#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x55
#define I2C_TIMEOUT 1000
#define I2C_RETRIES 1
#define I2C_DELAY 1000000

#define SENSOR_INIT_RETRIES 10
#define SENSOR_INIT_DELAY 1000000

#define SENSOR_READ_RETRIES 10
#define SENSOR_READ_DELAY 1000000

#define SENSOR_ERROR_OK 0
#define SENSOR_ERROR_READ 1
#define SENSOR_ERROR_UNINITIALIZED 2

#define LOG_FILE "biometric_log.csv"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd;
static FILE *log_file;

static void cleanup(void)
{
    if (chip)
        gpiod_chip_close(chip);
    if (line)
        gpiod_line_release(line);
    if (i2c_fd >= 0)
        close(i2c_fd);
    if (log_file)
        fclose(log_file);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_i2c(void)
{
    int ret;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_TIMEOUT, I2C_TIMEOUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C timeout: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_RETRIES, I2C_RETRIES);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C retries: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int init_sensor(void)
{
    int ret;
    uint8_t data[2];

    for (int i = 0; i < SENSOR_INIT_RETRIES; i++) {
        ret = read(i2c_fd, data, sizeof(data));
        if (ret == sizeof(data))
            return 0;
        usleep(SENSOR_INIT_DELAY);
    }

    fprintf(stderr, "Failed to initialize sensor\n");
    return -1;
}

static int read_sensor(uint16_t *ir, uint16_t *red)
{
    int ret;
    uint8_t data[4];

    for (int i = 0; i < SENSOR_READ_RETRIES; i++) {
        ret = read(i2c_fd, data, sizeof(data));
        if (ret == sizeof(data)) {
            *ir = (data[0] << 8) | data[1];
            *red = (data[2] << 8) | data[3];
            return 0;
        }
        usleep(SENSOR_READ_DELAY);
    }

    fprintf(stderr, "Failed to read sensor\n");
    return -1;
}

static int log_sample(uint16_t ir, uint16_t red)
{
    int ret;
    struct timespec ts;
    uint64_t timestamp;

    ret = clock_gettime(CLOCK_REALTIME, &ts);
    if (ret < 0) {
        fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
        return -1;
    }

    timestamp = (uint64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;

    ret = fprintf(log_file, "%llu,%u,%u,%d\n", timestamp, ir, red, SENSOR_ERROR_OK);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);

    return 0;
}

int main(void)
{
    int ret;
    uint16_t ir, red;

    atexit(cleanup);
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 25);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line value: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = init_i2c();
    if (ret < 0)
        return EXIT_FAILURE;

    ret = init_sensor();
    if (ret < 0)
        return EXIT_FAILURE;

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,ir,red,error\n");

    while (1) {
        ret = read_sensor(&ir, &red);
        if (ret < 0) {
            ret = log_sample(0, 0);
            if (ret < 0)
                return EXIT_FAILURE;
        } else {
            ret = log_sample(ir, red);
            if (ret < 0)
                return EXIT_FAILURE;
        }

        usleep(I2C_DELAY);
    }

    return EXIT_SUCCESS;
}

