#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define SPI_DELAY 0
#define SPI_CHANNEL 0
#define SPI_MAX_VALUE 1023
#define SPI_MAX_BYTES 3
#define SPI_MAX_READINGS 1000000
#define SPI_READING_INTERVAL 60
#define SPI_READING_FILE "moisture_log.txt"

static volatile int running = 1;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

int main(void) {
    int fd, ret;
    uint8_t tx[SPI_MAX_BYTES] = {0};
    uint8_t rx[SPI_MAX_BYTES] = {0};
    uint16_t value;
    FILE *fp;
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];

    // Open SPI device
    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode and speed
    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Error setting SPI mode");
        return -1;
    }
    ret = ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Error setting SPI mode");
        return -1;
    }
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Error setting SPI speed");
        return -1;
    }
    ret = ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Error setting SPI speed");
        return -1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open file for writing
    fp = fopen(SPI_READING_FILE, "a");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read and write SPI data in an infinite loop
    while (running) {
        // Construct SPI transfer message
        tx[0] = 0x01;
        tx[1] = (SPI_CHANNEL << 4) | 0x08;
        tx[2] = 0x00;

        // Transfer SPI message
        ret = write(fd, tx, SPI_MAX_BYTES);
        if (ret < 0) {
            perror("Error writing to SPI device");
            return -1;
        }
        ret = read(fd, rx, SPI_MAX_BYTES);
        if (ret < 0) {
            perror("Error reading from SPI device");
            return -1;
        }

        // Extract ADC value from received message
        value = ((rx[1] & 0x03) << 8) | rx[2];

        // Check if value is within valid range
        if (value > SPI_MAX_VALUE) {
            fprintf(stderr, "Error: ADC value out of range\n");
            return -1;
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = gmtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm);

        // Write timestamp and value to file
        fprintf(fp, "%s,%d\n", timestamp, value);

        // Wait for next reading
        sleep(SPI_READING_INTERVAL);
    }

    // Close SPI device and file
    close(fd);
    fclose(fp);

    return 0;
}

