#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define SPI_CHANNEL 0
#define SPI_START_BIT 0x01
#define SPI_SINGLE_ENDED 0x80
#define SPI_DUMMY_BYTE 0x00
#define SPI_MAX_RETRIES 3
#define BUZZER_PIN 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define FLAME_LOG_FILE "flame_log.txt"
#define FLAME_TEMP_COMPENSATION 0.004
#define FLAME_TEMP_THRESHOLD 100.0
#define FLAME_VOLTAGE_THRESHOLD 0.5
#define FLAME_DETECTED_MSG "Flame detected"
#define FLAME_NOT_DETECTED_MSG "Flame not detected"

int main(int argc, char *argv[])
{
    int spi_fd, ret, i;
    uint8_t tx_buf[3], rx_buf[3];
    uint16_t adc_value;
    double voltage, compensated_voltage, ambient_temp, flame_temp;
    FILE *ambient_temp_file, *flame_log_file;
    struct spi_ioc_transfer spi_xfer;
    struct timespec ts;
    char flame_detected_msg[100], flame_not_detected_msg[100];

    // Initialize SPI
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0)
    {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0)
    {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0)
    {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0)
    {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error initializing pigpio\n");
        close(spi_fd);
        return -1;
    }

    // Initialize buzzer
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, PI_OFF);

    // Initialize ambient temperature file
    ambient_temp_file = fopen(AMBIENT_TEMP_FILE, "r");
    if (ambient_temp_file == NULL)
    {
        fprintf(stderr, "Error opening ambient temperature file: %s\n", strerror(errno));
        gpioTerminate();
        close(spi_fd);
        return -1;
    }

    // Read ambient temperature
    if (fscanf(ambient_temp_file, "%lf", &ambient_temp) != 1)
    {
        fprintf(stderr, "Error reading ambient temperature from file\n");
        fclose(ambient_temp_file);
        gpioTerminate();
        close(spi_fd);
        return -1;
    }

    fclose(ambient_temp_file);

    // Initialize flame log file
    flame_log_file = fopen(FLAME_LOG_FILE, "a");
    if (flame_log_file == NULL)
    {
        fprintf(stderr, "Error opening flame log file: %s\n", strerror(errno));
        gpioTerminate();
        close(spi_fd);
        return -1;
    }

    // Initialize SPI transfer structure
    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.tx_buf = (unsigned long)tx_buf;
    spi_xfer.rx_buf = (unsigned long)rx_buf;
    spi_xfer.len = 3;
    spi_xfer.delay_usecs = SPI_DELAY;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = SPI_BITS;

    // Initialize message buffers
    snprintf(flame_detected_msg, sizeof(flame_detected_msg), "%s", FLAME_DETECTED_MSG);
    snprintf(flame_not_detected_msg, sizeof(flame_not_detected_msg), "%s", FLAME_NOT_DETECTED_MSG);

    // Main loop
    while (1)
    {
        // Read ADC value
        for (i = 0; i < SPI_MAX_RETRIES; i++)
        {
            tx_buf[0] = SPI_START_BIT;
            tx_buf[1] = SPI_SINGLE_ENDED | (SPI_CHANNEL << 4);
            tx_buf[2] = SPI_DUMMY_BYTE;

            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer);
            if (ret < 0)
            {
                fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
                fprintf(flame_log_file, "Error reading ADC value: %s\n", strerror(errno));
                gpioWrite(BUZZER_PIN, PI_OFF);
                break;
            }

            adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            if (adc_value >= 0 && adc_value <= 1023)
            {
                break;
            }
        }

        if (i == SPI_MAX_RETRIES)
        {
            fprintf(stderr, "Error reading ADC value: Maximum number of retries reached\n");
            fprintf(flame_log_file, "Error reading ADC value: Maximum number of retries reached\n");
            gpioWrite(BUZZER_PIN, PI_OFF);
            continue;
        }

        // Calculate voltage
        voltage = (double)adc_value * 3.3 / 1023.0;

        // Calculate compensated voltage
        compensated_voltage = voltage + FLAME_TEMP_COMPENSATION * (ambient_temp - 25.0);

        // Calculate flame temperature
        flame_temp = compensated_voltage * 1000.0 / 10.0;

        // Log data
