            fprintf(stderr, "Error reading ADC value: Maximum number of retries reached\n");
            fprintf(flame_log_file, "Error reading ADC value: Maximum number of retries reached\n");
            gpioWrite(BUZZER_PIN, PI_OFF);
            continue;
        }

        // Calculate voltage
        voltage = (double)adc_value * 3.3 / 1023.0;

        // Calculate compensated voltage
        compensated_voltage = voltage + FLAME_TEMP_COMPENSATION * (ambient_temp - 25.0);

        // Calculate flame temperature
        flame_temp = compensated_voltage * 1000.0 / 10.0;

        // Log data
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(flame_log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.1f,%s\n",
                ts.tv_sec / 31556926 % 100 + 1900, ts.tv_sec / 2629743 % 12 + 1, ts.tv_sec / 86400 % 31 + 1,
                ts.tv_sec / 3600 % 24, ts.tv_sec / 60 % 60, ts.tv_sec % 60,
                adc_value, voltage, compensated_voltage, flame_temp,
                flame_temp >= FLAME_TEMP_THRESHOLD ? flame_detected_msg : flame_not_detected_msg);
        fflush(flame_log_file);

        // Turn buzzer on if flame detected
        if (flame_temp >= FLAME_TEMP_THRESHOLD)
        {
            gpioWrite(BUZZER_PIN, PI_ON);
        }
        else
        {
            gpioWrite(BUZZER_PIN, PI_OFF);
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close files and release resources
    fclose(flame_log_file);
    gpioTerminate();
    close(spi_fd);

    return 0;
}
```

### Explanation:

- The program starts by initializing the SPI device and configuring it with the specified mode, speed, and bits per word.
- The program then initializes the pigpio library and sets the buzzer pin as an output.
- The program reads the ambient temperature from a file and uses it to calculate the compensation factor for the flame temperature.
- The program opens a log file for writing the flame data.
- The program enters a loop that reads the ADC value from the MCP3008, calculates the voltage, compensates it for the ambient temperature, and calculates the flame temperature.
- The program logs the data to the log file and turns the buzzer on if the flame temperature is above the threshold.
- The program sleeps for 500 ms before reading the next ADC value.
- The program handles SIGINT (Ctrl+C) gracefully by stopping the loop, turning the buzzer off, closing the log file, and releasing all resources.

