#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "soil_moisture.log"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SPI_DELAY 0
#define SPI_MAX_VALUE 1023
#define SPI_MAX_MOISTURE 100

static int spi_fd = -1;
static FILE *log_file = NULL;

static void cleanup(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_spi(void)
{
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

static int read_spi(uint8_t *buf, size_t len)
{
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)buf;
    xfer.rx_buf = (unsigned long)buf;
    xfer.len = len;
    xfer.delay_usecs = SPI_DELAY;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
}

static int read_adc(uint16_t *value)
{
    uint8_t buf[3];
    int ret;

    buf[0] = 0x01;
    buf[1] = (SPI_CHANNEL << 4) & 0x70;
    buf[2] = 0x00;

    ret = read_spi(buf, sizeof(buf));
    if (ret < 0) {
        perror("read_spi");
        return -1;
    }

    *value = ((buf[1] & 0x03) << 8) | buf[2];
    return 0;
}

static int read_moisture(uint16_t *value)
{
    uint16_t adc_value;
    int ret;

    ret = read_adc(&adc_value);
    if (ret < 0) {
        return -1;
    }

    *value = (adc_value * SPI_MAX_MOISTURE) / SPI_MAX_VALUE;
    return 0;
}

static int log_moisture(uint16_t value)
{
    time_t now;
    struct tm *tm;
    char buf[128];
    int ret;

    now = time(NULL);
    tm = localtime(&now);
    if (tm == NULL) {
        perror("localtime");
        return -1;
    }

    ret = strftime(buf, sizeof(buf), "%FT%T%z", tm);
    if (ret == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    ret = fprintf(log_file, "%s %u%%\n", buf, value);
    if (ret < 0) {
        perror("fprintf");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[])
{
    uint16_t value;
    int ret;
    int interval = 1;

    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval\n");
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    ret = init_spi();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (true) {
        ret = read_moisture(&value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read moisture\n");
            continue;
        }

        ret = log_moisture(value);
        if (ret < 0) {
            fprintf(stderr, "Failed to log moisture\n");
            continue;
        }

        sleep(interval);
    }

    cleanup();
    return EXIT_SUCCESS;
}

