#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_DELAY 0
#define SPI_CHANNEL 0
#define SPI_CONFIG_BYTE 0x01
#define SPI_DUMMY_BYTE 0x00
#define SPI_READ_CMD_SIZE 3
#define SPI_READ_DATA_SIZE 2
#define SPI_READ_CMD_START_BIT 0x01
#define SPI_READ_CMD_SINGLE_ENDED_BIT 0x80
#define SPI_READ_CMD_CHANNEL_BITS 0x70
#define SPI_READ_CMD_CHANNEL_SHIFT 4
#define SPI_READ_CMD_DUMMY_BYTE 0x00
#define SPI_READ_DATA_MSB_MASK 0x03
#define SPI_READ_DATA_MSB_SHIFT 6
#define SPI_READ_DATA_LSB_MASK 0xFF
#define SPI_READ_DATA_LSB_SHIFT 0
#define SPI_READ_DATA_MAX_VALUE 1023
#define SPI_READ_DATA_MIN_VALUE 0
#define SPI_READ_DATA_MAX_PERCENTAGE 100
#define SPI_READ_DATA_MIN_PERCENTAGE 0

static volatile int running = 1;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

int main(void) {
    int fd;
    uint8_t tx[SPI_READ_CMD_SIZE] = {0};
    uint8_t rx[SPI_READ_DATA_SIZE] = {0};
    uint16_t value;
    uint8_t percentage;

    // Open SPI device
    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return EXIT_FAILURE;
    }

    // Configure SPI mode
    int ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure SPI bits per word
    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure SPI max speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure SPI delay
    ret = ioctl(fd, SPI_IOC_WR_DELAY_USEC, &SPI_DELAY);
    if (ret == -1) {
        perror("Error setting SPI delay");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (running) {
        // Build SPI read command
        tx[0] = SPI_READ_CMD_START_BIT | SPI_READ_CMD_SINGLE_ENDED_BIT | ((SPI_CHANNEL << SPI_READ_CMD_CHANNEL_SHIFT) & SPI_READ_CMD_CHANNEL_BITS);
        tx[1] = SPI_READ_CMD_DUMMY_BYTE;
        tx[2] = SPI_READ_CMD_DUMMY_BYTE;

        // Transfer SPI read command and receive data
        ret = write(fd, tx, SPI_READ_CMD_SIZE);
        if (ret != SPI_READ_CMD_SIZE) {
            perror("Error writing to SPI device");
            close(fd);
            return EXIT_FAILURE;
        }

        ret = read(fd, rx, SPI_READ_DATA_SIZE);
        if (ret != SPI_READ_DATA_SIZE) {
            perror("Error reading from SPI device");
            close(fd);
            return EXIT_FAILURE;
        }

        // Compute value
        value = ((rx[0] & SPI_READ_DATA_MSB_MASK) << SPI_READ_DATA_MSB_SHIFT) | ((rx[1] & SPI_READ_DATA_LSB_MASK) << SPI_READ_DATA_LSB_SHIFT);

        // Clamp value to range
        if (value > SPI_READ_DATA_MAX_VALUE) {
            value = SPI_READ_DATA_MAX_VALUE;
        } else if (value < SPI_READ_DATA_MIN_VALUE) {
            value = SPI_READ_DATA_MIN_VALUE;
        }

        // Compute percentage
        percentage = (value * SPI_READ_DATA_MAX_PERCENTAGE) / SPI_READ_DATA_MAX_VALUE;

        // Print percentage
        printf("Moisture percentage: %d%%\n", percentage);

        // Wait 5 seconds
        sleep(5);
    }

    // Close SPI device
    close(fd);

    return EXIT_SUCCESS;
}

