#define RELAY_ACTIVE_HIGH 1

#define DEFAULT_THRESHOLD 0.3
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60

#define LOG_FILE "irrigation.log"

static int spi_fd = -1;
static int relay_fd = -1;
static int log_fd = -1;

static double threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP;

static void log_message(const char *message)
{
    if (log_fd < 0) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char time_str[64];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

    dprintf(log_fd, "%s: %s\n", time_str, message);
}

static void close_spi(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

static void close_relay(void)
{
    if (relay_fd >= 0) {
        close(relay_fd);
        relay_fd = -1;
    }
}

static void close_log(void)
{
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

static void close_all(void)
{
    close_spi();
    close_relay();
    close_log();
}

static void handle_signal(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("Received signal, turning off relay");
        if (relay_fd >= 0) {
            write(relay_fd, "0", 1);
        }
    }

    close_all();
    exit(0);
}

static void setup_signal_handlers(void)
{
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);
}

static int open_spi(void)
{
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

