static int read_spi(uint8_t *data, size_t len)
{
    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)data;
    transfer.rx_buf = (unsigned long)data;
    transfer.len = len;
    transfer.delay_usecs = SPI_DELAY;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = SPI_BITS;

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_mcp3008(uint8_t channel, uint16_t *value)
{
    uint8_t data[3] = {0};
    data[0] = 0x01;
    data[1] = (channel << 4) | 0x08;

    int ret = read_spi(data, ARRAY_SIZE(data));
    if (ret < 0) {
        return -1;
    }

    *value = ((data[1] & 0x03) << 8) | data[2];
    return 0;
}

