static int relay_fd = -1;
static int log_fd = -1;

static double threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP;

static void log_message(const char *message)
{
    if (log_fd < 0) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char time_str[64];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

    dprintf(log_fd, "%s: %s\n", time_str, message);
}

static void close_spi(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

static void close_relay(void)
{
    if (relay_fd >= 0) {
        close(relay_fd);
        relay_fd = -1;
    }
}

static void close_log(void)
{
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

static void close_all(void)
{
    close_spi();
    close_relay();
    close_log();
}

static void handle_signal(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("Received signal, turning off relay");
        if (relay_fd >= 0) {
            write(relay_fd, "0", 1);
        }
    }

    close_all();
    exit(0);
}

static void setup_signal_handlers(void)
{
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);
}

static int open_spi(void)
{
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int open_relay(void)
{
    relay_fd = open("/sys/class/gpio/gpio18/value", O_WRONLY);
    if (relay_fd < 0) {
        fprintf(stderr, "Failed to open relay GPIO: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_spi(uint8_t *data, size_t len)
{
    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)data;
    transfer.rx_buf = (unsigned long)data;
    transfer.len = len;
    transfer.delay_usecs = SPI_DELAY;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = SPI_BITS;

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_mcp3008(uint8_t channel, uint16_t *value)
{
    uint8_t data[3] = {0};
    data[0] = 0x01;
    data[1] = (channel << 4) | 0x08;

    int ret = read_spi(data, ARRAY_SIZE(data));
    if (ret < 0) {
        return -1;
    }

    *value = ((data[1] & 0x03) << 8) | data[2];
    return 0;
}

static double convert_to_voltage(uint16_t value)
{
    return (double)value * MCP3008_VREF / MCP3008_RESOLUTION;
}

static int read_moisture(double *moisture)
{
    uint16_t value;
    int ret = read_mcp3008(MCP3008_CHANNEL, &value);
    if (ret < 0) {
        return -1;
    }

    *moisture = convert_to_voltage(value);
    return 0;
}

static int activate_relay(void)
{
    if (relay_fd < 0) {
        return -1;
    }

    int ret = write(relay_fd, RELAY_ACTIVE_HIGH ? "1" : "0", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to activate relay: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int deactivate_relay(void)
{
    if (relay_fd < 0) {
        return -1;
    }

    int ret = write(relay_fd, RELAY_ACTIVE_HIGH ? "0" : "1", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to deactivate relay: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void print_usage(const char *program_name)
{
    fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep]\n", program_name);
}

