            }
            break;
        default:
            print_usage(argv[0]);
            return -1;
        }
    }

    return 0;
}

int main(int argc, char *argv[])
{
    if (parse_options(argc, argv) < 0) {
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    if (open_spi() < 0) {
        return EXIT_FAILURE;
