    uint8_t tx_buf[SPI_MAX_BYTES] = {0};
    uint8_t rx_buf[SPI_MAX_BYTES] = {0};

    tx_buf[0] = 0x01;
    tx_buf[1] = (SPI_CHANNEL << 6) & 0x70;
    tx_buf[2] = 0x00;

    ret = write(spi_fd, tx_buf, SPI_MAX_BYTES);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = read(spi_fd, rx_buf, SPI_MAX_BYTES);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(errno));
        return -1;
    }

    *value = ((rx_buf[1] & 0x0F) << 8) | rx_buf[2];

    return 0;
}

