        return -1;
    }

    ret = snprintf(line, LOG_MAX_LINE, line_format, timestamp, value_str);
    if (ret < 0) {
        fprintf(stderr, "Failed to format line: %s\n", strerror(errno));
        return -1;
    }

    ret = fputs(line, log_fp);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    ret = fflush(log_fp);
    if (ret < 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_deinit(void)
{
    int ret;

    ret = fclose(log_fp);
    if (ret < 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int ret;
    uint16_t value;
    uint16_t threshold = 0;
    struct timeval tv;

    ret = spi_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = log_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize log: %s\n", strerror(errno));
        return -1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        ret = spi_read(&value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from SPI: %s\n", strerror(errno));
            break;
        }

        if (value > threshold) {
            ret = log_write(value);
            if (ret < 0) {
                fprintf(stderr, "Failed to write to log: %s\n", strerror(errno));
                break;
            }

            threshold = value + SPI_MAX_THRESHOLD;
        }

        tv.tv_sec = 0;
        tv.tv_usec = 10000;
        ret = select(0, NULL, NULL, NULL, &tv);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait: %s\n", strerror(errno));
            break;
        }
    }

    ret = log_deinit();
    if (ret < 0) {
        fprintf(stderr, "Failed to deinitialize log: %s\n", strerror(errno));
        return -1;
    }

    ret = spi_deinit();
    if (ret < 0) {
        fprintf(stderr, "Failed to deinitialize SPI: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

