#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_CHANNEL 0
#define SPI_DELAY 0
#define GPIO_PIN 18
#define GPIO_DELAY 10000
#define THRESHOLD 300
#define LOG_FILE "watering_events.txt"

static volatile int running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

static int init_spi(int *fd)
{
    int ret;

    *fd = open(SPI_DEV, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        return -1;
    }

    return 0;
}

static int read_spi(int fd, uint8_t *buf, size_t len)
{
    struct spi_ioc_transfer xfer;

    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)buf;
    xfer.rx_buf = (unsigned long)buf;
    xfer.len = len;
    xfer.delay_usecs = SPI_DELAY;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;

    return ioctl(fd, SPI_IOC_MESSAGE(1), &xfer);
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return -1;
    }

    return 0;
}

static void water_plant(void)
{
    gpioWrite(GPIO_PIN, 1);
    usleep(GPIO_DELAY);
    gpioWrite(GPIO_PIN, 0);
}

static void log_event(int moisture)
{
    FILE *fp;
    time_t t;
    struct tm *tm;
    char buf[64];

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    t = time(NULL);
    tm = localtime(&t);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %d\n", buf, moisture);
    fclose(fp);
}

int main(void)
{
    int fd, ret;
    uint8_t buf[3];
    uint16_t moisture;

    if (init_spi(&fd) < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        buf[0] = 0x01;
        buf[1] = (SPI_CHANNEL << 4) & 0x70;
        buf[2] = 0x00;

        ret = read_spi(fd, buf, sizeof(buf));
        if (ret < 0) {
            fprintf(stderr, "Failed to read SPI\n");
            break;
        }

        moisture = ((buf[1] & 0x03) << 8) | buf[2];

        if (moisture < THRESHOLD) {
            water_plant();
            log_event(moisture);
        }

        sleep(60);
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    close(fd);

    return EXIT_SUCCESS;
}
