#define SPI_DEV "/dev/spidev0.0"
#define GPIO_DEV "/dev/gpiochip0"
#define GPIO_LINE 8
#define LOG_FILE "audio_log.txt"
#define SAMPLE_RATE 1000
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE)

static int spi_fd = -1;
static int gpio_fd = -1;
static int log_fd = -1;

static void cleanup(void)
{
    if (gpio_fd >= 0) {
        ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, GPIO_LINE);
        gpio_fd = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    struct spi_ioc_transfer spi_xfer;
    struct timespec ts;
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3];
    uint32_t sample;
    char log_line[32];
    int ret;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        goto error;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, 0);
    if (ret < 0) {
        perror("ioctl");
        goto error;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8);
    if (ret < 0) {
        perror("ioctl");
        goto error;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000);
    if (ret < 0) {
        perror("ioctl");
        goto error;
    }

    gpio_fd = open(GPIO_DEV, O_RDWR);
    if (gpio_fd < 0) {
        perror("open");
        goto error;
    }

    ret = ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, GPIO_LINE);
    if (ret < 0) {
        perror("ioctl");
        goto error;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        goto error;
    }

    while (1) {
        ret = clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        if (ret < 0) {
            perror("clock_gettime");
            goto error;
        }

        ret = ioctl(gpio_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 0);
        if (ret < 0) {
            perror("ioctl");
            goto error;
        }

        spi_xfer.tx_buf = (unsigned long)tx_buf;
        spi_xfer.rx_buf = (unsigned long)rx_buf;
        spi_xfer.len = 3;
        spi_xfer.speed_hz = 1000000;
        spi_xfer.delay_usecs = 0;
        spi_xfer.bits_per_word = 8;
        spi_xfer.cs_change = 0;
        spi_xfer.pad = 0;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer);
        if (ret < 0) {
            perror("ioctl");
            goto error;
        }

        ret = ioctl(gpio_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 1);
        if (ret < 0) {
            perror("ioctl");
            goto error;
        }

        sample = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        ret = snprintf(log_line, sizeof(log_line), "%ld.%09ld|%u\n", ts.tv_sec, ts.tv_nsec, sample);
        if (ret < 0) {
            perror("snprintf");
            goto error;
        }

        ret = write(log_fd, log_line, strlen(log_line));
        if (ret < 0) {
            perror("write");
            goto error;
        }

        ret = fsync(log_fd);
        if (ret < 0) {
            perror("fsync");
            goto error;
        }

        ts.tv_nsec += SAMPLE_PERIOD_NS;
        ret = clock_nanosleep(CLOCK_MONOTONIC_RAW, TIMER_ABSTIME, &ts, NULL);
        if (ret < 0) {
            perror("clock_nanosleep");
            goto error;
        }
    }

    cleanup();
    return EXIT_SUCCESS;

error:
    cleanup();
    return EXIT_FAILURE;
}

