#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <unistd.h>

#define SPI_PATH "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_DELAY 0
#define SPI_CHANNEL 0
#define SPI_MAX_CHANNEL 2
#define SPI_MAX_VALUE 1023
#define SPI_MAX_READINGS 3
#define SPI_READING_DELAY 1000000
#define CSV_FILE "sensor_data.csv"

static int spi_fd = -1;
static FILE *csv_file = NULL;

static void spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits_per_word = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;
    uint16_t delay = SPI_DELAY;

    spi_fd = open(SPI_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &delay) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_LSB_FIRST, &delay) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

static void spi_read(uint8_t channel, uint16_t *value)
{
    uint8_t tx[3] = {0};
    uint8_t rx[3] = {0};

    tx[0] = 1;
    tx[1] = (channel << 4) | 8;

    if (write(spi_fd, tx, sizeof(tx)) != sizeof(tx)) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    if (read(spi_fd, rx, sizeof(rx)) != sizeof(rx)) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    *value = ((rx[1] & 3) << 8) | rx[2];
}

