#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <mosquitto.h>
#include "json.h"
#include "gpio.h"

#define MAX_RECONNECT_BACKOFF 60
#define MAX_RECONNECT_ATTEMPTS 10

static struct mosquitto *mosq = NULL;
static int reconnect_attempts = 0;
static int reconnect_backoff = 1;
static bool led_state = false;

static void on_connect(struct mosquitto *mosq, void *obj, int rc)
{
    if (rc == 0) {
        reconnect_attempts = 0;
        reconnect_backoff = 1;
        mosquitto_subscribe(mosq, NULL, "home/led_control", 0);
    } else {
        fprintf(stderr, "%s: failed to connect to MQTT broker: %s\n", __func__, mosquitto_connack_string(rc));
        if (reconnect_attempts < MAX_RECONNECT_ATTEMPTS) {
            reconnect_attempts++;
            reconnect_backoff *= 2;
            if (reconnect_backoff > MAX_RECONNECT_BACKOFF)
                reconnect_backoff = MAX_RECONNECT_BACKOFF;
            fprintf(stderr, "%s: reconnecting in %d seconds...\n", __func__, reconnect_backoff);
            sleep(reconnect_backoff);
            mosquitto_reconnect(mosq);
        } else {
            fprintf(stderr, "%s: giving up after %d attempts\n", __func__, reconnect_attempts);
            exit(EXIT_FAILURE);
        }
    }
}

static void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg)
{
    if (msg->payloadlen == 0) {
        fprintf(stderr, "%s: received empty message\n", __func__);
        return;
    }
    if (msg->payloadlen > 1024) {
        fprintf(stderr, "%s: received message too long\n", __func__);
        return;
    }
    char *payload = malloc(msg->payloadlen + 1);
    if (payload == NULL) {
        fprintf(stderr, "%s: out of memory\n", __func__);
        return;
    }
    memcpy(payload, msg->payload, msg->payloadlen);
    payload[msg->payloadlen] = '\0';
    struct json_object *json = json_parse(payload);
    if (json == NULL) {
        fprintf(stderr, "%s: failed to parse JSON payload\n", __func__);
        free(payload);
        return;
    }
    struct json_object *led_state_obj = json_object_get(json, "led_state");
    if (led_state_obj == NULL) {
        fprintf(stderr, "%s: missing \"led_state\" key\n", __func__);
        json_object_free(json);
        free(payload);
        return;
    }
    if (led_state_obj->type != JSON_TYPE_BOOLEAN) {
        fprintf(stderr, "%s: \"led_state\" is not a boolean\n", __func__);
        json_object_free(json);
        free(payload);
        return;
    }
    led_state = led_state_obj->value.boolean;
    gpio_set_value(17, led_state);
    json_object_free(json);
    free(payload);
}

static void on_disconnect(struct mosquitto *mosq, void *obj, int rc)
{
    if (rc != 0) {
        fprintf(stderr, "%s: unexpected disconnection from MQTT broker: %s\n", __func__, mosquitto_connack_string(rc));
        if (reconnect_attempts < MAX_RECONNECT_ATTEMPTS) {
            reconnect_attempts++;
            reconnect_backoff *= 2;
            if (reconnect_backoff > MAX_RECONNECT_BACKOFF)
                reconnect_backoff = MAX_RECONNECT_BACKOFF;
            fprintf(stderr, "%s: reconnecting in %d seconds...\n", __func__, reconnect_backoff);
            sleep(reconnect_backoff);
            mosquitto_reconnect(mosq);
        } else {
            fprintf(stderr, "%s: giving up after %d attempts\n", __func__, reconnect_attempts);
            exit(EXIT_FAILURE);
        }
    }
}

static void on_signal(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        mosquitto_disconnect(mosq);
        gpio_set_value(17, false);
        gpio_free(17);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        exit(EXIT_SUCCESS);
    }
}

int main(void)
{
    if (gpio_request(17, "led_control") != 0) {
        fprintf(stderr, "%s: failed to request GPIO17\n", __func__);
        return EXIT_FAILURE;
    }
    if (gpio_direction_output(17, false) != 0) {
        fprintf(stderr, "%s: failed to set GPIO17 direction\n", __func__);
        gpio_free(17);
        return EXIT_FAILURE;
    }
    if (mosquitto_lib_init() != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "%s: failed to initialize mosquitto library\n", __func__);
        gpio_free(17);
        return EXIT_FAILURE;
    }
    mosq = mosquitto_new("rpi_led_control", true, NULL);
    if (mosq == NULL) {
        fprintf(stderr, "%s: failed to create mosquitto client\n", __func__);
        gpio_free(17);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);
    mosquitto_connect(mosq, "mqtt.eclipseprojects.io", 1883, 60);
    mosquitto_loop_forever(mosq, -1, 1);
    return EXIT_SUCCESS;
}

