#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "soil_moisture.log"
#define MOISTURE_THRESHOLD 20
#define RELAY_GPIO 17
#define RELAY_GPIO_PATH "/sys/class/gpio/gpio17"
#define RELAY_GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define RELAY_GPIO_DIRECTION_PATH "/sys/class/gpio/gpio17/direction"
#define RELAY_GPIO_VALUE_PATH "/sys/class/gpio/gpio17/value"
#define RELAY_GPIO_ACTIVE_HIGH 1

static int spi_fd = -1;
static int log_fd = -1;
static int relay_gpio_fd = -1;

static void cleanup(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
    if (relay_gpio_fd >= 0) {
        close(relay_gpio_fd);
        relay_gpio_fd = -1;
    }
}

static int init_spi(void)
{
    int ret;
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    uint8_t tx[3] = {0};
    uint8_t rx[3] = {0};

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret < 0) {
        perror("Failed to get SPI mode");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("Failed to get SPI bits per word");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("Failed to get SPI speed");
        return -1;
    }

    tx[0] = 0x01;
    tx[1] = 0x80;
    tx[2] = 0x00;

    ret = write(spi_fd, tx, 3);
    if (ret < 0) {
        perror("Failed to write to SPI device");
        return -1;
    }

    ret = read(spi_fd, rx, 3);
    if (ret < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    return 0;
}

static int read_adc(uint8_t channel)
{
    int ret;
    uint8_t tx[3] = {0};
    uint8_t rx[3] = {0};

    tx[0] = 0x01;
    tx[1] = (0x08 | (channel & 0x07)) << 4;
    tx[2] = 0x00;

    ret = write(spi_fd, tx, 3);
    if (ret < 0) {
        perror("Failed to write to SPI device");
        return -1;
    }

    ret = read(spi_fd, rx, 3);
    if (ret < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int init_log(void)
{
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return -1;
    }

    return 0;
}

static int init_relay_gpio(void)
{
    int ret;
    char buf[10];

    relay_gpio_fd = open(RELAY_GPIO_EXPORT_PATH, O_WRONLY);
    if (relay_gpio_fd < 0) {
        perror("Failed to open GPIO export file");
        return -1;
    }

    ret = write(relay_gpio_fd, "17", 2);
    if (ret < 0) {
        perror("Failed to export GPIO");
        return -1;
    }

    close(relay_gpio_fd);
    relay_gpio_fd = -1;

    relay_gpio_fd = open(RELAY_GPIO_DIRECTION_PATH, O_WRONLY);
    if (relay_gpio_fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    ret = write(relay_gpio_fd, "out", 3);
    if (ret < 0) {
        perror("Failed to set GPIO direction");
        return -1;
    }

    close(relay_gpio_fd);
    relay_gpio_fd = -1;

    relay_gpio_fd = open(RELAY_GPIO_VALUE_PATH, O_WRONLY);
    if (relay_gpio_fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    ret = write(relay_gpio_fd, "0", 1);
    if (ret < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }

    return 0;
}

static int set_relay_gpio(int value)
{
    int ret;
    char buf[10];

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        return -1;
    }

    ret = write(relay_gpio_fd, buf, sprintf(buf, "%d", value));
    if (ret < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }

    return 0;
}

static int log_sample(int moisture_percentage, int pump_status)
{
    int ret;
    char buf[100];
    time_t t;
    struct tm *tm;

    t = time(NULL);
    tm = localtime(&t);

    ret = write(log_fd, buf, sprintf(buf, "%04d-%02d-%02d %02d:%02d:%02d, %d%%, %s\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, moisture_percentage, pump_status ? "ON" : "OFF"));
    if (ret < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    return 0;
}

static void sigint_handler(int signum)
{
    if (signum == SIGINT) {
        set_relay_gpio(0);
        cleanup();
        exit(0);
    }
}

int main(void)
{
    int ret;
    int adc_value;
    int moisture_percentage;
    int pump_status = 0;

    ret = init_spi();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return -1;
    }

    ret = init_log();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize log file\n");
        return -1;
    }

    ret = init_relay_gpio();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO\n");
        return -1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            return -1;
        }

        moisture_percentage = (adc_value * 100) / 1023;

        if (moisture_percentage < MOISTURE_THRESHOLD) {
            if (!pump_status) {
                ret = set_relay_gpio(RELAY_GPIO_ACTIVE_HIGH);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set relay GPIO\n");
                    return -1;
                }
                pump_status = 1;
            }
        } else {
            if (pump_status) {
                ret = set_relay_gpio(0);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set relay GPIO\n");
                    return -1;
                }
                pump_status = 0;
            }
        }

        ret = log_sample(moisture_percentage, pump_status);
        if (ret < 0) {
            fprintf(stderr, "Failed to log sample\n");
            return -1;
        }

        sleep(60);
    }

    return 0;
}

