#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_DEV "/sys/class/gpio/gpio17"
#define LOG_FILE "current_log.txt"

#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000

#define GPIO_EXPORT "/sys/class/gpio/export"
#define GPIO_DIR "/sys/class/gpio/gpio17/direction"
#define GPIO_VAL "/sys/class/gpio/gpio17/value"

#define GPIO_OUT "out"
#define GPIO_HIGH "1"
#define GPIO_LOW "0"

#define ADC_CHANNEL 0
#define ADC_VREF 5.0
#define ADC_RESOLUTION 1024
#define ADC_GAIN 1.0

#define CURRENT_SENSITIVITY 0.1

#define TIMESTAMP_LEN 20

#define LOG_LINE_LEN 100

#define EXIT_SUCCESS 0
#define EXIT_FAILURE 1

#define TRUE 1
#define FALSE 0

int spi_fd;
int gpio_fd;
FILE *log_file;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM)
    {
        printf("Received signal %d, cleaning up...\n", signo);

        // Close the SPI device
        if (spi_fd != -1)
        {
            close(spi_fd);
        }

        // Close the GPIO line
        if (gpio_fd != -1)
        {
            close(gpio_fd);
        }

        // Close the log file
        if (log_file != NULL)
        {
            fclose(log_file);
        }

        exit(EXIT_SUCCESS);
    }
}

int main(void)
{
    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0)
    {
        perror("Error opening SPI device");
        return EXIT_FAILURE;
    }

    // Configure the SPI device
    struct spi_ioc_transfer spi_xfer;
    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.tx_buf = (unsigned long)&spi_xfer;
    spi_xfer.rx_buf = (unsigned long)&spi_xfer;
    spi_xfer.len = 3;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = SPI_BITS;
    spi_xfer.delay_usecs = 0;

    // Export the GPIO line
    gpio_fd = open(GPIO_EXPORT, O_WRONLY);
    if (gpio_fd < 0)
    {
        perror("Error opening GPIO export file");
        return EXIT_FAILURE;
    }
    write(gpio_fd, "17", 2);
    close(gpio_fd);

    // Set the GPIO line direction
    gpio_fd = open(GPIO_DIR, O_WRONLY);
    if (gpio_fd < 0)
    {
        perror("Error opening GPIO direction file");
        return EXIT_FAILURE;
    }
    write(gpio_fd, GPIO_OUT, strlen(GPIO_OUT));
    close(gpio_fd);

    // Set the GPIO line value
    gpio_fd = open(GPIO_VAL, O_WRONLY);
    if (gpio_fd < 0)
    {
        perror("Error opening GPIO value file");
        return EXIT_FAILURE;
    }
    write(gpio_fd, GPIO_HIGH, strlen(GPIO_HIGH));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Main loop
    while (TRUE)
    {
        // Read the ADC value
        uint8_t tx_buf[3] = {0x01, 0x80 | (ADC_CHANNEL << 4), 0x00};
        uint8_t rx_buf[3] = {0x00, 0x00, 0x00};
        spi_xfer.tx_buf = (unsigned long)tx_buf;
        spi_xfer.rx_buf = (unsigned long)rx_buf;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0)
        {
            perror("Error reading from SPI device");
            return EXIT_FAILURE;
        }

        // Convert the ADC value to current
        uint16_t adc_value = (rx_buf[1] << 8) | rx_buf[2];
        double current = (adc_value * ADC_VREF / ADC_RESOLUTION / ADC_GAIN) / CURRENT_SENSITIVITY;

        // Get the current timestamp
        time_t now = time(NULL);
        char timestamp[TIMESTAMP_LEN];
        strftime(timestamp, TIMESTAMP_LEN, "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write the current value to the log file
        char log_line[LOG_LINE_LEN];
        snprintf(log_line, LOG_LINE_LEN, "%s,%.2f\n", timestamp, current);
        fputs(log_line, log_file);
        fflush(log_file);

        // Wait for one second
        sleep(1);
    }

    return EXIT_SUCCESS;
}

