#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define NUM_BUFFERS 4

struct buffer {
    void *start;
    size_t length;
};

static struct buffer *buffers;
static int fd;
static int streaming = 0;

static void stop_streaming(void)
{
    int i;

    if (!streaming)
        return;

    for (i = 0; i < NUM_BUFFERS; i++)
        if (-1 == v4l2_munmap(buffers[i].start, buffers[i].length))
            perror("munmap");

    if (-1 == v4l2_ioctl(fd, VIDIOC_STREAMOFF, NULL))
        perror("VIDIOC_STREAMOFF");

    streaming = 0;
}

static void start_streaming(void)
{
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf = {
            .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
            .memory = V4L2_MEMORY_MMAP,
            .index = i,
        };

        if (-1 == v4l2_ioctl(fd, VIDIOC_QBUF, &buf))
            perror("VIDIOC_QBUF");
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == v4l2_ioctl(fd, VIDIOC_STREAMON, &type))
        perror("VIDIOC_STREAMON");

    streaming = 1;
}

static void init_mmap(void)
{
    struct v4l2_requestbuffers req = {
        .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
        .memory = V4L2_MEMORY_MMAP,
        .count = NUM_BUFFERS,
    };

    if (-1 == v4l2_ioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", VIDEO_DEVICE);
            exit(EXIT_FAILURE);
        } else {
            perror("VIDIOC_REQBUFS");
            exit(EXIT_FAILURE);
        }
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", VIDEO_DEVICE);
        exit(EXIT_FAILURE);
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf = {
            .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
            .memory = V4L2_MEMORY_MMAP,
            .index = i,
        };

        if (-1 == v4l2_ioctl(fd, VIDIOC_QUERYBUF, &buf))
            perror("VIDIOC_QUERYBUF");

        buffers[i].length = buf.length;
        buffers[i].start = v4l2_mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start)
            perror("mmap");
    }
}

static void init_device(void)
{
    struct v4l2_capability cap;
    struct v4l2_cropcap cropcap;
    struct v4l2_crop crop;
    struct v4l2_format fmt = {
        .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    };

    if (-1 == v4l2_ioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is no V4L2 device\n", VIDEO_DEVICE);
            exit(EXIT_FAILURE);
        } else {
            perror("VIDIOC_QUERYCAP");
            exit(EXIT_FAILURE);
        }
