```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PIN 4

#define MIN_PULSE 1000
#define MAX_PULSE 2000
#define CENTER_PULSE 1500

#define DELAY 50
#define INCREMENT 10

int pulse = CENTER_PULSE;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM)
    {
        printf("Exiting...\n");
        gpioServo(PIN, 0);
        gpioTerminate();
        exit(0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(PIN, PI_OUTPUT);

    printf("Servo Control\n");
    printf("Servo: GPIO%d\n", PIN);
    printf("Center position: %d us\n", CENTER_PULSE);

    while (1)
    {
        pulse += INCREMENT;
        if (pulse > MAX_PULSE)
        {
            pulse = MIN_PULSE;
        }

        gpioServo(PIN, pulse);

        gpioDelay(DELAY);
    }

    return 0;
}
