#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define VIDEO_FORMAT V4L2_PIX_FMT_YUYV
#define VIDEO_WIDTH 200
#define VIDEO_HEIGHT 150
#define VIDEO_BUFFER_COUNT 1
#define VIDEO_BUFFER_SIZE (VIDEO_WIDTH * VIDEO_HEIGHT * 2)
#define VIDEO_TIMEOUT_SEC 2

static void *video_buffer;
static int video_fd;

static void video_init(void)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int ret;

    video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(video_fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "device is not a video capture device\n");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "device does not support streaming i/o\n");
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = VIDEO_WIDTH;
    fmt.fmt.pix.height = VIDEO_HEIGHT;
    fmt.fmt.pix.pixelformat = VIDEO_FORMAT;
