#include <unistd.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define VIDEO_FORMAT V4L2_PIX_FMT_YUYV
#define VIDEO_WIDTH 200
#define VIDEO_HEIGHT 150
#define VIDEO_BUFFER_COUNT 1
#define VIDEO_BUFFER_SIZE (VIDEO_WIDTH * VIDEO_HEIGHT * 2)
#define VIDEO_TIMEOUT_SEC 2

static void *video_buffer;
static int video_fd;

static void video_init(void)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int ret;

    video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(video_fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "device is not a video capture device\n");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "device does not support streaming i/o\n");
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = VIDEO_WIDTH;
    fmt.fmt.pix.height = VIDEO_HEIGHT;
    fmt.fmt.pix.pixelformat = VIDEO_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(video_fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (fmt.fmt.pix.width != VIDEO_WIDTH ||
        fmt.fmt.pix.height != VIDEO_HEIGHT ||
        fmt.fmt.pix.pixelformat != VIDEO_FORMAT) {
        fprintf(stderr, "device does not support %dx%d %s\n",
                VIDEO_WIDTH, VIDEO_HEIGHT,
                (char *)&fmt.fmt.pix.pixelformat);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = VIDEO_BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(video_fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    ret = ioctl(video_fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    video_buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
    if (video_buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(video_fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(video_fd, VIDIOC_STREAMON, &buf.type);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    FD_ZERO(&fds);
    FD_SET(video_fd, &fds);
    tv.tv_sec = VIDEO_TIMEOUT_SEC;
    tv.tv_usec = 0;
    ret = select(video_fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) {
        if (errno == EINTR) {
            fprintf(stderr, "select interrupted\n");
            exit(EXIT_FAILURE);
        }
        perror("select");
        exit(EXIT_FAILURE);
    } else if (ret == 0) {
        fprintf(stderr, "select timeout\n");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(video_fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (buf.length != VIDEO_BUFFER_SIZE) {
        fprintf(stderr, "buffer size mismatch\n");
        exit(EXIT_FAILURE);
    }
}

static void video_deinit(void)
{
    int ret;

    ret = ioctl(video_fd, VIDIOC_STREAMOFF, &buf.type);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    munmap(video_buffer, buf.length);
    close(video_fd);
}

static void video_capture(void)
{
    FILE *fp;
    int ret;

    fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    ret = fwrite(video_buffer, VIDEO_BUFFER_SIZE, 1, fp);
    if (ret != 1) {
        perror("fwrite");
        exit(EXIT_FAILURE);
    }

    fclose(fp);
}

static void signal_handler(int sig)
{
    video_deinit();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    video_init();
    video_capture();
    video_deinit();

    return EXIT_SUCCESS;
}
