#define SSD1306_SETCOMPINS 0xDA
#define SSD1306_SETVCOMDETECT 0xDB
#define SSD1306_SETDISPLAYCLOCKDIV 0xD5
#define SSD1306_SETPRECHARGE 0xD9
#define SSD1306_SETMULTIPLEX 0xA8
#define SSD1306_SETLOWCOLUMN 0x00
#define SSD1306_SETHIGHCOLUMN 0x10
#define SSD1306_SETSTARTLINE 0x40
#define SSD1306_MEMORYMODE 0x20
#define SSD1306_COLUMNADDR 0x21
#define SSD1306_PAGEADDR   0x22
#define SSD1306_COMSCANINC 0xC0
#define SSD1306_COMSCANDEC 0xC8
#define SSD1306_SEGREMAP 0xA0
#define SSD1306_CHARGEPUMP 0x8D
#define SSD1306_EXTERNALVCC 0x1
#define SSD1306_SWITCHCAPVCC 0x2

#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

#define SSD1306_BUFFER_SIZE (SSD1306_WIDTH * SSD1306_HEIGHT / 8)

static int fd;
static char buffer[SSD1306_BUFFER_SIZE];

static void ssd1306_command(uint8_t c)
{
    if (write(fd, &c, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        exit(1);
    }
}

static void ssd1306_data(uint8_t c)
{
    uint8_t control = 0x40;
    if (write(fd, &control, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        exit(1);
    }
    if (write(fd, &c, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        exit(1);
    }
}

static void ssd1306_init(void)
{
    ssd1306_command(SSD1306_DISPLAYOFF);
    ssd1306_command(SSD1306_SETDISPLAYCLOCKDIV);
    ssd1306_command(0x80);
    ssd1306_command(SSD1306_SETMULTIPLEX);
    ssd1306_command(0x3F);
    ssd1306_command(SSD1306_SETDISPLAYOFFSET);
    ssd1306_command(0x0);
    ssd1306_command(SSD1306_SETSTARTLINE | 0x0);
    ssd1306_command(SSD1306_CHARGEPUMP);
    ssd1306_command(0x14);
    ssd1306_command(SSD1306_MEMORYMODE);
    ssd1306_command(0x00);
    ssd1306_command(SSD1306_SEGREMAP | 0x1);
    ssd1306_command(SSD1306_COMSCANDEC);
    ssd1306_command(SSD1306_SETCOMPINS);
    ssd1306_command(0x12);
    ssd1306_command(SSD1306_SETCONTRAST);
    ssd1306_command(0xCF);
    ssd1306_command(SSD1306_SETPRECHARGE);
    ssd1306_command(0xF1);
    ssd1306_command(SSD1306_SETVCOMDETECT);
    ssd1306_command(0x40);
    ssd1306_command(SSD1306_DISPLAYALLON_RESUME);
    ssd1306_command(SSD1306_NORMALDISPLAY);
    ssd1306_command(SSD1306_DISPLAYON);
}

static void ssd1306_clear(void)
{
    memset(buffer, 0, SSD1306_BUFFER_SIZE);
}

static void ssd1306_draw_char(int x, int y, char c)
{
    int i;
    for (i = 0; i < 5; i++) {
        buffer[x + (y / 8) * SSD1306_WIDTH + i] = font5x7[c * 5 + i];
    }
}

static void ssd1306_draw_string(int x, int y, char *s)
{
    while (*s) {
        ssd1306_draw_char(x, y, *s);
        x += 6;
        s++;
    }
}

static void ssd1306_update(void)
{
    int i;
    ssd1306_command(SSD1306_COLUMNADDR);
    ssd1306_command(0);
    ssd1306_command(SSD1306_WIDTH - 1);
    ssd1306_command(SSD1306_PAGEADDR);
    ssd1306_command(0);
    ssd1306_command(7);
    for (i = 0; i < SSD1306_BUFFER_SIZE; i++) {
        ssd1306_data(buffer[i]);
    }
}

static void ssd1306_close(void)
{
    ssd1306_command(SSD1306_DISPLAYOFF);
    close(fd);
}

static void ssd1306_open(void)
{
    char filename[20];
    sprintf(filename, "/dev/i2c-%d", I2C_BUS);
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C device: %s\n", strerror(errno));
        exit(1);
    }
    ssd1306_init();
}

static void sigint_handler(int signum)
{
    ssd1306_close();
    exit(0);
}

int main(void)
{
    FILE *fp;
    char line[1024];
    char *p;
    int cpu_temp;
    int cpu_usage;
    int i;

    ssd1306_open();
    signal(SIGINT, sigint_handler);

    while (1) {
        ssd1306_clear();

        fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (fp == NULL) {
            ssd1306_draw_string(0, 0, "Error reading");
            ssd1306_draw_string(0, 8, "/sys/class/thermal/thermal_zone0/temp");
            ssd1306_update();
            continue;
        }
        fgets(line, sizeof(line), fp);
        fclose(fp);
        p = strchr(line, '\n');
        if (p != NULL) {
            *p = '\0';
        }
        cpu_temp = atoi(line) / 1000;

        fp = fopen("/proc/stat", "r");
        if (fp == NULL) {
            ssd1306_draw_string(0, 0, "Error reading");
            ssd1306_draw_string(0, 8, "/proc/stat");
            ssd1306_update();
            continue;
        }
        fgets(line, sizeof(line), fp);
        fclose(fp);
        p = strchr(line, ' ');
        if (p == NULL) {
            ssd1306_draw_string(0, 0, "Error parsing");
            ssd1306_draw_string(0, 8, "/proc/stat");
            ssd1306_update();
            continue;
        }
        p++;
        cpu_usage = atoi(p) * 100 / 10000000;

        ssd1306_draw_string(0, 0, "CPU Temp:");
        ssd1306_draw_string(64, 0, "C");
        ssd1306_draw_string(0, 8, "CPU Usage:");
        ssd1306_draw_string(64, 8, "%");
        for (i = 0; i < cpu_temp; i++) {
            ssd1306_draw_char(72 + i * 6, 0, '0' + (i % 10));
        }
        for (i = 0; i < cpu_usage; i++) {
            ssd1306_draw_char(72 + i * 6, 8, '0' + (i % 10));
        }
        ssd1306_update();

        sleep(1);
    }

    return 0;
}

