#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define SENSOR_GPIO 4
#define LED_GPIO 17
#define SENSOR_NAME "E18-D50NK"
#define LOG_FILE "proximity.log"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%SZ %s\n"
#define LOG_BUFFER_SIZE 100
#define SENSOR_POLL_INTERVAL_MS 100
#define LED_BLINK_DURATION_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *led_line;
static FILE *log_file;

static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void handle_signal(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static void blink_led(void)
{
    gpiod_line_request_output(led_line, "blink", 0);
    gpiod_line_set_value(led_line, 1);
    usleep(LED_BLINK_DURATION_MS * 1000);
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    led_line = NULL;
}

static void log_detection(void)
{
    char buffer[LOG_BUFFER_SIZE];
    time_t now = time(NULL);
    struct tm *now_tm = gmtime(&now);
    if (now_tm == NULL) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return;
    }
    if (strftime(buffer, LOG_BUFFER_SIZE, LOG_FORMAT, now_tm) == 0) {
        fprintf(stderr, "Error formatting time: %s\n", strerror(errno));
        return;
    }
    if (fputs(buffer, log_file) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }
    fflush(log_file);
}

static void detect_object(void)
{
    int ret;
    struct gpiod_line_event event;
    ret = gpiod_line_event_wait(sensor_line, &event);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for sensor event: %s\n", strerror(errno));
        return;
    }
    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        return;
    }
    blink_led();
    log_detection();
}

int main(void)
{
    int ret;
    struct gpiod_line_request_config sensor_config;
    struct gpiod_line_request_config led_config;
    struct sigaction action;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (sensor_line == NULL) {
        fprintf(stderr, "Error getting sensor line: %s\n", strerror(errno));
        goto error;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (led_line == NULL) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        goto error;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        goto error;
    }

    memset(&sensor_config, 0, sizeof(sensor_config));
    sensor_config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    sensor_config.consumer = SENSOR_NAME;
    ret = gpiod_line_request(sensor_line, &sensor_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting sensor line: %s\n", strerror(errno));
        goto error;
    }

    memset(&led_config, 0, sizeof(led_config));
    led_config.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    led_config.consumer = SENSOR_NAME;
    ret = gpiod_line_request(led_line, &led_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line: %s\n", strerror(errno));
        goto error;
    }

    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    while (1) {
        detect_object();
        usleep(SENSOR_POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;

error:
    cleanup();
    return EXIT_FAILURE;
}

