#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_RANGE 38000
#define MAX_TIMEOUT 200000

static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP);

    gpioSetAlertFunc(ECHO_PIN, NULL);

    signal(SIGINT, intHandler);

    while (keepRunning) {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        int echo = gpioRead(ECHO_PIN);
        while (echo == PI_LOW) {
            echo = gpioRead(ECHO_PIN);
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        long long start_time = start.tv_sec * 1000000 + start.tv_nsec / 1000;
        long long end_time = end.tv_sec * 1000000 + end.tv_nsec / 1000;
        long long pulse_start = end_time - start_time;

        if (pulse_start > MAX_TIMEOUT) {
            fprintf(stderr, "Echo pulse start timeout\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &start);

        echo = gpioRead(ECHO_PIN);
        while (echo == PI_HIGH) {
            echo = gpioRead(ECHO_PIN);
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        start_time = start.tv_sec * 1000000 + start.tv_nsec / 1000;
        end_time = end.tv_sec * 1000000 + end.tv_nsec / 1000;
        long long pulse_end = end_time - start_time;

        if (pulse_end > MAX_TIMEOUT) {
            fprintf(stderr, "Echo pulse end timeout\n");
            continue;
        }

        long long pulse_duration = pulse_end - pulse_start;

        if (pulse_duration <= 0 || pulse_duration > MAX_RANGE) {
            fprintf(stderr, "Invalid pulse duration: %lld\n", pulse_duration);
            continue;
        }

        double distance = pulse_duration / 58.0;

        printf("Distance: %.2f cm\n", distance);

        sleep(1);
    }

    gpioTerminate();

    return 0;
}

