#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1 17
#define SENSOR_2 27
#define POLL_INTERVAL 10
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "proximity_log.txt"

FILE *log_file;
int sensor_1_state = 0;
int sensor_2_state = 0;
int sensor_1_last_state = 0;
int sensor_2_last_state = 0;

void log_event(int sensor, int state) {
    time_t now = time(NULL);
    struct tm *time_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", time_info);

    char event[10];
    if (state == 0) {
        strcpy(event, "CLEARED");
    } else {
        strcpy(event, "DETECTED");
    }

    fprintf(log_file, "%s,%d,%s\n", timestamp, sensor, event);
    fflush(log_file);
}

void poll_sensors() {
    int sensor_1_value = gpioRead(SENSOR_1);
    int sensor_2_value = gpioRead(SENSOR_2);

    if (sensor_1_value != sensor_1_last_state) {
        sensor_1_last_state = sensor_1_value;
        if (sensor_1_value == 0) {
            sensor_1_state = 0;
        } else {
            sensor_1_state = 1;
        }
        log_event(1, sensor_1_state);
    }

    if (sensor_2_value != sensor_2_last_state) {
        sensor_2_last_state = sensor_2_value;
        if (sensor_2_value == 0) {
            sensor_2_state = 0;
        } else {
            sensor_2_state = 1;
        }
        log_event(2, sensor_2_state);
    }
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        gpioTerminate();
        fclose(log_file);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        poll_sensors();
        gpioDelay(POLL_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

