#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_1 "/dev/i2c-1"
#define I2C_ADDR 0x29
#define I2C_TIMEOUT 50000
#define I2C_MEAS_STATUS 0x13
#define I2C_MEAS_START 0x03
#define I2C_MEAS_DISTANCE 0x62
#define I2C_MEAS_DISTANCE_SIZE 2
#define CSV_FILE "distance_log.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int i2c_read(uint8_t reg, uint8_t *buf, size_t size)
{
    int ret;

    ret = write(i2c_fd, &reg, 1);
    if (ret < 0) {
        fprintf(stderr, "write failed: %s\n", strerror(errno));
        return -1;
    }

    ret = read(i2c_fd, buf, size);
    if (ret < 0) {
        fprintf(stderr, "read failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_write(uint8_t reg, uint8_t val)
{
    int ret;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = val;

    ret = write(i2c_fd, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "write failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_init(void)
{
    int ret;

    i2c_fd = open(I2C_BUS_1, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open failed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "ioctl failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int csv_init(void)
{
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "fopen failed: %s\n", strerror(errno));
        return -1;
    }

    fprintf(csv_file, "timestamp,distance_mm\n");

    return 0;
}

static int measure_distance(void)
{
    int ret;
    uint8_t buf[I2C_MEAS_DISTANCE_SIZE];
    uint16_t distance;
    struct timespec ts;

    ret = i2c_write(I2C_MEAS_STATUS, I2C_MEAS_START);
    if (ret < 0) {
        return -1;
    }

    ret = i2c_read(I2C_MEAS_STATUS, buf, 1);
    if (ret < 0) {
        return -1;
    }

    if (!(buf[0] & 0x01)) {
        fprintf(stderr, "measurement not ready\n");
        return -1;
    }

    ret = i2c_read(I2C_MEAS_DISTANCE, buf, I2C_MEAS_DISTANCE_SIZE);
    if (ret < 0) {
        return -1;
    }

    distance = (buf[0] << 8) | buf[1];

    ret = clock_gettime(CLOCK_REALTIME, &ts);
    if (ret < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    fprintf(csv_file, "%ld.%09ld,%d\n", ts.tv_sec, ts.tv_nsec, distance);

    return 0;
}

