    ret = i2c_init();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    ret = csv_init();
    if (ret < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (true) {
        ret = measure_distance();
        if (ret < 0) {
            continue;
        }

        usleep(500000);
    }

    cleanup();

    return EXIT_SUCCESS;
