#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <vl53l1x_api.h>

#define BUZZER_PIN 22
#define I2C_BUS 1
#define I2C_ADDR 0x29

VL53L1_Dev_t dev;
VL53L1_RangingMeasurementData_t data;

void sigint_handler(int sig) {
    VL53L1_StopMeasurement(&dev);
    VL53L1_Deinit(&dev);
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (VL53L1_WaitDeviceBooted(&dev) != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to boot VL53L1X\n");
        return 1;
    }

    if (VL53L1_DataInit(&dev) != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        return 1;
    }

    if (VL53L1_StaticInit(&dev) != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        return 1;
    }

    if (VL53L1_SetDistanceMode(&dev, VL53L1_DISTANCEMODE_LONG) != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to set distance mode\n");
        return 1;
    }

    if (VL53L1_SetMeasurementTimingBudgetMicroSeconds(&dev, 50000) != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to set measurement timing budget\n");
        return 1;
    }

    if (VL53L1_StartMeasurement(&dev) != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to start measurement\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (VL53L1_WaitMeasurementDataReady(&dev) != VL53L1_ERROR_NONE) {
            fprintf(stderr, "Failed to wait for measurement data\n");
            continue;
        }

        if (VL53L1_GetRangingMeasurementData(&dev, &data) != VL53L1_ERROR_NONE) {
            fprintf(stderr, "Failed to get ranging measurement data\n");
            continue;
        }

        if (data.RangeStatus == 0) {
            if (data.RangeMilliMeter < 100) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        }

        VL53L1_ClearInterruptAndStartMeasurement(&dev);
        usleep(500000);
    }

    return 0;
}

