Write a C program for a Raspberry Pi 3 Model B+ that implements a temperature sensor using a DS18B20 sensor connected on the GPIO bus on GPIO 4 (BCM); the program must use the library’s API to read the temperature every 100 ms, checking that the driver library initialization, GPIO mode configuration, and sensor initialization succeed, and report clearly any sensor‑absent condition (timeout or no echo) or invalid reading (out‑of‑range), where valid readings are limited to 0 °C–100 °C, and ensure a clean shutdown on SIGINT that calls the library’s API call() to release resources.

### Response:
```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define MAX_TEMP 100
#define MIN_TEMP 0
#define SLEEP_TIME 100

volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_OFF);

    signal(SIGINT, intHandler);

    while (keepRunning) {
        double temp = gpioRead_DS18B20(SENSOR_PIN);

        if (temp >= MAX_TEMP || temp <= MIN_TEMP) {
            printf("Out of range\n");
        } else {
            printf("Temperature: %.1f °C\n", temp);
        }

        gpioDelay(SLEEP_TIME * 1000);
    }

    gpioTerminate();

    return 0;
}
