#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <VL53L1X.h>

#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_INTERRUPT 24

#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300

#define I2C_BUS 1
#define I2C_ADDRESS 0x29

#define MAX_RETRIES 5

VL53L1X sensor;

void motor_forward() {
    gpioWrite(GPIO_MOTOR_FORWARD, 1);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
}

void motor_backward() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 1);
}

void motor_stop() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
}

void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        uint16_t distance;
        int status;

        for (int i = 0; i < MAX_RETRIES; i++) {
            status = VL53L1X_get_distance(&sensor, &distance);
            if (status == 0) {
                break;
            }
            gpioDelay(1000 * (1 << i));
        }

        if (status != 0) {
            fprintf(stderr, "Failed to read distance: %d\n", status);
            return;
        }

        printf("Distance: %d\n", distance);

        if (distance < DISTANCE_THRESHOLD_FORWARD) {
            motor_forward();
        } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
            motor_backward();
        } else {
            motor_stop();
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (VL53L1X_init(&sensor, I2C_BUS, I2C_ADDRESS) != 0) {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        return 1;
    }

    if (gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_INTERRUPT, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        return 1;
    }

    if (gpioSetISRFunc(GPIO_INTERRUPT, EITHER_EDGE, 0, interrupt_handler) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        return 1;
    }

    while (1) {
        gpioDelay(1000000);
    }

    VL53L1X_close(&sensor);
    gpioTerminate();
    return 0;
}

