#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x_api.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define XSHUT_PIN 27

VL53L1_Dev_t dev;
VL53L1_RangingMeasurementData_t data;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        VL53L1_StopMeasurement(&dev);
        VL53L1_Deinit(&dev);
        gpioWrite(XSHUT_PIN, 0);
        gpioTerminate();
        closelog();
        exit(0);
    }
}

int main(void) {
    openlog("vl53l1x", LOG_PID, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1);
    sleep(1);

    if (VL53L1_WaitDeviceBooted(&dev) != VL53L1_ERROR_NONE) {
        syslog(LOG_ERR, "Failed to boot VL53L1X");
        return 1;
    }

    if (VL53L1_DataInit(&dev) != VL53L1_ERROR_NONE) {
        syslog(LOG_ERR, "Failed to initialize VL53L1X");
        return 1;
    }

    VL53L1_StaticInit(&dev);
    VL53L1_SetDistanceMode(&dev, VL53L1_DISTANCEMODE_LONG);
    VL53L1_SetMeasurementTimingBudgetMicroSeconds(&dev, 50000);
    VL53L1_SetInterMeasurementPeriodMilliSeconds(&dev, 100);
    VL53L1_StartMeasurement(&dev);

    while (true) {
        if (VL53L1_WaitMeasurementDataReady(&dev) != VL53L1_ERROR_NONE) {
            syslog(LOG_ERR, "Failed to wait for measurement data");
            continue;
        }

        if (VL53L1_GetRangingMeasurementData(&dev, &data) != VL53L1_ERROR_NONE) {
            syslog(LOG_ERR, "Failed to get ranging measurement data");
            continue;
        }

        if (data.RangeStatus != 0) {
            syslog(LOG_ERR, "Invalid range status: %d", data.RangeStatus);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        syslog(LOG_INFO, "%ld.%09ld, %d, %d", ts.tv_sec, ts.tv_nsec, data.RangeMilliMeter, data.RangeStatus);

        VL53L1_ClearInterruptAndStartMeasurement(&dev);
    }

    return 0;
}

