#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDR 0x5A
#define I2C_BUS 1
#define GPIO_PIN 27
#define THRESHOLD 1000
#define LOG_FILE "proximity.log"

int i2c_fd;
int gpio_fd;
int threshold;

void i2c_init(int addr)
{
    char i2c_dev[16];
    sprintf(i2c_dev, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        exit(1);
    }
}

void gpio_init(int pin)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %s\n", strerror(errno));
        exit(1);
    }
    gpio_fd = gpioSetAlertFuncEx(pin, NULL);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to set GPIO alert function: %s\n", strerror(errno));
        exit(1);
    }
}

void log_init(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }
    fclose(fp);
}

void log_proximity(int proximity, int status)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s %d %s\n", timestamp, proximity, status ? "ALERT" : "SAFE");
    fclose(fp);
}

void i2c_read(int *proximity)
{
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read I2C data: %s\n", strerror(errno));
        exit(1);
    }
    *proximity = (buf[0] << 8) | buf[1];
}

void gpio_read(int *status)
{
    *status = gpioRead(GPIO_PIN);
    if (*status < 0) {
        fprintf(stderr, "Failed to read GPIO pin: %s\n", strerror(errno));
        exit(1);
    }
}

void gpio_wait()
{
    while (gpioWaitAlert(gpio_fd, 1000) >= 0) {
        int proximity;
        int status;
        i2c_read(&proximity);
        gpio_read(&status);
        log_proximity(proximity, status);
    }
}

void cleanup()
{
    gpioTerminate();
    close(i2c_fd);
}

void sigint_handler(int signum)
{
    cleanup();
    exit(0);
}

int main(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
        case 'a':
            i2c_init(strtol(optarg, NULL, 0));
            break;
        case 't':
            threshold = atoi(optarg);
            break;
        default:
            fprintf(stderr, "Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
            exit(1);
        }
    }
    log_init(LOG_FILE);
    gpio_init(GPIO_PIN);
    gpio_wait();
    return 0;
}

