#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_RANGE (SERVO_MAX - SERVO_MIN)
#define SERVO_CENTER (SERVO_MIN + SERVO_RANGE / 2)
#define SERVO_MIN_DIST 20
#define SERVO_MAX_DIST 200
#define SERVO_RANGE_DIST (SERVO_MAX_DIST - SERVO_MIN_DIST)
#define SERVO_MIN_ANGLE 0
