#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define TEMP_LOG "temperature_log.csv"

int fd;
FILE *fp;

void sigint_handler(int sig) {
    if (fd > 0) {
        close(fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return 1;
    }

    fp = fopen(TEMP_LOG, "a");
    if (fp == NULL) {
        perror("Failed to open temperature log file");
        close(fd);
        return 1;
    }

    uint8_t buf[2];
    float ambient_temp, object_temp;
    struct timespec ts;

    while (1) {
        // Read ambient temperature
        buf[0] = 0x06;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to I2C bus");
            break;
        }
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from I2C bus");
            break;
        }
        ambient_temp = (buf[0] | (buf[1] << 8)) * 0.02 - 273.15;

        // Read object temperature
        buf[0] = 0x07;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to I2C bus");
            break;
        }
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from I2C bus");
            break;
        }
        object_temp = (buf[0] | (buf[1] << 8)) * 0.02 - 273.15;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to log file
        fprintf(fp, "%ld.%09ld,%.2f,%.2f\n", ts.tv_sec, ts.tv_nsec, ambient_temp, object_temp);
        fflush(fp);

        // Wait 5 seconds
        sleep(5);
    }

    close(fd);
    fclose(fp);
    return 0;
}

