static void i2c_init(void)
{
    char i2c_dev[16];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void i2c_deinit(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void log_init(void)
{
    log_fd = open(I2C_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file %s: %s\n", I2C_LOG_FILE, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

