#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SENSOR_TIMEOUT 50000
#define SENSOR_INTERVAL 5000000
#define TEMP_MIN -40
#define TEMP_MAX 150
#define TEMP_ERROR "SENSOR MALFUNCTION"

FILE *fp;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM)
    {
        fclose(fp);
        gpioTerminate();
        exit(0);
    }
}

int main(void)
{
    int count = 0;
    int high_time, low_time, total_time;
    int temp;
    char timestamp[25];
    struct timeval tv;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if ((fp = fopen("temperature_log.txt", "a")) == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1)
    {
        high_time = gpioPulseIn(GPIO_PIN, 1, SENSOR_TIMEOUT);
        low_time = gpioPulseIn(GPIO_PIN, 0, SENSOR_TIMEOUT);
        total_time = high_time + low_time;

        if (total_time == 0)
        {
            fprintf(stderr, "Error: total time is zero\n");
            count = 0;
            continue;
        }

        temp = (high_time * 1000000) / total_time;
        temp = (temp - 500) / 10;

        if (temp < TEMP_MIN || temp > TEMP_MAX)
        {
            fprintf(stderr, "Error: temperature out of range\n");
            count++;
        }
        else
        {
            count = 0;
        }

        if (count == 3)
        {
            fprintf(fp, "%s\n", TEMP_ERROR);
            count = 0;
        }
        else
        {
            gettimeofday(&tv, NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%T%z", localtime(&tv.tv_sec));
            fprintf(fp, "%s, %d\n", timestamp, temp);
        }

        usleep(SENSOR_INTERVAL);
    }

    return 0;
}

