#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define I2C_CMD 0x2400
#define I2C_DATA_LEN 6
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 1
#define LOG_FILE "environmental_data.txt"
#define LOG_INTERVAL 5
#define LOG_SIN_FREQ 1
#define LOG_SIN_AMP 2
#define LOG_SIN_OFFSET 5
#define LOG_SIN_PERIOD 3600

static int i2c_fd = -1;
static FILE *log_file = NULL;
static bool running = true;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        running = false;
    }
}

static int i2c_init(void)
{
    int fd;
    char filename[20];

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

static int i2c_read(uint8_t *data, size_t len)
{
    int ret;

    ret = read(i2c_fd, data, len);
    if (ret != len) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    return 0;
}

static int i2c_write(uint16_t cmd)
{
    int ret;

    ret = write(i2c_fd, &cmd, sizeof(cmd));
    if (ret != sizeof(cmd)) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    return 0;
}

static int i2c_crc8(uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    int i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

static int i2c_read_data(uint8_t *data, size_t len)
{
    int ret;
    uint8_t crc;

    ret = i2c_read(data, len);
    if (ret < 0) {
        return -1;
    }

    crc = i2c_crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    return 0;
}

static int log_init(void)
{
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    return 0;
}

static int log_data(double temp, double humidity)
{
    time_t now;
    struct tm *tm;
    char time_str[32];

    now = time(NULL);
    tm = gmtime(&now);
    if (tm == NULL) {
        perror("Failed to get current time");
        return -1;
    }

    if (strftime(time_str, sizeof(time_str), "%FT%TZ", tm) == 0) {
        fprintf(stderr, "Failed to format time string\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", time_str, temp, humidity);
    fflush(log_file);

    return 0;
}

int main(void)
{
    int ret;
    uint8_t data[I2C_DATA_LEN];
    double temp, humidity;
    double sin_offset;
    time_t start_time;
    time_t now;
    double elapsed;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    ret = log_init();
    if (ret < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    start_time = time(NULL);
    sin_offset = 0;

    while (running) {
        ret = i2c_write(I2C_CMD);
        if (ret < 0) {
            break;
        }

        usleep(15000);

        for (int i = 0; i < I2C_RETRY_COUNT; i++) {
            ret = i2c_read_data(data, I2C_DATA_LEN);
            if (ret == 0) {
                break;
            }

            if (i < I2C_RETRY_COUNT - 1) {
                usleep(I2C_RETRY_DELAY * 1000000);
            }
        }

        if (ret < 0) {
            temp = NAN;
            humidity = NAN;
        } else {
            uint16_t raw_temp = (data[0] << 8) | data[1];
            uint16_t raw_humidity = (data[3] << 8) | data[4];

            temp = -45 + 175 * raw_temp / 65535.0;
            humidity = 100 * raw_humidity / 65535.0;
        }

        now = time(NULL);
        elapsed = difftime(now, start_time);
        sin_offset = LOG_SIN_AMP * sin(2 * M_PI * LOG_SIN_FREQ * elapsed / LOG_SIN_PERIOD);

        ret = log_data(temp + sin_offset, humidity + sin_offset);
        if (ret < 0) {
            break;
        }

        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

