#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define SDP800_ADDR 0x25
#define SDP800_CMD 0x10
#define SDP800_DATA_LEN 3
#define SDP800_CRC_POLY 0x31
#define SDP800_CRC_INIT 0xff

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "airflow_log.csv"

int main(void)
{
    int fd;
    int ret;
    uint8_t buf[SDP800_DATA_LEN];
    uint8_t crc;
    uint16_t pressure;
    struct timespec ts;
    FILE *fp;

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    /* Set I2C slave address */
    ret = ioctl(fd, I2C_SLAVE, SDP800_ADDR);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    /* Open log file */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    /* Write header row if file is newly created */
    if (access(LOG_FILE, F_OK) == -1) {
        fprintf(fp, "Timestamp,Pressure\n");
    }

    /* Read pressure continuously */
    while (1) {
        /* Trigger measurement */
        ret = write(fd, &SDP800_CMD, 1);
        if (ret < 0) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        /* Wait at least 8 ms */
        usleep(8000);

        /* Read data */
        ret = read(fd, buf, SDP800_DATA_LEN);
        if (ret < 0) {
            perror("read");
            exit(EXIT_FAILURE);
        }

        /* Verify CRC */
        crc = SDP800_CRC_INIT;
        for (int i = 0; i < SDP800_DATA_LEN - 1; i++) {
            crc ^= buf[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ SDP800_CRC_POLY;
                } else {
                    crc <<= 1;
                }
            }
        }
        if (crc != buf[SDP800_DATA_LEN - 1]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        /* Convert data to pressure */
        pressure = (buf[0] << 8) | buf[1];

        /* Get current timestamp */
        clock_gettime(CLOCK_REALTIME, &ts);

        /* Write timestamp and pressure to log file */
        fprintf(fp, "%ld.%09ld,%d\n", ts.tv_sec, ts.tv_nsec, pressure);

        /* Flush log file */
        fflush(fp);
    }

    /* Close log file */
    fclose(fp);

    /* Close I2C bus */
    close(fd);

    return 0;
}

