#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDR 0x48
#define I2C_BUS 1
#define GPIO_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0

int main(void)
{
    int i2c_fd, gpio_fd;
    int i2c_result, gpio_result;
    int i;
    float temp_buffer[BUFFER_SIZE];
    float temp_sum = 0.0;
    float temp_avg = 0.0;
    float temp_current = 0.0;
    int fan_state = 0;

    // Initialize the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0)
    {
        fprintf(stderr, "Error opening I2C bus\n");
        return -1;
    }

    i2c_result = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (i2c_result < 0)
    {
        fprintf(stderr, "Error setting I2C address\n");
        close(i2c_fd);
        return -1;
    }

    // Initialize the GPIO pin
    gpio_result = gpioInitialise();
    if (gpio_result < 0)
    {
        fprintf(stderr, "Error initializing GPIO\n");
        close(i2c_fd);
        return -1;
    }

    gpio_fd = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_fd < 0)
    {
        fprintf(stderr, "Error setting GPIO pin mode\n");
        gpioTerminate();
        close(i2c_fd);
        return -1;
    }

    // Main loop
    while (1)
    {
        // Read temperature from LM75B
        char buf[2];
        i2c_result = read(i2c_fd, buf, 2);
        if (i2c_result < 0)
        {
            fprintf(stderr, "Error reading from I2C bus\n");
            gpioWrite(GPIO_PIN, 0);
            gpioTerminate();
            close(i2c_fd);
            return -1;
        }

        // Convert raw temperature data to degrees Celsius
        temp_current = (buf[0] << 8 | buf[1]) >> 7;
        temp_current /= 2.0;

        // Update temperature buffer and compute average
        temp_sum -= temp_buffer[i];
        temp_buffer[i] = temp_current;
        temp_sum += temp_buffer[i];
        temp_avg = temp_sum / BUFFER_SIZE;

        // Check temperature and set fan state
        if (temp_avg > TEMP_THRESHOLD_ON)
        {
            fan_state = 1;
        }
        else if (temp_avg < TEMP_THRESHOLD_OFF)
        {
            fan_state = 0;
        }

        // Set GPIO pin based on fan state
        gpio_result = gpioWrite(GPIO_PIN, fan_state);
        if (gpio_result < 0)
        {
            fprintf(stderr, "Error writing to GPIO pin\n");
            gpioTerminate();
            close(i2c_fd);
            return -1;
        }

        // Wait for 1 second
        sleep(1);

        // Increment buffer index
        i = (i + 1) % BUFFER_SIZE;
    }

    // Clean up
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    close(i2c_fd);

    return 0;
}

