#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define I2C_TEMP_REG 0x00
#define I2C_HUM_REG 0x01
#define I2C_CONFIG_REG 0x02
#define I2C_CONFIG_VAL 0x10
#define I2C_MANUF_ID_REG 0xFE
#define I2C_DEV_ID_REG 0xFF
#define I2C_MANUF_ID_VAL 0x5449
#define I2C_DEV_ID_VAL 0x1050
#define I2C_READ_TIMEOUT 1000000
#define I2C_WRITE_TIMEOUT 1000000
#define I2C_READ_RETRIES 10
#define I2C_WRITE_RETRIES 10
#define I2C_READ_DELAY 20000
#define I2C_LOG_DELAY 5000000
#define I2C_LOG_FILE "enviro_log.txt"

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

static int i2c_read(int fd, uint8_t reg, uint16_t *val) {
    int ret;
    uint8_t buf[2];
    struct timespec ts;

    ts.tv_sec = 0;
    ts.tv_nsec = I2C_READ_TIMEOUT;

    for (int i = 0; i < I2C_READ_RETRIES; i++) {
        ret = pread(fd, buf, 2, reg);
        if (ret == 2) {
            *val = (buf[0] << 8) | buf[1];
            return 0;
        }
        nanosleep(&ts, NULL);
    }

    return -1;
}

static int i2c_write(int fd, uint8_t reg, uint16_t val) {
    int ret;
    uint8_t buf[3];
    struct timespec ts;

    ts.tv_sec = 0;
    ts.tv_nsec = I2C_WRITE_TIMEOUT;

    buf[0] = reg;
    buf[1] = val >> 8;
    buf[2] = val & 0xFF;

    for (int i = 0; i < I2C_WRITE_RETRIES; i++) {
        ret = pwrite(fd, buf, 3, 0);
        if (ret == 3) {
            return 0;
        }
        nanosleep(&ts, NULL);
    }

    return -1;
}

int main(void) {
    int ret;
    int fd;
    uint16_t val;
    uint16_t temp;
    uint16_t hum;
    struct timespec ts;
    FILE *fp;
    char buf[128];
    struct tm *tm;
    time_t t;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    ret = i2c_read(fd, I2C_MANUF_ID_REG, &val);
    if (ret < 0) {
        fprintf(stderr, "Failed to read manufacturer ID\n");
        close(fd);
        return EXIT_FAILURE;
    }
    if (val != I2C_MANUF_ID_VAL) {
        fprintf(stderr, "Invalid manufacturer ID: 0x%04X\n", val);
        close(fd);
        return EXIT_FAILURE;
    }

    ret = i2c_read(fd, I2C_DEV_ID_REG, &val);
    if (ret < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        close(fd);
        return EXIT_FAILURE;
    }
    if (val != I2C_DEV_ID_VAL) {
        fprintf(stderr, "Invalid device ID: 0x%04X\n", val);
        close(fd);
        return EXIT_FAILURE;
    }

