#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x44
#define I2C_REG 0x00
#define I2C_DATA_LEN 3
#define POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"

int main(void)
{
    int i2c_fd = -1;
    int log_fd = -1;
    uint8_t i2c_data[I2C_DATA_LEN];
    uint8_t crc = 0;
    uint16_t temp = 0;
    struct timespec ts;
    char time_str[26];
    char log_str[100];

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        goto cleanup;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Trigger temperature conversion
        if (write(i2c_fd, &I2C_REG, 1) != 1) {
            fprintf(stderr, "Failed to trigger temperature conversion: %s\n", strerror(errno));
            goto cleanup;
        }

        // Wait 10 ms for conversion to complete
        usleep(10000);

        // Read temperature data
        if (read(i2c_fd, i2c_data, I2C_DATA_LEN) != I2C_DATA_LEN) {
            fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
            goto cleanup;
        }

        // Calculate CRC
        for (int i = 0; i < I2C_DATA_LEN - 1; i++) {
            crc ^= i2c_data[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }

        // Verify CRC
        if (crc != i2c_data[I2C_DATA_LEN - 1]) {
            fprintf(stderr, "CRC mismatch: %02X != %02X\n", crc, i2c_data[I2C_DATA_LEN - 1]);
            goto cleanup;
        }

        // Calculate temperature
        temp = (i2c_data[0] << 8) | i2c_data[1];
        temp = (temp >> 2) * 100 / 32;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(time_str, sizeof(time_str), "%FT%T%z", gmtime(&ts.tv_sec));

        // Format log string
        snprintf(log_str, sizeof(log_str), "%s: %d.%02d\n", time_str, temp / 100, temp % 100);

        // Write log string to file
        if (write(log_fd, log_str, strlen(log_str)) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            goto cleanup;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

cleanup:
    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Close log file
    if (log_fd >= 0) {
        close(log_fd);
    }

    return 0;
}

