#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPiI2C.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_MEASURE_TEMP 0x2C06
#define SHT40_CMD_MEASURE_HUMIDITY 0x2C0D
#define SHT40_CMD_SOFT_RESET 0x30A2

#define HTTP_PORT 8080
#define HTTP_HEADER "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n"
#define HTTP_BODY "<html><head><title>SHT40</title></head><body><h1>SHT40</h1><p>Temperature: %f °C</p><p>Humidity: %f %%</p></body></html>"

static int sht40_fd = -1;
static int http_server_fd = -1;

static void cleanup(void)
{
    if (sht40_fd >= 0) {
        wiringPiI2CWriteReg16(sht40_fd, SHT40_CMD_SOFT_RESET);
        close(sht40_fd);
    }
    if (http_server_fd >= 0) {
        close(http_server_fd);
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int sht40_init(void)
{
    sht40_fd = wiringPiI2CSetup(SHT40_ADDR);
    if (sht40_fd < 0) {
        fprintf(stderr, "Failed to open SHT40: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sht40_read_temp(float *temp)
{
    int ret;
    unsigned short data;

    ret = wiringPiI2CWriteReg16(sht40_fd, SHT40_CMD_MEASURE_TEMP);
    if (ret < 0) {
        fprintf(stderr, "Failed to write SHT40 command: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    data = wiringPiI2CReadReg16(sht40_fd);
    if (data < 0) {
        fprintf(stderr, "Failed to read SHT40 data: %s\n", strerror(errno));
        return -1;
    }

    *temp = -45.0 + 175.0 * (data & 0xFFFC) / 65535.0;
    return 0;
}

static int sht40_read_humidity(float *humidity)
{
    int ret;
    unsigned short data;

    ret = wiringPiI2CWriteReg16(sht40_fd, SHT40_CMD_MEASURE_HUMIDITY);
    if (ret < 0) {
        fprintf(stderr, "Failed to write SHT40 command: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    data = wiringPiI2CReadReg16(sht40_fd);
    if (data < 0) {
        fprintf(stderr, "Failed to read SHT40 data: %s\n", strerror(errno));
        return -1;
    }

    *humidity = 100.0 * (data & 0xFFFC) / 65535.0;
    return 0;
}

static int http_server_init(void)
{
    int ret;
    struct sockaddr_in addr;

    http_server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (http_server_fd < 0) {
        fprintf(stderr, "Failed to create HTTP server socket: %s\n", strerror(errno));
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(HTTP_PORT);

    ret = bind(http_server_fd, (struct sockaddr *)&addr, sizeof(addr));
    if (ret < 0) {
        fprintf(stderr, "Failed to bind HTTP server socket: %s\n", strerror(errno));
        return -1;
    }

    ret = listen(http_server_fd, 5);
    if (ret < 0) {
        fprintf(stderr, "Failed to listen on HTTP server socket: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int http_server_send_response(int client_fd, float temp, float humidity)
{
    int ret;
    char buf[1024];

    snprintf(buf, sizeof(buf), HTTP_HEADER HTTP_BODY, temp, humidity);

    ret = send(client_fd, buf, strlen(buf), 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to send HTTP response: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int ret;
    int client_fd;
    struct sockaddr_in client_addr;
    socklen_t client_addr_len;
    float temp, humidity;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = sht40_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SHT40\n");
        return EXIT_FAILURE;
    }

    ret = http_server_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize HTTP server\n");
        return EXIT_FAILURE;
    }

    while (1) {
        client_addr_len = sizeof(client_addr);
        client_fd = accept(http_server_fd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_fd < 0) {
            fprintf(stderr, "Failed to accept HTTP client connection: %s\n", strerror(errno));
            continue;
        }

        ret = sht40_read_temp(&temp);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature from SHT40\n");
            close(client_fd);
            continue;
        }

        ret = sht40_read_humidity(&humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to read humidity from SHT40\n");
            close(client_fd);
            continue;
        }

        ret = http_server_send_response(client_fd, temp, humidity);
        if (ret < 0) {
            fprintf(stderr, "Failed to send HTTP response\n");
            close(client_fd);
            continue;
        }

        close(client_fd);
    }

    cleanup();
    return EXIT_SUCCESS;
}

