#define TMP102_CONF_13BIT 0x0200
#define TMP102_CONF_14BIT 0x0400
#define TMP102_CONF_11BIT 0x0600
#define TMP102_CONF_OS 0x8000
#define TMP102_CONF_FAULT_QUEUE_1 0x0000
#define TMP102_CONF_FAULT_QUEUE_2 0x0800
#define TMP102_CONF_FAULT_QUEUE_4 0x1000
#define TMP102_CONF_FAULT_QUEUE_6 0x1800
#define TMP102_CONF_POL 0x2000
#define TMP102_CONF_TM 0x4000
#define TMP102_CONF_SD 0x8000
#define TMP102_CONF_DEFAULT (TMP102_CONF_EM | TMP102_CONF_12BIT | TMP102_CONF_OS | TMP102_CONF_FAULT_QUEUE_1 | TMP102_CONF_POL | TMP102_CONF_TM | TMP102_CONF_SD)

static int i2c_fd = -1;

static void i2c_init(void)
{
    if (i2c_fd >= 0)
        return;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP102_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint16_t config = TMP102_CONF_DEFAULT;
    if (write(i2c_fd, &config, sizeof(config)) != sizeof(config)) {
        fprintf(stderr, "Failed to set I2C configuration: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void i2c_deinit(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int16_t i2c_read_temperature(void)
{
    uint8_t reg = TMP102_REG_TEMP;
    if (write(i2c_fd, &reg, sizeof(reg)) != sizeof(reg)) {
        fprintf(stderr, "Failed to set I2C register: %s\n", strerror(errno));
        return -1;
    }

    int16_t temp;
    if (read(i2c_fd, &temp, sizeof(temp)) != sizeof(temp)) {
        fprintf(stderr, "Failed to read I2C temperature: %s\n", strerror(errno));
        return -1;
    }

    return temp;
}

static void log_temperature(int16_t temp)
{
    FILE *fp = fopen("temperature_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open temperature log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    if (!tm) {
        fprintf(stderr, "Failed to get local time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (!strftime(timestamp, sizeof(timestamp), "%F %T", tm)) {
        fprintf(stderr, "Failed to format timestamp: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, temp / 200.0);
    fclose(fp);
}

static void sigint_handler(int signum)
{
    i2c_deinit();
    exit(EXIT_SUCCESS);
}

