#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RAIN_SENSOR 17
#define MOTOR_ENA 22
#define MOTOR_IN1 23
#define MOTOR_IN2 24

#define MOTOR_FORWARD 0
#define MOTOR_STOP 1

#define MOTOR_ON 1
#define MOTOR_OFF 0

#define MOTOR_DELAY 5000

#define LOG_FILE "log.txt"

static volatile int keep_running = 1;

void log_event(char *event)
{
    FILE *fp;
    time_t t;
    struct tm *tmp;
    char time_str[100];

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        printf("Error opening log file\n");
        return;
    }

    t = time(NULL);
    tmp = localtime(&t);
    if (tmp == NULL) {
        printf("Error getting local time\n");
        fclose(fp);
        return;
    }

    if (strftime(time_str, sizeof(time_str), "%c", tmp) == 0) {
        printf("Error formatting time string\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s: %s\n", time_str, event);
    fclose(fp);
}

void motor_control(int state)
{
    if (state == MOTOR_FORWARD) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioWrite(MOTOR_ENA, 1);
        log_event("Motor started");
    } else if (state == MOTOR_STOP) {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioWrite(MOTOR_ENA, 0);
        log_event("Motor stopped");
    }
}

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
        motor_control(MOTOR_STOP);
        gpioTerminate();
        log_event("Program terminated");
    }
}

int main(void)
{
    int rain_sensor_state;
    int motor_state = MOTOR_OFF;
    int motor_delay_start;

    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        return 1;
    }

    gpioSetMode(RAIN_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    log_event("Program started");

    while (keep_running) {
        rain_sensor_state = gpioRead(RAIN_SENSOR);

        if (rain_sensor_state == 0) {
            if (motor_state == MOTOR_OFF) {
                motor_control(MOTOR_FORWARD);
                motor_state = MOTOR_ON;
                motor_delay_start = millis();
            } else if (motor_state == MOTOR_ON) {
                if (millis() - motor_delay_start >= MOTOR_DELAY) {
                    motor_control(MOTOR_STOP);
                    motor_state = MOTOR_OFF;
                }
            }
        } else {
            if (motor_state == MOTOR_ON) {
                motor_control(MOTOR_STOP);
                motor_state = MOTOR_OFF;
            }
        }

        sleep(2);
    }

    return 0;
}

