#define BMP180_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_CTRL 0xF4
#define BMP180_REG_DATA 0xF6
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESS 0x34
#define BMP180_OSS 3

#define GPIO_INT 2

#define LOG_FILE "altitude_log.txt"

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

#define CHECK_ERR(x) \
	do { \
		if ((x) < 0) { \
			fprintf(stderr, "%s:%d: %s: %s\n", __FILE__, __LINE__, #x, strerror(errno)); \
			goto err; \
		} \
	} while (0)

#define CHECK_ERR_GOTO(x, label) \
	do { \
		if ((x) < 0) { \
			fprintf(stderr, "%s:%d: %s: %s\n", __FILE__, __LINE__, #x, strerror(errno)); \
			goto label; \
		} \
	} while (0)

#define CHECK_ERR_EXIT(x) \
	do { \
		if ((x) < 0) { \
			fprintf(stderr, "%s:%d: %s: %s\n", __FILE__, __LINE__, #x, strerror(errno)); \
			exit(EXIT_FAILURE); \
		} \
	} while (0)

#define CHECK_ERR_EXIT_GOTO(x, label) \
	do { \
		if ((x) < 0) { \
			fprintf(stderr, "%s:%d: %s: %s\n", __FILE__, __LINE__, #x, strerror(errno)); \
			goto label; \
		} \
	} while (0)

static int i2c_fd = -1;
static int log_fd = -1;
static bool logging = false;

static void sigint_handler(int signum)
{
	(void)signum;

	if (i2c_fd >= 0) {
		CHECK_ERR_EXIT(close(i2c_fd));
	}

	if (log_fd >= 0) {
		CHECK_ERR_EXIT(close(log_fd));
	}

	gpioTerminate();

	exit(EXIT_SUCCESS);
}

static int bmp180_read_reg(uint8_t reg, uint8_t *val)
{
	CHECK_ERR(i2c_smbus_write_byte(i2c_fd, reg));
	CHECK_ERR(i2c_smbus_read_byte(i2c_fd));
	*val = (uint8_t)i2c_smbus_data.read_byte;

	return 0;

err:
	return -1;
}

static int bmp180_write_reg(uint8_t reg, uint8_t val)
{
	CHECK_ERR(i2c_smbus_write_byte_data(i2c_fd, reg, val));

	return 0;

err:
	return -1;
}

static int bmp180_read_regs(uint8_t reg, uint8_t *buf, size_t len)
{
	CHECK_ERR(i2c_smbus_write_byte(i2c_fd, reg));
	CHECK_ERR(i2c_smbus_read_i2c_block_data(i2c_fd, len, buf));

	return 0;

err:
	return -1;
}

static int bmp180_read_calib(uint16_t *calib)
{
	uint8_t buf[22];

	CHECK_ERR(bmp180_read_regs(BMP180_REG_CALIB, buf, ARRAY_SIZE(buf)));

	calib[0] = (buf[0] << 8) | buf[1];
	calib[1] = (buf[2] << 8) | buf[3];
	calib[2] = (buf[4] << 8) | buf[5];
	calib[3] = (buf[6] << 8) | buf[7];
	calib[4] = (buf[8] << 8) | buf[9];
	calib[5] = (buf[10] << 8) | buf[11];
	calib[6] = (buf[12] << 8) | buf[13];
	calib[7] = (buf[14] << 8) | buf[15];
	calib[8] = (buf[16] << 8) | buf[17];
	calib[9] = (buf[18] << 8) | buf[19];
	calib[10] = (buf[20] << 8) | buf[21];

	return 0;

err:
	return -1;
}

static int bmp180_read_temp(int32_t *temp)
{
	uint16_t calib[11];
	int32_t ut;
	int32_t x1, x2;

	CHECK_ERR(bmp180_read_calib(calib));
	CHECK_ERR(bmp180_write_reg(BMP180_REG_CTRL, BMP180_CMD_TEMP));
	CHECK_ERR(usleep(5000));
	CHECK_ERR(bmp180_read_reg(BMP180_REG_DATA, (uint8_t *)&ut));

	x1 = ((ut - calib[6]) * calib[5]) >> 15;
	x2 = ((calib[4] * ((x1 >> 11) * (x1 >> 11))) >> 12) >> 11;
	*temp = x1 + x2;

	return 0;

err:
	return -1;
}

static int bmp180_read_press(int32_t *press)
{
	uint16_t calib[11];
	int32_t ut, up;
	int32_t x1, x2, x3, b3, b5, b6, p;
	uint32_t b4, b7;

	CHECK_ERR(bmp180_read_calib(calib));
	CHECK_ERR(bmp180_write_reg(BMP180_REG_CTRL, BMP180_CMD_PRESS | (BMP180_OSS << 6)));
	CHECK_ERR(usleep(25000));
	CHECK_ERR(bmp180_read_reg(BMP180_REG_DATA, (uint8_t *)&ut));
	CHECK_ERR(bmp180_read_regs(BMP180_REG_DATA + 2, (uint8_t *)&up, 2));

	up <<= 8;
	up >>= 8;

