	calib[6] = (buf[12] << 8) | buf[13];
	calib[7] = (buf[14] << 8) | buf[15];
	calib[8] = (buf[16] << 8) | buf[17];
	calib[9] = (buf[18] << 8) | buf[19];
	calib[10] = (buf[20] << 8) | buf[21];

	return 0;

err:
	return -1;
}

static int bmp180_read_temp(int32_t *temp)
{
	uint16_t calib[11];
	int32_t ut;
	int32_t x1, x2;

	CHECK_ERR(bmp180_read_calib(calib));
	CHECK_ERR(bmp180_write_reg(BMP180_REG_CTRL, BMP180_CMD_TEMP));
	CHECK_ERR(usleep(5000));
	CHECK_ERR(bmp180_read_reg(BMP180_REG_DATA, (uint8_t *)&ut));

	x1 = ((ut - calib[6]) * calib[5]) >> 15;
	x2 = ((calib[4] * ((x1 >> 11) * (x1 >> 11))) >> 12) >> 11;
	*temp = x1 + x2;

	return 0;

err:
	return -1;
}

static int bmp180_read_press(int32_t *press)
{
	uint16_t calib[11];
	int32_t ut, up;
	int32_t x1, x2, x3, b3, b5, b6, p;
	uint32_t b4, b7;

	CHECK_ERR(bmp180_read_calib(calib));
	CHECK_ERR(bmp180_write_reg(BMP180_REG_CTRL, BMP180_CMD_PRESS | (BMP180_OSS << 6)));
	CHECK_ERR(usleep(25000));
	CHECK_ERR(bmp180_read_reg(BMP180_REG_DATA, (uint8_t *)&ut));
	CHECK_ERR(bmp180_read_regs(BMP180_REG_DATA + 2, (uint8_t *)&up, 2));

	up <<= 8;
	up >>= 8;

	x1 = ((ut - calib[6]) * calib[5]) >> 15;
	x2 = ((calib[4] * ((x1 >> 11) * (x1 >> 11))) >> 12) >> 11;
	b5 = x1 + x2;
	b6 = b5 - 4000;
	x1 = (calib[2] * ((b6 * b6) >> 12)) >> 11;
	x2 = (calib[1] * b6) >> 11;
	x3 = x1 + x2;
	b3 = (((((int32_t)calib[0]) * 4 + x3) << BMP180_OSS) + 2) >> 2;
	x1 = (calib[9] * b6) >> 13;
	x2 = ((calib[8] * ((b6 * b6) >> 12)) >> 18) >> 12;
	x3 = ((x1 + x2) + 2) >> 2;
	b4 = (calib[7] + x3) << (12 - BMP180_OSS);
	b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
	if (b7 < 0x80000000) {
		p = (b7 << 1) / b4;
	} else {
		p = (b7 / b4) << 1;
	}
	x1 = (p >> 8) * (p >> 8);
	x1 = (x1 * 3038) >> 16;
	x2 = (-7357 * p) >> 16;
	*press = p + ((x1 + x2 + 3791) >> 4);

	return 0;

err:
	return -1;
}

static int bmp180_read_alt(double *alt)
{
	int32_t temp, press;

	CHECK_ERR(bmp180_read_temp(&temp));
	CHECK_ERR(bmp180_read_press(&press));

	*alt = 44330.0 * (1.0 - pow(press / 101325.0, 0.190295));

	return 0;

err:
	return -1;
}

static void log_altitude(void)
{
	double alt;
	char buf[1024];
	time_t t;
	struct tm tm;

	CHECK_ERR_GOTO(bmp180_read_alt(&alt), err);

	t = time(NULL);
	CHECK_ERR_GOTO(localtime_r(&t, &tm), err);
	CHECK_ERR_GOTO(strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm), err);

	CHECK_ERR_GOTO(dprintf(log_fd, "%s,%.2f\n", buf, alt), err);

	return;

err:
	return;
}

static void gpio_int_handler(int gpio, int level, uint32_t tick)
{
	(void)gpio;
	(void)level;
	(void)tick;

	if (logging) {
		log_altitude();
	}
}

