#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34
#define BMP180_CMD_PRESSURE_OSS0 0x34
#define BMP180_CMD_PRESSURE_OSS1 0x74
#define BMP180_CMD_PRESSURE_OSS2 0xB4
#define BMP180_CMD_PRESSURE_OSS3 0xF4
#define BMP180_CALIB_AC1 0xAA
#define BMP180_CALIB_AC2 0xAC
#define BMP180_CALIB_AC3 0xAE
#define BMP180_CALIB_AC4 0xB0
#define BMP180_CALIB_AC5 0xB2
#define BMP180_CALIB_AC6 0xB4
#define BMP180_CALIB_B1 0xB6
#define BMP180_CALIB_B2 0xB8
#define BMP180_CALIB_MB 0xBA
#define BMP180_CALIB_MC 0xBC
#define BMP180_CALIB_MD 0xBE

#define BMP180_I2C_BUS 1
#define BMP180_I2C_FREQ 100000
#define BMP180_I2C_TIMEOUT 1000

#define BMP180_TIMER_FREQ 20
#define BMP180_TIMER_TIMEOUT 50

#define BMP180_ALERT_GPIO 24

#define BMP180_BUFFER_SIZE 60

#define BMP180_PRESSURE_DEVIATION 5

typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calib_t;

typedef struct {
    time_t timestamp;
    int32_t pressure;
} bmp180_buffer_t;

static bmp180_calib_t bmp180_calib;
static bmp180_buffer_t bmp180_buffer[BMP180_BUFFER_SIZE];
static int32_t bmp180_buffer_index = 0;
static int32_t bmp180_buffer_count = 0;
static int32_t bmp180_buffer_sum = 0;
static int32_t bmp180_buffer_average = 0;
static int32_t bmp180_buffer_last = 0;
static bool bmp180_alert = false;

static int bmp180_i2c_handle = -1;
static int bmp180_timer_handle = -1;

static void bmp180_buffer_reset(void)
{
    bmp180_buffer_index = 0;
    bmp180_buffer_count = 0;
    bmp180_buffer_sum = 0;
    bmp180_buffer_average = 0;
    bmp180_buffer_last = 0;
    bmp180_alert = false;
}

static void bmp180_buffer_add(int32_t pressure)
{
    bmp180_buffer[bmp180_buffer_index].timestamp = time(NULL);
    bmp180_buffer[bmp180_buffer_index].pressure = pressure;

    bmp180_buffer_index = (bmp180_buffer_index + 1) % BMP180_BUFFER_SIZE;

    if (bmp180_buffer_count < BMP180_BUFFER_SIZE) {
        bmp180_buffer_count++;
    }

    bmp180_buffer_sum += pressure;
    bmp180_buffer_average = bmp180_buffer_sum / bmp180_buffer_count;

    if (abs(pressure - bmp180_buffer_average) > BMP180_PRESSURE_DEVIATION) {
        bmp180_alert = true;
    }
}

static void bmp180_buffer_print(void)
{
    for (int i = 0; i < bmp180_buffer_count; i++) {
        int index = (bmp180_buffer_index + i) % BMP180_BUFFER_SIZE;
        printf("%ld %ld\n", bmp180_buffer[index].timestamp, bmp180_buffer[index].pressure);
    }
}

static int bmp180_i2c_init(void)
{
    if (bmp180_i2c_handle >= 0) {
        return bmp180_i2c_handle;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    if ((bmp180_i2c_handle = i2cOpen(BMP180_I2C_BUS, BMP180_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", BMP180_I2C_BUS);
        return -1;
    }

    if (i2cSetSlaveAddress(bmp180_i2c_handle, BMP180_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return -1;
    }

    if (i2cSetBusSpeed(bmp180_i2c_handle, BMP180_I2C_FREQ) < 0) {
        fprintf(stderr, "Failed to set I2C bus speed\n");
        return -1;
    }

    if (i2cSetTimeout(bmp180_i2c_handle, BMP180_I2C_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to set I2C timeout\n");
        return -1;
    }

    return bmp180_i2c_handle;
}

static void bmp180_i2c_deinit(void)
{
    if (bmp180_i2c_handle >= 0) {
        i2cClose(bmp180_i2c_handle);
        bmp180_i2c_handle = -1;
    }

    gpioTerminate();
}

static int bmp180_i2c_read(uint8_t reg, uint8_t *data, size_t size)
{
    if (bmp180_i2c_handle < 0) {
        return -1;
    }

    if (i2cWriteByteData(bmp180_i2c_handle, reg) < 0) {
        fprintf(stderr, "Failed to write I2C register\n");
        return -1;
    }

    if (i2cReadDevice(bmp180_i2c_handle, data, size) < 0) {
        fprintf(stderr, "Failed to read I2C data\n");
        return -1;
    }

    return 0;
}

static int bmp180_i2c_write(uint8_t reg, uint8_t data)
{
    if (bmp180_i2c_handle < 0) {
        return -1;
    }

    if (i2cWriteByteData(bmp180_i2c_handle, reg, data) < 0) {
        fprintf(stderr, "Failed to write I2C data\n");
        return -1;
    }

    return 0;
}

static int bmp180_calib_read(void)
{
    uint8_t data[22];

    if (bmp180_i2c_read(BMP180_REG_CALIB, data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    bmp180_calib.ac1 = (data[0] << 8) | data[1];
    bmp180_calib.ac2 = (data[2] << 8) | data[3];
    bmp180_calib.ac3 = (data[4] << 8) | data[5];
    bmp180_calib.ac4 = (data[6] << 8) | data[7];
    bmp180_calib.ac5 = (data[8] << 8) | data[9];
    bmp180_calib.ac6 = (data[10] << 8) | data[11];
    bmp180_calib.b1 = (data[12] << 8) | data[13];
    bmp180_calib.b2 = (data[14] << 8) | data[15];
    bmp180_calib.mb = (data[16] << 8) | data[17];
    bmp180_calib.mc = (data[18] << 8) | data[19];
    bmp180_calib.md = (data[20] << 8) | data[21];

    return 0;
}

static int bmp180_temp_read(int32_t *temp)
{
    uint8_t data[2];

    if (bmp180_i2c_write(BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1;
    }

    if (bmp180_i2c_read(BMP180_REG_RESULT, data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    *temp = (data[0] << 8) | data[1];

    return 0;
}

static int bmp180_pressure_read(int32_t *pressure)
{
    uint8_t data[3];

    if (bmp180_i2c_write(BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS3) < 0) {
        fprintf(stderr, "Failed to write pressure command\n");
        return -1;
    }

    if (bmp180_i2c_read(BMP180_REG_RESULT, data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to read pressure data\n");
        return -1;
    }

    *pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - 3);

    return 0;
}

static int bmp180_timer_init(void)
{
    if (bmp180_timer_handle >= 0) {
        return bmp180_timer_handle;
    }

    if ((bmp180_timer_handle = gpioSetTimerFuncEx(BMP180_TIMER_FREQ, BMP180_TIMER_TIMEOUT, NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to set timer\n");
        return -1;
    }

    return bmp180_timer_handle;
}

static void bmp180_timer_deinit(void)
{
    if (bmp180_timer_handle >= 0) {
        gpioSetTimerFuncEx(BMP180_TIMER_FREQ, 0, NULL, NULL);
        bmp180_timer_handle = -1;
    }
}

static int bmp180_alert_init(void)
{
    if (gpioSetMode(BMP180_ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set alert GPIO mode\n");
        return -1;
    }

    if (gpioWrite(BMP180_ALERT_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write alert GPIO\n");
        return -1;
    }

    return 0;
}

static void bmp180_alert_deinit(void)
{
    if (gpioSetMode(BMP180_ALERT_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set alert GPIO mode\n");
    }

    if (gpioWrite(BMP180_ALERT_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write alert GPIO\n");
    }
}

static void bmp180_alert_set(bool alert)
{
    if (gpioWrite(BMP180_ALERT_GPIO, alert ? PI_HIGH : PI_LOW) < 0) {
        fprintf(stderr, "Failed to write alert GPIO\n");
    }
}

static void bmp180_sample(void)
{
    int32_t temp;
    int32_t pressure;
    int32_t x1;
    int32_t x2;
    int32_t b5;
    int32_t b6;
    int32_t x3;
    int32_t b3;
    int32_t b4;
    int32_t b7;
    int32_t p;

    if (bmp180_temp_read(&temp) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return;
    }

    if (bmp180_pressure_read(&pressure) < 0) {
        fprintf(stderr, "Failed to read pressure\n");
        return;
    }

    x1 = (temp - bmp180_calib.ac6) * bmp180_calib.ac5 >> 15;
    x2 = (bmp180_calib.mc << 11) / (x1 + bmp180_calib.md);
    b5 = x1 + x2;
    b6 = b5 - 4000;
    x3 = (bmp180_calib.b2 * (b6 * b6 >> 12)) >> 11;
    b3 = ((bmp180_calib.ac1 * 4 + x3) + 2) / 4;
    x1 = (bmp180_calib.ac3 * b6) >> 13;
    x2 = (bmp180_calib.b1 * (b6 * b6 >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (bmp180_calib.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)pressure - b3) * (50000 >> 3);

    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    bmp180_buffer_add(p);

    if (bmp180_alert) {
        bmp180_alert_set(true);
    }
}

static void bmp180_signal_handler(int signum)
{
    bmp180_i2c_deinit();
    bmp180_timer_deinit();
    bmp180_alert_deinit();
}

int main(void)
{
    if (bmp180_i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    if (bmp180_calib_read() < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return EXIT_FAILURE;
    }

    if (bmp180_timer_init() < 0) {
        fprintf(stderr, "Failed to initialize timer\n");
        return EXIT_FAILURE;
    }

    if (bmp180_alert_init() < 0) {
        fprintf(stderr, "Failed to initialize alert GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, bmp180_signal_handler);

    while (true) {
        bmp180_sample();
    }

    return EXIT_SUCCESS;
}
