{
    uint8_t data[22];

    if (bmp180_i2c_read(BMP180_REG_CALIB, data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    bmp180_calib.ac1 = (data[0] << 8) | data[1];
    bmp180_calib.ac2 = (data[2] << 8) | data[3];
    bmp180_calib.ac3 = (data[4] << 8) | data[5];
    bmp180_calib.ac4 = (data[6] << 8) | data[7];
    bmp180_calib.ac5 = (data[8] << 8) | data[9];
    bmp180_calib.ac6 = (data[10] << 8) | data[11];
    bmp180_calib.b1 = (data[12] << 8) | data[13];
    bmp180_calib.b2 = (data[14] << 8) | data[15];
    bmp180_calib.mb = (data[16] << 8) | data[17];
    bmp180_calib.mc = (data[18] << 8) | data[19];
    bmp180_calib.md = (data[20] << 8) | data[21];

    return 0;
}

static int bmp180_temp_read(int32_t *temp)
{
    uint8_t data[2];

    if (bmp180_i2c_write(BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1;
    }

    if (bmp180_i2c_read(BMP180_REG_RESULT, data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    *temp = (data[0] << 8) | data[1];

    return 0;
}

static int bmp180_pressure_read(int32_t *pressure)
{
    uint8_t data[3];

    if (bmp180_i2c_write(BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS3) < 0) {
        fprintf(stderr, "Failed to write pressure command\n");
        return -1;
    }

    if (bmp180_i2c_read(BMP180_REG_RESULT, data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to read pressure data\n");
        return -1;
    }

    *pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - 3);

    return 0;
}

static int bmp180_timer_init(void)
{
    if (bmp180_timer_handle >= 0) {
        return bmp180_timer_handle;
    }

    if ((bmp180_timer_handle = gpioSetTimerFuncEx(BMP180_TIMER_FREQ, BMP180_TIMER_TIMEOUT, NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to set timer\n");
        return -1;
    }

    return bmp180_timer_handle;
}

static void bmp180_timer_deinit(void)
{
    if (bmp180_timer_handle >= 0) {
        gpioSetTimerFuncEx(BMP180_TIMER_FREQ, 0, NULL, NULL);
        bmp180_timer_handle = -1;
    }
}

static int bmp180_alert_init(void)
{
    if (gpioSetMode(BMP180_ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set alert GPIO mode\n");
        return -1;
    }

    if (gpioWrite(BMP180_ALERT_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write alert GPIO\n");
        return -1;
    }

    return 0;
}

static void bmp180_alert_deinit(void)
{
    if (gpioSetMode(BMP180_ALERT_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set alert GPIO mode\n");
    }

    if (gpioWrite(BMP180_ALERT_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write alert GPIO\n");
    }
}

static void bmp180_alert_set(bool alert)
{
    if (gpioWrite(BMP180_ALERT_GPIO, alert ? PI_HIGH : PI_LOW) < 0) {
        fprintf(stderr, "Failed to write alert GPIO\n");
    }
}

static void bmp180_sample(void)
{
    int32_t temp;
    int32_t pressure;
    int32_t x1;
    int32_t x2;
    int32_t b5;
    int32_t b6;
    int32_t x3;
    int32_t b3;
    int32_t b4;
    int32_t b7;
    int32_t p;

    if (bmp180_temp_read(&temp) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return;
    }

    if (bmp180_pressure_read(&pressure) < 0) {
        fprintf(stderr, "Failed to read pressure\n");
        return;
    }

    x1 = (temp - bmp180_calib.ac6) * bmp180_calib.ac5 >> 15;
    x2 = (bmp180_calib.mc << 11) / (x1 + bmp180_calib.md);
    b5 = x1 + x2;
    b6 = b5 - 4000;
    x3 = (bmp180_calib.b2 * (b6 * b6 >> 12)) >> 11;
    b3 = ((bmp180_calib.ac1 * 4 + x3) + 2) / 4;
    x1 = (bmp180_calib.ac3 * b6) >> 13;
    x2 = (bmp180_calib.b1 * (b6 * b6 >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (bmp180_calib.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)pressure - b3) * (50000 >> 3);

    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    bmp180_buffer_add(p);

    if (bmp180_alert) {
        bmp180_alert_set(true);
    }
}

static void bmp180_signal_handler(int signum)
{
    bmp180_i2c_deinit();
    bmp180_timer_deinit();
    bmp180_alert_deinit();
}

int main(void)
{
    if (bmp180_i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    if (bmp180_calib_read() < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return EXIT_FAILURE;
    }

    if (bmp180_timer_init() < 0) {
        fprintf(stderr, "Failed to initialize timer\n");
        return EXIT_FAILURE;
    }

    if (bmp180_alert_init() < 0) {
        fprintf(stderr, "Failed to initialize alert GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, bmp180_signal_handler);

    while (true) {
        bmp180_sample();
    }

    return EXIT_SUCCESS;
}
