#include <linux/types.h>
#include <linux/gpio.h>
#include <linux/timerfd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define I2C_PATH "/dev/i2c-1"
#define I2C_TIMEOUT 1000000
#define I2C_RETRIES 3
#define I2C_DELAY 100000

#define BMP180_REG_AC1 0xAA
#define BMP180_REG_AC2 0xAC
#define BMP180_REG_AC3 0xAE
#define BMP180_REG_AC4 0xB0
#define BMP180_REG_AC5 0xB2
#define BMP180_REG_AC6 0xB4
#define BMP180_REG_B1 0xB6
#define BMP180_REG_B2 0xB8
#define BMP180_REG_MB 0xBA
#define BMP180_REG_MC 0xBC
#define BMP180_REG_MD 0xBE
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_CMD_TEMPERATURE 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x74
#define BMP180_CMD_PRESSURE2 0xB4
#define BMP180_CMD_PRESSURE3 0xF4

#define BMP180_LOG_FILE "bmp180_log.txt"

#define ARRAY_SIZE(x) (sizeof(x) / sizeof((x)[0]))

static int i2c_fd = -1;
static int timer_fd = -1;
static bool running = true;

static void cleanup(void)
{
    if (timer_fd >= 0) {
        close(timer_fd);
        timer_fd = -1;
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void signal_handler(int signum)
{
    running = false;
}

static int i2c_read(uint8_t reg, uint8_t *buf, size_t len)
{
    int ret;

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_smbus_write_byte(i2c_fd, reg);
    if (ret < 0) {
        fprintf(stderr, "Failed to write register: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, reg, len, buf);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_write(uint8_t reg, uint8_t *buf, size_t len)
{
    int ret;
    uint8_t data[len + 1];

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return -1;
    }

    data[0] = reg;
    memcpy(&data[1], buf, len);

    ret = i2c_smbus_write_i2c_block_data(i2c_fd, reg, len, data);
    if (ret < 0) {
        fprintf(stderr, "Failed to write data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int bmp180_read_calibration(int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md)
{
    uint8_t buf[2];
    int ret;

    ret = i2c_read(BMP180_REG_AC1, buf, 2);
    if (ret < 0)
        return -1;
    *ac1 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_AC2, buf, 2);
    if (ret < 0)
        return -1;
    *ac2 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_AC3, buf, 2);
    if (ret < 0)
        return -1;
    *ac3 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_AC4, buf, 2);
    if (ret < 0)
        return -1;
    *ac4 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_AC5, buf, 2);
    if (ret < 0)
        return -1;
    *ac5 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_AC6, buf, 2);
    if (ret < 0)
        return -1;
    *ac6 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_B1, buf, 2);
    if (ret < 0)
        return -1;
    *b1 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_B2, buf, 2);
    if (ret < 0)
        return -1;
    *b2 = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_MB, buf, 2);
    if (ret < 0)
        return -1;
    *mb = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_MC, buf, 2);
    if (ret < 0)
        return -1;
    *mc = (buf[0] << 8) | buf[1];

    ret = i2c_read(BMP180_REG_MD, buf, 2);
    if (ret < 0)
        return -1;
    *md = (buf[0] << 8) | buf[1];

    return 0;
}

static int bmp180_read_temperature(int32_t *temperature)
{
    uint8_t buf[2];
    int32_t ut;
    int ret;

    ret = i2c_write(BMP180_REG_CONTROL, &BMP180_CMD_TEMPERATURE, 1);
    if (ret < 0)
        return -1;

    usleep(5000);

    ret = i2c_read(BMP180_REG_RESULT, buf, 2);
    if (ret < 0)
        return -1;
    ut = (buf[0] << 8) | buf[1];

    *temperature = (ut + 8) >> 4;

    return 0;
}

static int bmp180_read_pressure(int32_t *pressure)
{
    uint8_t buf[3];
    int32_t up;
    int ret;

    ret = i2c_write(BMP180_REG_CONTROL, &BMP180_CMD_PRESSURE0, 1);
    if (ret < 0)
        return -1;

    usleep(5000);

    ret = i2c_read(BMP180_REG_RESULT, buf, 3);
    if (ret < 0)
        return -1;
    up = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;

    *pressure = (up + 8) >> 4;

    return 0;
}

static int bmp180_read_data(int32_t *temperature, int32_t *pressure)
{
    int ret;

    ret = bmp180_read_temperature(temperature);
    if (ret < 0)
        return -1;

    ret = bmp180_read_pressure(pressure);
    if (ret < 0)
        return -1;

    return 0;
}

static int bmp180_log_data(int32_t temperature, int32_t pressure)
{
    FILE *fp;
    int ret;

    fp = fopen(BMP180_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    ret = fprintf(fp, "%d %d\n", temperature, pressure);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return 0;
}

static int timer_init(void)
{
    struct itimerspec ts;
    int ret;

    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        return -1;
    }

    ts.it_interval.tv_sec = 0;
    ts.it_interval.tv_nsec = 500000000;
    ts.it_value.tv_sec = 0;
    ts.it_value.tv_nsec = 500000000;

    ret = timerfd_settime(timer_fd, 0, &ts, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        close(timer_fd);
        timer_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_init(void)
{
    int ret;

    i2c_fd = open(I2C_PATH, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_TIMEOUT, I2C_TIMEOUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C timeout: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_RETRIES, I2C_RETRIES);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C retries: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int main(void)
{
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
    int32_t temperature, pressure;
    int ret;

    ret = i2c_init();
    if (ret < 0)
        goto error;

    ret = timer_init();
    if (ret < 0)
        goto error;

    ret = bmp180_read_calibration(&ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md);
    if (ret < 0)
        goto error;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        ret = read(timer_fd, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to read timer: %s\n", strerror(errno));
            goto error;
        }

        ret = bmp180_read_data(&temperature, &pressure);
        if (ret < 0)
            goto error;

        ret = bmp180_log_data(temperature, pressure);
        if (ret < 0)
            goto error;
    }

    cleanup();
    return 0;

error:
    cleanup();
    return -1;
}

