#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_CTRL 0xF4
#define BMP180_REG_DATA 0xF6
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRES 0x34
#define BMP180_OSS 0
#define BMP180_BUF_SIZE 60

typedef struct {
    int16_t AC1;
    int16_t AC2;
    int16_t AC3;
    uint16_t AC4;
    uint16_t AC5;
    uint16_t AC6;
    int16_t B1;
    int16_t B2;
    int16_t MB;
    int16_t MC;
    int16_t MD;
} bmp180_calib_t;

typedef struct {
    uint32_t timestamp;
    int32_t temp;
    int32_t pres;
} bmp180_sample_t;

static int bmp180_fd = -1;
static bmp180_calib_t bmp180_calib;
static bmp180_sample_t bmp180_buf[BMP180_BUF_SIZE];
static int bmp180_buf_head = 0;
static int bmp180_buf_tail = 0;
static int bmp180_buf_count = 0;
static int bmp180_fan_gpio = 18;
static int bmp180_fan_gpio_fd = -1;
static int bmp180_timer_id = -1;

static int bmp180_i2c_open(void)
{
    int fd;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to select I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int bmp180_i2c_read(uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(bmp180_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(bmp180_fd, buf, len) != len) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int bmp180_i2c_write(uint8_t reg, uint8_t val)
{
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = val;

    if (write(bmp180_fd, buf, 2) != 2) {
