#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 2000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define SPI_CS 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11
#define RELAY_PIN 17
#define MAX_DUTY_CYCLE 80
#define DEFAULT_TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"

static int spi_fd = -1;
static int duty_cycle = 0;
static double target_temp = DEFAULT_TARGET_TEMP;
static FILE *log_file = NULL;

static void cleanup(void)
{
    if (spi_fd >= 0) {
        gpioSetMode(SPI_CS, PI_INPUT);
        gpioSetMode(SPI_MISO, PI_INPUT);
        gpioSetMode(SPI_MOSI, PI_INPUT);
        gpioSetMode(SPI_SCLK, PI_INPUT);
        gpioSetMode(RELAY_PIN, PI_INPUT);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static void handle_error(const char *msg)
{
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    cleanup();
    exit(EXIT_FAILURE);
}

static void handle_signal(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static void set_duty_cycle(int duty_cycle)
{
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }
    gpioPWM(RELAY_PIN, duty_cycle);
    printf("Duty cycle set to %d%%\n", duty_cycle);
}

static void log_measurement(double temp, int duty_cycle)
{
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temp, duty_cycle);
    fflush(log_file);
}

static double read_temperature(void)
{
    uint8_t tx_buf[3] = {0};
    uint8_t rx_buf[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = sizeof(tx_buf),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        handle_error("SPI transfer failed");
    }

    uint16_t raw_temp = (rx_buf[0] << 8) | rx_buf[1];
    if (raw_temp & 0x4) {
        return NAN;
    }
    uint16_t temp = (raw_temp >> 2) & 0x3FFF;
    if (raw_temp & 0x2) {
        temp |= 0xC000;
    }
    return temp * 0.25;
}

static void control_loop(void)
{
    double temp = read_temperature();
    if (isnan(temp)) {
        set_duty_cycle(0);
        log_measurement(temp, 0);
        return;
    }
    double error = target_temp - temp;
    int new_duty_cycle = duty_cycle + error;
    set_duty_cycle(new_duty_cycle);
    log_measurement(temp, new_duty_cycle);
}

int main(int argc, char *argv[])
{
    if (argc > 1) {
        target_temp = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize GPIO");
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        handle_error("Failed to open SPI device");
    }

    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(SPI_CS, 1);
    gpioWrite(RELAY_PIN, 0);

    if (gpioSetPWMfrequency(RELAY_PIN, 1000) < 0) {
        handle_error("Failed to set PWM frequency");
    }

    if (gpioSetPWMrange(RELAY_PIN, 100) < 0) {
        handle_error("Failed to set PWM range");
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    fprintf(log_file, "Timestamp,Temperature,Duty Cycle\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (true) {
        control_loop();
        sleep(1);
    }

    return 0;
}
