#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define MAX_TEMP 65
#define MIN_TEMP 45
#define MAX_FAN_SPEED 3
#define MIN_FAN_SPEED 0
#define POLL_INTERVAL 5

int fan_speed = -1;

void log_event(char *event)
{
    FILE *log_file;
    time_t t;
    struct tm *tm;
    char time_string[64];

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    t = time(NULL);
    tm = localtime(&t);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s: %s\n", time_string, event);
    fclose(log_file);
}

int get_fan_speed()
{
    FILE *fan_file;
    int speed;

    fan_file = fopen(FAN_FILE, "r");
    if (fan_file == NULL) {
        fprintf(stderr, "Error opening fan file: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fan_file, "%d", &speed) != 1) {
        fprintf(stderr, "Error reading fan file: %s\n", strerror(errno));
        fclose(fan_file);
        return -1;
    }

    fclose(fan_file);
    return speed;
}

int get_max_fan_speed()
{
    FILE *max_state_file;
    int max_state;

    max_state_file = fopen(MAX_STATE_FILE, "r");
    if (max_state_file == NULL) {
        fprintf(stderr, "Error opening max state file: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(max_state_file, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max state file: %s\n", strerror(errno));
        fclose(max_state_file);
        return -1;
    }

    fclose(max_state_file);
    return max_state;
}

int get_cpu_temp()
{
    FILE *temp_file;
    int temp;

    temp_file = fopen(TEMP_FILE, "r");
    if (temp_file == NULL) {
        fprintf(stderr, "Error opening temp file: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(temp_file, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temp file: %s\n", strerror(errno));
        fclose(temp_file);
        return -1;
    }

    fclose(temp_file);
    return temp / 1000;
}

int set_fan_speed(int speed)
{
    FILE *fan_file;

    fan_file = fopen(FAN_FILE, "w");
    if (fan_file == NULL) {
        fprintf(stderr, "Error opening fan file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fan_file, "%d", speed) < 0) {
        fprintf(stderr, "Error writing fan file: %s\n", strerror(errno));
        fclose(fan_file);
        return -1;
    }

    fclose(fan_file);
    return 0;
}

void shutdown_fan()
{
    if (fan_speed != MIN_FAN_SPEED) {
        if (set_fan_speed(MIN_FAN_SPEED) == 0) {
            log_event("Fan shutdown");
        }
    }
}

void handle_signal(int signal)
{
    shutdown_fan();
    exit(0);
}

int main()
{
    int cpu_temp;
    int max_fan_speed;
    int new_fan_speed;
    char event[128];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        cpu_temp = get_cpu_temp();
        if (cpu_temp == -1) {
            sleep(POLL_INTERVAL);
            continue;
        }

        max_fan_speed = get_max_fan_speed();
        if (max_fan_speed == -1) {
            sleep(POLL_INTERVAL);
            continue;
        }

        if (cpu_temp < MIN_TEMP) {
            new_fan_speed = MIN_FAN_SPEED;
        } else if (cpu_temp < MAX_TEMP) {
            new_fan_speed = (cpu_temp - MIN_TEMP) / 10;
        } else {
            new_fan_speed = MAX_FAN_SPEED;
        }

        if (new_fan_speed > max_fan_speed) {
            new_fan_speed = max_fan_speed;
        }

        if (new_fan_speed != fan_speed) {
            if (set_fan_speed(new_fan_speed) == 0) {
                fan_speed = new_fan_speed;
                sprintf(event, "Fan speed changed to %d", fan_speed);
                log_event(event);
            }
        }

        sleep(POLL_INTERVAL);
    }

    return 0;
}

