#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 25000
#define PWM_RANGE 1024
#define PWM_MIN 0
#define PWM_MAX 1024
#define TEMP_MIN 40
#define TEMP_MAX 70
#define TEMP_RANGE 30
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    FILE *tempFile, *logFile;
    char tempString[10];
    int temp, pwmDuty;
    time_t now;
    struct tm *timeInfo;
    char timeString[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        return 1;
    }

    if ((tempFile = fopen(TEMP_FILE, "r")) == NULL) {
        fprintf(stderr, "fopen failed\n");
        return 1;
    }

    if ((logFile = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "fopen failed\n");
        return 1;
    }

    fprintf(logFile, "Timestamp,Temperature,PWM Duty\n");

    signal(SIGINT, intHandler);

    while (keepRunning) {
        if (fgets(tempString, 10, tempFile) == NULL) {
            fprintf(stderr, "fgets failed\n");
            return 1;
        }

        temp = atoi(tempString) / 1000;
        pwmDuty = (temp - TEMP_MIN) * (PWM_MAX - PWM_MIN) / TEMP_RANGE + PWM_MIN;

        if (gpioPWM(PWM_PIN, pwmDuty) != 0) {
            fprintf(stderr, "gpioPWM failed\n");
            return 1;
        }

        time(&now);
        timeInfo = localtime(&now);
        strftime(timeString, 20, "%Y-%m-%d %H:%M:%S", timeInfo);

        fprintf(logFile, "%s,%d,%d\n", timeString, temp, pwmDuty);

        sleep(5);
    }

    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return 1;
    }

    if (gpioTerminate() != 0) {
        fprintf(stderr, "gpioTerminate failed\n");
        return 1;
    }

    if (fclose(tempFile) != 0) {
        fprintf(stderr, "fclose failed\n");
        return 1;
    }

    if (fclose(logFile) != 0) {
        fprintf(stderr, "fclose failed\n");
        return 1;
    }

    return 0;
}

