#define I2C_ADDR_2 0x41
#define I2C_REG_1 0x00
#define I2C_REG_2 0x00
#define I2C_DATA_LEN 3
#define I2C_RETRIES 3
#define I2C_TIMEOUT 1000
#define I2C_DELAY 1000000
#define LOG_FILE "flow_log.txt"

static int i2c_fd_1 = -1;
static int i2c_fd_2 = -1;
static int log_fd = -1;
static int running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

static int i2c_open(int addr)
{
    int fd;
    char dev_path[20];

    snprintf(dev_path, sizeof(dev_path), "/dev/i2c-%d", I2C_BUS);
    fd = open(dev_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *data, int len)
{
    int ret;

    ret = i2c_smbus_write_byte(fd, reg);
    if (ret < 0) {
        fprintf(stderr, "Failed to write register: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_smbus_read_i2c_block_data(fd, reg, len, data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_close(int fd)
{
    return close(fd);
}

static int log_open(void)
{
    int fd;

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

static int log_write(int fd, const char *buf, int len)
{
    int ret;

    ret = write(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_close(int fd)
{
    return close(fd);
}

static int crc8(const uint8_t *data, int len)
{
    int i, j;
    uint8_t crc = 0xFF;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }

    return crc;
}

static int read_sensor(int fd, uint8_t reg, uint8_t *data, int len)
{
    int i, ret;

    for (i = 0; i < I2C_RETRIES; i++) {
        ret = i2c_read(fd, reg, data, len);
        if (ret == 0) {
            if (crc8(data, len - 1) == data[len - 1])
                return 0;
        }
    }

    return -1;
}

