        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *data, int len)
{
    int ret;

    ret = i2c_smbus_write_byte(fd, reg);
    if (ret < 0) {
        fprintf(stderr, "Failed to write register: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_smbus_read_i2c_block_data(fd, reg, len, data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_close(int fd)
{
    return close(fd);
}

static int log_open(void)
{
    int fd;

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

static int log_write(int fd, const char *buf, int len)
{
    int ret;

    ret = write(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_close(int fd)
{
    return close(fd);
}

static int crc8(const uint8_t *data, int len)
{
    int i, j;
    uint8_t crc = 0xFF;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }

    return crc;
}

static int read_sensor(int fd, uint8_t reg, uint8_t *data, int len)
{
    int i, ret;

    for (i = 0; i < I2C_RETRIES; i++) {
        ret = i2c_read(fd, reg, data, len);
        if (ret == 0) {
            if (crc8(data, len - 1) == data[len - 1])
                return 0;
        }
    }

    return -1;
}

int main(void)
{
    uint8_t data[I2C_DATA_LEN];
    char buf[100];
    time_t t;
    struct tm *tm;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd_1 = i2c_open(I2C_ADDR_1);
    if (i2c_fd_1 < 0)
        goto error;

    i2c_fd_2 = i2c_open(I2C_ADDR_2);
    if (i2c_fd_2 < 0)
        goto error;

    log_fd = log_open();
    if (log_fd < 0)
        goto error;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        if (read_sensor(i2c_fd_1, I2C_REG_1, data, I2C_DATA_LEN) == 0 &&
            read_sensor(i2c_fd_2, I2C_REG_2, data + I2C_DATA_LEN, I2C_DATA_LEN) == 0) {
            t = time(NULL);
            tm = localtime(&t);
            snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
                     tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                     tm->tm_hour, tm->tm_min, tm->tm_sec,
                     (data[0] << 8) | data[1], (data[3] << 8) | data[4]);
            log_write(log_fd, buf, strlen(buf));
        }
        usleep(I2C_DELAY);
    }

    log_close(log_fd);
    i2c_close(i2c_fd_2);
    i2c_close(i2c_fd_1);
    gpioTerminate();

    return EXIT_SUCCESS;

