static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    FILE *fp;
    int gpioA, gpioB;
    int lastGpioA, lastGpioB;
    int state;
    int lastState;
    int position;
    int lastPosition;
    struct timespec timestamp;
    char timestampStr[256];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    gpioA = gpioSetMode(GPIO_A, PI_INPUT);
    gpioB = gpioSetMode(GPIO_B, PI_INPUT);

    if (gpioA < 0 || gpioB < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(GPIO_A, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_B, PI_PUD_UP);

    if (gpioA < 0 || gpioB < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetAlertFunc(GPIO_A, NULL);
    gpioSetAlertFunc(GPIO_B, NULL);

    if (gpioA < 0 || gpioB < 0) {
        fprintf(stderr, "gpioSetAlertFunc failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    lastGpioA = gpioRead(GPIO_A);
    lastGpioB = gpioRead(GPIO_B);
    lastState = (lastGpioA << 1) | lastGpioB;
    lastPosition = 0;

    while (keepRunning) {
        gpioA = gpioRead(GPIO_A);
        gpioB = gpioRead(GPIO_B);
        state = (gpioA << 1) | gpioB;

        if (state != lastState) {
            position = lastPosition;

            if (state == 0 && lastState == 1) {
                position += 1;
            } else if (state == 1 && lastState == 2) {
                position += 1;
            } else if (state == 2 && lastState == 3) {
                position += 1;
            } else if (state == 3 && lastState == 0) {
                position += 1;
            } else if (state == 3 && lastState == 2) {
                position -= 1;
            } else if (state == 2 && lastState == 1) {
                position -= 1;
            } else if (state == 1 && lastState == 0) {
                position -= 1;
            } else if (state == 0 && lastState == 3) {
                position -= 1;
            }

            if (position < 0) {
                position += 360;
            } else if (position >= 360) {
                position -= 360;
            }

            clock_gettime(CLOCK_REALTIME, &timestamp);
            strftime(timestampStr, sizeof(timestampStr), "%Y-%m-%d %H:%M:%S", localtime(&timestamp.tv_sec));

            fprintf(fp, "%s.%09ld, %d\n", timestampStr, timestamp.tv_nsec, position);
            fflush(fp);

            lastState = state;
            lastPosition = position;
        }
    }

    fclose(fp);
    gpioTerminate();

    return 0;
}

