#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define LOG_INTERVAL 1000

static volatile int pulse_count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file;

static void sig_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerminate();
        fclose(log_file);
        pthread_mutex_destroy(&mutex);
        exit(EXIT_SUCCESS);
    }
}

static void isr_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        pulse_count++;
        pthread_mutex_unlock(&mutex);
    }
}

int main(void)
{
    int ret;
    struct timespec ts;
    double rpm;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library: %s\n", gpioGetError(ret));
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO pin mode: %s\n", gpioGetError(ret));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO pin pull-down resistor: %s\n", gpioGetError(ret));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetAlertFunc(GPIO_PIN, isr_callback);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO pin alert function: %s\n", gpioGetError(ret));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += LOG_INTERVAL / 1000;
        ts.tv_nsec += (LOG_INTERVAL % 1000) * 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }

        pthread_mutex_lock(&mutex);
        rpm = pulse_count * 60.0 / LOG_INTERVAL;
        pulse_count = 0;
        pthread_mutex_unlock(&mutex);

        fprintf(log_file, "%ld.%09ld,%.2f\n", ts.tv_sec, ts.tv_nsec, rpm);
        fflush(log_file);

        ret = clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL);
        if (ret != 0) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            break;
        }
    }

    gpioTerminate();
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    return EXIT_FAILURE;
}

