#include <sys/types.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY 0

#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24

#define FRAME_SIZE 32768
#define FRAME_PERIOD 100000

#define MAGIC_NUMBER 4144

#define CONFIG_START_FREQ 77000000000
#define CONFIG_END_FREQ 79000000000
#define CONFIG_NUM_CHIRPS 64
#define CONFIG_NUM_SAMPLES 256

#define LOG_FILE "log.bin"

struct config {
    uint64_t start_freq;
    uint64_t end_freq;
    uint16_t num_chirps;
    uint16_t num_samples;
};

struct frame {
    uint64_t timestamp;
    uint32_t frame_num;
    uint8_t data[FRAME_SIZE];
};

static int spi_fd = -1;
static int gpio_fd = -1;
static int log_fd = -1;

static void cleanup(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        ioctl(gpio_fd, GPIO_UNEXPORT, GPIO_TRIGGER);
        ioctl(gpio_fd, GPIO_UNEXPORT, GPIO_DATA_READY);
        close(gpio_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

static void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int setup_spi(void)
{
    int ret;

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_DELAY_USEC, &SPI_DELAY);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI delay: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int setup_gpio(void)
{
    int ret;

    gpio_fd = open("/dev/gpiomem", O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO device: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(gpio_fd, GPIO_EXPORT, GPIO_TRIGGER);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO trigger: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(gpio_fd, GPIO_EXPORT, GPIO_DATA_READY);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO data ready: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(gpio_fd, GPIO_SET_DIR_OUT, GPIO_TRIGGER);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO trigger direction: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(gpio_fd, GPIO_SET_DIR_IN, GPIO_DATA_READY);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO data ready direction: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int setup_log(void)
{
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int write_config(struct config *config)
{
    int ret;

    ret = write(log_fd, &MAGIC_NUMBER, sizeof(MAGIC_NUMBER));
    if (ret < 0) {
        fprintf(stderr, "Failed to write magic number: %s\n", strerror(errno));
        return -1;
    }

    ret = write(log_fd, &config->start_freq, sizeof(config->start_freq));
    if (ret < 0) {
        fprintf(stderr, "Failed to write start frequency: %s\n", strerror(errno));
        return -1;
    }

    ret = write(log_fd, &config->end_freq, sizeof(config->end_freq));
    if (ret < 0) {
        fprintf(stderr, "Failed to write end frequency: %s\n", strerror(errno));
        return -1;
    }

    ret = write(log_fd, &config->num_chirps, sizeof(config->num_chirps));
    if (ret < 0) {
        fprintf(stderr, "Failed to write number of chirps: %s\n", strerror(errno));
        return -1;
    }

    ret = write(log_fd, &config->num_samples, sizeof(config->num_samples));
    if (ret < 0) {
        fprintf(stderr, "Failed to write number of samples: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int write_frame(struct frame *frame)
{
    int ret;

    ret = write(log_fd, &frame->timestamp, sizeof(frame->timestamp));
    if (ret < 0) {
        fprintf(stderr, "Failed to write frame timestamp: %s\n", strerror(errno));
        return -1;
    }

    ret = write(log_fd, &frame->frame_num, sizeof(frame->frame_num));
    if (ret < 0) {
        fprintf(stderr, "Failed to write frame number: %s\n", strerror(errno));
        return -1;
    }

    ret = write(log_fd, frame->data, FRAME_SIZE);
    if (ret < 0) {
        fprintf(stderr, "Failed to write frame data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int ret;
    struct config config = {
        .start_freq = CONFIG_START_FREQ,
        .end_freq = CONFIG_END_FREQ,
        .num_chirps = CONFIG_NUM_CHIRPS,
        .num_samples = CONFIG_NUM_SAMPLES,
    };
    struct frame frame;
    struct timespec ts;
    uint8_t tx_buf[FRAME_SIZE];
    uint8_t rx_buf[FRAME_SIZE];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = setup_spi();
    if (ret < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        goto error;
    }

    ret = setup_gpio();
    if (ret < 0) {
        fprintf(stderr, "Failed to setup GPIO\n");
        goto error;
    }

    ret = setup_log();
    if (ret < 0) {
        fprintf(stderr, "Failed to setup log\n");
        goto error;
    }

    ret = write_config(&config);
    if (ret < 0) {
        fprintf(stderr, "Failed to write config\n");
        goto error;
    }

    memset(tx_buf, 0, FRAME_SIZE);
    memset(rx_buf, 0, FRAME_SIZE);

    while (1) {
        ret = clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
            goto error;
        }

        frame.timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

        ret = ioctl(gpio_fd, GPIO_SET_VALUE, GPIO_TRIGGER);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO trigger value: %s\n", strerror(errno));
            goto error;
        }

        ret = ioctl(gpio_fd, GPIO_GET_VALUE, GPIO_DATA_READY);
        if (ret < 0) {
            fprintf(stderr, "Failed to get GPIO data ready value: %s\n", strerror(errno));
            goto error;
        }

        while (ret == 0) {
            ret = ioctl(gpio_fd, GPIO_GET_VALUE, GPIO_DATA_READY);
            if (ret < 0) {
                fprintf(stderr, "Failed to get GPIO data ready value: %s\n", strerror(errno));
                goto error;
            }
        }

        ret = read(spi_fd, rx_buf, FRAME_SIZE);
        if (ret < 0) {
            fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
            goto error;
        }

        ret = write(spi_fd, tx_buf, FRAME_SIZE);
        if (ret < 0) {
            fprintf(stderr, "Failed to write SPI data: %s\n", strerror(errno));
            goto error;
        }

        frame.frame_num++;
        memcpy(frame.data, rx_buf, FRAME_SIZE);

        ret = write_frame(&frame);
        if (ret < 0) {
            fprintf(stderr, "Failed to write frame\n");
            goto error;
        }

        ret = clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
            goto error;
        }

        while (ts.tv_nsec < frame.timestamp + FRAME_PERIOD) {
            ret = clock_gettime(CLOCK_MONOTONIC, &ts);
            if (ret < 0) {
                fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
                goto error;
            }
        }
    }

error:
    cleanup();
    return EXIT_FAILURE;
}

