            fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
            goto error;
        }

        ret = write(spi_fd, tx_buf, FRAME_SIZE);
        if (ret < 0) {
            fprintf(stderr, "Failed to write SPI data: %s\n", strerror(errno));
            goto error;
        }

