        perror("clock_gettime");
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_wait_timeout(&event, &ts, 1000000000) < 0) {
        perror("gpiod_line_event_wait_timeout");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
