#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

#define POLL_INTERVAL 50000

static volatile int running = 1;

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

int main(void)
{
    int left, center, right;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(LEFT_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set mode for pin %d: %s\n", LEFT_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(CENTER_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set mode for pin %d: %s\n", CENTER_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RIGHT_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set mode for pin %d: %s\n", RIGHT_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        left = gpioRead(LEFT_PIN);
        center = gpioRead(CENTER_PIN);
        right = gpioRead(RIGHT_PIN);

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

        usleep(POLL_INTERVAL);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}
