    ret = gpiod_chip_release_lines(chip, lines, ARRAY_SIZE(lines));
    if (ret < 0) {
        fprintf(stderr, "Failed to release lines: %s\n", strerror(errno));
        goto err_close_chip;
    }

    /* Close the chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

err_release_lines:
    gpiod_chip_release_lines(chip, lines, ARRAY_SIZE(lines));
err_close_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
