#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

static struct gpiod_chip *chip;
static struct gpiod_line *lines[8];
static int running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

int main(void)
{
    int i, ret;
    struct timespec ts;
    struct gpiod_line_bulk_config bulk_config;
    struct gpiod_line_event event;
    char buf[100];

    /* Open the chip */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request the lines */
    bulk_config.lines_max = ARRAY_SIZE(lines);
    bulk_config.lines = lines;
    bulk_config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    bulk_config.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;
    bulk_config.consumer = "touch-sensor";
    ret = gpiod_chip_get_lines_bulk_config(chip, 2, 9, &bulk_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        goto err_close_chip;
    }

    /* Set up the signal handler */
    signal(SIGINT, sigint_handler);

    /* Main loop */
    while (running) {
        /* Wait for an event */
        ret = gpiod_line_event_wait(lines[0], &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            goto err_release_lines;
        }

        /* Get the current time */
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(buf, sizeof(buf), "%F %T", localtime(&ts.tv_sec));

        /* Print the event */
        printf("%s.%03ld: ", buf, ts.tv_nsec / 1000000);
        for (i = 0; i < ARRAY_SIZE(lines); i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to get line value: %s\n", strerror(errno));
                goto err_release_lines;
            }
            printf("%d", ret);
        }
        printf("\n");
    }

    /* Release the lines */
    ret = gpiod_chip_release_lines(chip, lines, ARRAY_SIZE(lines));
    if (ret < 0) {
        fprintf(stderr, "Failed to release lines: %s\n", strerror(errno));
        goto err_close_chip;
    }

    /* Close the chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

err_release_lines:
    gpiod_chip_release_lines(chip, lines, ARRAY_SIZE(lines));
err_close_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}
