#define LED_GPIO 18
#define TOUCH_GPIO 17

static struct gpiod_chip *chip;
static struct gpiod_line *led_line, *touch_line;
static struct gpiod_line_event event;

static void cleanup(void)
{
    gpiod_line_release(led_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);
}

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

static int setup(void)
{
    int ret;

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        ret = -1;
        goto err_chip;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        goto err_led;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line\n");
        ret = -1;
        goto err_led_req;
    }

    ret = gpiod_line_request_rising_edge_events(touch_line, "touch", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request touch line\n");
        goto err_touch;
    }

    return 0;

