#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <signal.h>
#include <pthread.h>
#include <stdbool.h>

#define BCM2708_PERI_BASE        0x3F000000
#define GPIO_BASE                (BCM2708_PERI_BASE + 0x200000) /* GPIO controller */

#define PAGE_SIZE (4*1024)
#define BLOCK_SIZE (4*1024)

int  mem_fd;
void *gpio_map;

// I/O access
volatile unsigned *gpio;

// GPIO setup macros. Always use INP_GPIO(x) before using OUT_GPIO(x) or SET_GPIO_ALT(x,y)
#define INP_GPIO(g) *(gpio+((g)/10)) &= ~(7<<(((g)%10)*3))
#define OUT_GPIO(g) *(gpio+((g)/10)) |=  (1<<(((g)%10)*3))
#define SET_GPIO_ALT(g,a) *(gpio+(((g)/10))) |= (((a)<=3?(a)+4:(a)==4?3:2)<<(((g)%10)*3))

#define GPIO_SET *(gpio+7)  // sets   bits which are 1 ignores bits which are 0
#define GPIO_CLR *(gpio+10) // clears bits which are 1 ignores bits which are 0

#define GET_GPIO(g) (*(gpio+13)&(1<<g)) // 0 if LOW, (1<<g) if HIGH

#define GPIO_PULL *(gpio+37) // Pull up/pull down
#define GPIO_PULLCLK0 *(gpio+38) // Pull up/pull down clock

#define SENSOR1 17
#define SENSOR2 18

#define DEBOUNCE_TIME 5000

#define LOG_FILE "shaft_log.txt"

#define MAX_BUF 64

#define TRUE 1
#define FALSE 0

#define ERROR_EXIT(str) {perror(str); exit(EXIT_FAILURE);}

// Global variables
int keepRunning = TRUE;

// Function prototypes
void setup_io();
void *sensor_thread(void *arg);
void *rpm_thread(void *arg);
void sig_handler(int signo);

int main(int argc, char **argv)
{
    // Set up a signal handler that will exit the program
    // when Ctrl+C is pressed
    signal(SIGINT, sig_handler);

    // Set up gpi pointer for direct register access
    setup_io();

    // Set up the GPIO pins
    INP_GPIO(SENSOR1);
    INP_GPIO(SENSOR2);

    // Set up the pull up/pull down resistors
    GPIO_PULL = 0;
    GPIO_PULLCLK0 = (1 << SENSOR1) | (1 << SENSOR2);
    usleep(10);
    GPIO_PULL = 0;
    GPIO_PULLCLK0 = 0;

    // Create the threads
    pthread_t sensor_thread_id;
    pthread_t rpm_thread_id;

    pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL);
    pthread_create(&rpm_thread_id, NULL, rpm_thread, NULL);

    // Wait for the threads to finish
    pthread_join(sensor_thread_id, NULL);
    pthread_join(rpm_thread_id, NULL);

    // Close the log file
    fclose(stdout);

    // Reset GPIO settings
    GPIO_PULL = 0;
    GPIO_PULLCLK0 = 0;
    INP_GPIO(SENSOR1);
    INP_GPIO(SENSOR2);

    // Reset GPIO setup
    munmap(gpio_map, BLOCK_SIZE);
    close(mem_fd);

    return 0;
}

void setup_io()
{
    /* open /dev/mem */
    if ((mem_fd = open("/dev/mem", O_RDWR|O_SYNC) ) < 0) {
        ERROR_EXIT("can't open /dev/mem");
    }

    /* mmap GPIO */
    gpio_map = mmap(
        NULL,             //Any adddress in our space will do
        BLOCK_SIZE,       //Map length
        PROT_READ|PROT_WRITE,// Enable reading & writting to mapped memory
        MAP_SHARED,       //Shared with other processes
        mem_fd,           //File to map
        GPIO_BASE         //Offset to GPIO peripheral
    );

    close(mem_fd); //No need to keep mem_fd open after mmap

    if (gpio_map == MAP_FAILED) {
        ERROR_EXIT("mmap error");
    }

    // Always use volatile pointer!
    gpio = (volatile unsigned *)gpio_map;
}

void *sensor_thread(void *arg)
{
    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        ERROR_EXIT("fopen");
