    bool sensor2_debounce_state = FALSE;

    // Set up the debounce timers
    struct timeval sensor1_debounce_timer_start;
    struct timeval sensor2_debounce_timer_start;
    gettimeofday(&sensor1_debounce_timer_start, NULL);
    gettimeofday(&sensor2_debounce_timer_start, NULL);

    // Set up the debounce states
