#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x55
#define I2C_REG_HR 0x00
#define I2C_REG_SPO2 0x01

#define LOG_FILE "biometric_log.txt"

int i2c_fd;
FILE *log_file;

void sigint_handler(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main(void) {
    int ret;
    char buf[100];
    time_t now;
    struct tm *tm_info;
    char time_str[20];
    unsigned char hr, spo2;

    signal(SIGINT, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        ret = read(i2c_fd, &hr, 1);
        if (ret != 1) {
            fprintf(stderr, "Error reading heart rate: %s\n", strerror(errno));
            break;
        }

        ret = read(i2c_fd, &spo2, 1);
        if (ret != 1) {
            fprintf(stderr, "Error reading SpO2: %s\n", strerror(errno));
            break;
        }

        now = time(NULL);
        tm_info = localtime(&now);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        snprintf(buf, sizeof(buf), "%s, Heart Rate: %d BPM, SpO2: %d%%\n", time_str, hr, spo2);
        fputs(buf, log_file);
        fflush(log_file);

        sleep(1);
    }

    close(i2c_fd);
    fclose(log_file);
    return EXIT_FAILURE;
}

