#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27
#define LOG_FILE "bridge_integrity.log"
#define LOG_FILE_MODE "a"
#define LOG_FILE_FORMAT "%Y-%m-%dT%H:%M:%S"
#define LOG_FILE_FORMAT_SIZE 20
#define ALARM_TIMEOUT_MS 2000
#define POLL_TIMEOUT_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_1_line;
static struct gpiod_line *sensor_2_line;
static struct gpiod_line *alarm_line;
static FILE *log_file;
static int alarm_active = 0;
static int alarm_timeout_ms = 0;

static void log_event(const char *event)
{
    time_t now;
    char time_str[LOG_FILE_FORMAT_SIZE];

    now = time(NULL);
    strftime(time_str, sizeof(time_str), LOG_FILE_FORMAT, localtime(&now));
    fprintf(log_file, "%s %s\n", time_str, event);
    fflush(log_file);
}

static void activate_alarm(void)
{
    if (alarm_active)
        return;

    alarm_active = 1;
    alarm_timeout_ms = ALARM_TIMEOUT_MS;
    gpiod_line_set_value(alarm_line, 1);
    log_event("alarm activated");
}

static void deactivate_alarm(void)
{
    if (!alarm_active)
        return;

    alarm_active = 0;
    gpiod_line_set_value(alarm_line, 0);
    log_event("alarm deactivated");
}

static void handle_shutdown(int signum)
{
    deactivate_alarm();
    fclose(log_file);
    gpiod_line_release(sensor_1_line);
    gpiod_line_release(sensor_2_line);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    exit(0);
}

