#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define LED_GPIO 18
#define SENSOR_GPIO_1 4
#define SENSOR_GPIO_2 17
#define SENSOR_GPIO_3 27
#define SENSOR_GPIO_4 22

#define SENSOR_GPIO_COUNT 4

#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *sensor_lines[SENSOR_GPIO_COUNT];

static void cleanup(void)
{
    int i;

    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }

    for (i = 0; i < SENSOR_GPIO_COUNT; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
            sensor_lines[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void sig_handler(int signo)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init(void)
{
    int i;

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", strerror(errno));
        return -1;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        return -1;
    }

    for (i = 0; i < SENSOR_GPIO_COUNT; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_GPIO_1 + i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get sensor line %d: %s\n", i, strerror(errno));
            return -1;
        }

        if (gpiod_line_request_input(sensor_lines[i], "sensor") < 0) {
            fprintf(stderr, "Failed to request sensor line %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int poll_sensors(void)
{
    int i;
    int value;

    for (i = 0; i < SENSOR_GPIO_COUNT; i++) {
        value = gpiod_line_get_value(sensor_lines[i]);
        if (value < 0) {
            fprintf(stderr, "Failed to read sensor line %d: %s\n", i, strerror(errno));
            return -1;
        }

        if (value == 0) {
            return 1;
        }
    }

    return 0;
}

static void set_led(int value)
{
    if (gpiod_line_set_value(led_line, value) < 0) {
        fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct timespec ts;
    int value;

    if (init() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        value = poll_sensors();
        if (value < 0) {
            break;
        }

        set_led(value);

        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&ts, NULL);
    }

    cleanup();
    return EXIT_FAILURE;
}

