#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define ARRAY_SIZE(x) (sizeof(x) / sizeof((x)[0]))

static struct gpiod_chip *chip;
static struct gpiod_line *lines[8];
static int line_values[8];

static void cleanup(void)
{
    for (int i = 0; i < ARRAY_SIZE(lines); i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    struct timespec ts;
    char timestamp[26];
    int line_value;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < ARRAY_SIZE(lines); i++) {
        lines[i] = gpiod_chip_get_line(chip, 5 + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", 5 + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(lines[i], "touch-sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d: %s\n", 5 + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        for (int i = 0; i < ARRAY_SIZE(lines); i++) {
            ret = gpiod_line_get_value(lines[i], &line_value);
            if (ret < 0) {
                fprintf(stderr, "Failed to read GPIO line %d: %s\n", 5 + i, strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }

            if (line_value != line_values[i]) {
                clock_gettime(CLOCK_REALTIME, &ts);
                strftime(timestamp, sizeof(timestamp), "%FT%T%z", gmtime(&ts.tv_sec));
                printf("%s: Sensor %d (BCM %d) %s\n", timestamp, i, 5 + i, line_value ? "touched" : "released");
                line_values[i] = line_value;
            }
        }

        usleep(50000);
    }

