#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define BUZZER_DURATION 2
#define POLL_INTERVAL 500
#define LOG_FILE "alert_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;

static void log_entry(const char *message)
{
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char time_string[20];
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", local_time);
    fprintf(log_file, "%s: %s\n", time_string, message);
    fflush(log_file);
}

static void handle_flame_detected(void)
{
    log_entry("FLAME DETECTED");
    gpiod_line_set_value(buzzer_line, 1);
    sleep(BUZZER_DURATION);
    gpiod_line_set_value(buzzer_line, 0);
}

static void handle_signal(int signal)
{
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main(void)
{
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting flame sensor line: %s\n", strerror(errno));
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    log_entry("System started");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            fprintf(stderr, "Error getting flame sensor value: %s\n", strerror(errno));
            return 1;
        }
        if (value == 0) {
            handle_flame_detected();
        }
        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

