#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1 17
#define SENSOR_2 18
#define SENSOR_3 27
#define SENSOR_4 22
#define POLL_INTERVAL 100
#define CSV_FILE "tracking_log.csv"

FILE *csv_file;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signo);
        fclose(csv_file);
        gpioTerminate();
        exit(0);
    }
}

int main(int argc, char *argv[])
{
    int sensor_values[4];
    char csv_line[100];
    time_t current_time;
    struct tm *time_info;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetMode(SENSOR_3, PI_INPUT);
    gpioSetMode(SENSOR_4, PI_INPUT);

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        sensor_values[0] = gpioRead(SENSOR_1);
        sensor_values[1] = gpioRead(SENSOR_2);
        sensor_values[2] = gpioRead(SENSOR_3);
        sensor_values[3] = gpioRead(SENSOR_4);

        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(csv_line, sizeof(csv_line), "%Y-%m-%d %H:%M:%S", time_info);
        fprintf(csv_file, "%s,%d,%d,%d,%d\n", csv_line, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3]);
        fflush(csv_file);

        gpioDelay(POLL_INTERVAL * 1000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define LOG_FILE "/var/log/tilt_events.log"
#define LOG_FILE_MODE (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)
#define LOG_FILE_BUF_SIZE 1024
#define LOG_FILE_LINE_SIZE 128
#define LOG_FILE_LINE_FORMAT "%04d-%02d-%02d %02d:%02d:%02d, Sensor %d tilted\n"

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 18
#define GPIO_LINE_REQUEST_FLAGS (GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_BIAS_PULL_UP)
#define GPIO_LINE_REQUEST_EVENT_FLAGS (GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE)
#define GPIO_LINE_REQUEST_EVENT_DEBOUNCE_NS 50000000

#define POLL_TIMEOUT_NS 100000000

#define EXIT_SUCCESS 0
#define EXIT_FAILURE 1

static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line_1;
static struct gpiod_line *gpio_line_2;
static FILE *log_file;

static void sig_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        if (gpio_line_1) {
            gpiod_line_release(gpio_line_1);
            gpio_line_1 = NULL;
        }
        if (gpio_line_2) {
            gpiod_line_release(gpio_line_2);
            gpio_line_2 = NULL;
        }
        if (gpio_chip) {
            gpiod_chip_close(gpio_chip);
            gpio_chip = NULL;
        }
        if (log_file) {
            fclose(log_file);
            log_file = NULL;
        }
        exit(EXIT_SUCCESS);
    }
}

static int init_gpio(void)
{
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line_1 = gpiod_chip_get_line(gpio_chip, GPIO_LINE_1);
    if (!gpio_line_1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_1, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_input_flags(gpio_line_1, "tilt_sensor_1", GPIO_LINE_REQUEST_FLAGS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_1, strerror(errno));
        return -1;
    }

    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_LINE_2);
    if (!gpio_line_2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_2, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_input_flags(gpio_line_2, "tilt_sensor_2", GPIO_LINE_REQUEST_FLAGS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE_2, strerror(errno));
        return -1;
    }

    return 0;
}

static int init_log_file(void)
{
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    if (chmod(LOG_FILE, LOG_FILE_MODE) < 0) {
        fprintf(stderr, "Failed to set log file permissions: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_event(int sensor)
{
    int ret;
    char buf[LOG_FILE_BUF_SIZE];
    time_t t;
    struct tm *tm;

    t = time(NULL);
    tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Failed to get local time: %s\n", strerror(errno));
        return -1;
    }

    ret = snprintf(buf, sizeof(buf), LOG_FILE_LINE_FORMAT, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, sensor);
    if (ret < 0 || ret >= sizeof(buf)) {
        fprintf(stderr, "Failed to format log line\n");
        return -1;
    }

    ret = fwrite(buf, 1, strlen(buf), log_file);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);

    return 0;
}

int main(void)
{
    int ret;
    struct gpiod_line_event event;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = init_gpio();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    ret = init_log_file();
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_event_flags(gpio_line_1, "tilt_sensor_1", GPIO_LINE_REQUEST_EVENT_FLAGS, GPIO_LINE_REQUEST_EVENT_DEBOUNCE_NS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d event: %s\n", GPIO_LINE_1, strerror(errno));
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_event_flags(gpio_line_2, "tilt_sensor_2", GPIO_LINE_REQUEST_EVENT_FLAGS, GPIO_LINE_REQUEST_EVENT_DEBOUNCE_NS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d event: %s\n", GPIO_LINE_2, strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_line_event_wait(gpio_line_1, &event, POLL_TIMEOUT_NS);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for GPIO line %d event: %s\n", GPIO_LINE_1, strerror(errno));
            return EXIT_FAILURE;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            ret = log_event(1);
            if (ret < 0) {
                return EXIT_FAILURE;
            }
        }

        ret = gpiod_line_event_wait(gpio_line_2, &event, POLL_TIMEOUT_NS);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for GPIO line %d event: %s\n", GPIO_LINE_2, strerror(errno));
            return EXIT_FAILURE;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            ret = log_event(2);
            if (ret < 0) {
                return EXIT_FAILURE;
            }
        }
    }

    return EXIT_SUCCESS;
}

