#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_TIME_MS 100

volatile sig_atomic_t stop = 0;

void sigint_handler(int sig)
{
    stop = 1;
}

int main(void)
{
    int rc;
    struct timespec ts;
    struct timespec ts_led_on;
    struct timespec ts_led_off;
    struct timespec ts_led_diff;
    struct timespec ts_diff;
    gpioPulse_t pulse[2];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    rc = gpioSetMode(MIC_PIN, PI_INPUT);
    if (rc != 0)
    {
        fprintf(stderr, "gpioSetMode failed for MIC_PIN\n");
        goto cleanup;
    }

    rc = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (rc != 0)
    {
        fprintf(stderr, "gpioSetMode failed for LED_PIN\n");
        goto cleanup;
    }

    rc = gpioSetPullUpDown(MIC_PIN, PI_PUD_OFF);
    if (rc != 0)
    {
        fprintf(stderr, "gpioSetPullUpDown failed for MIC_PIN\n");
        goto cleanup;
    }

    rc = gpioSetPullUpDown(LED_PIN, PI_PUD_OFF);
    if (rc != 0)
    {
        fprintf(stderr, "gpioSetPullUpDown failed for LED_PIN\n");
        goto cleanup;
    }

    rc = gpioSetAlertFunc(MIC_PIN, NULL);
    if (rc != 0)
    {
        fprintf(stderr, "gpioSetAlertFunc failed for MIC_PIN\n");
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);

    while (!stop)
    {
        rc = clock_gettime(CLOCK_MONOTONIC, &ts);
        if (rc != 0)
        {
            fprintf(stderr, "clock_gettime failed\n");
            goto cleanup;
        }

        rc = gpioRead_Bits_0_31(&rc);
        if (rc != 0)
        {
            fprintf(stderr, "gpioRead_Bits_0_31 failed\n");
            goto cleanup;
        }

        if (rc & (1 << MIC_PIN))
        {
            printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            pulse[0].gpioOn = 1 << LED_PIN;
            pulse[0].gpioOff = 0;
            pulse[0].usDelay = 0;

            pulse[1].gpioOn = 0;
            pulse[1].gpioOff = 1 << LED_PIN;
            pulse[1].usDelay = LED_ON_TIME_MS * 1000;

            rc = gpioWaveAddGeneric(2, pulse);
            if (rc < 0)
            {
                fprintf(stderr, "gpioWaveAddGeneric failed\n");
                goto cleanup;
            }

            rc = gpioWaveTxSend(rc, PI_WAVE_MODE_ONE_SHOT);
            if (rc != 0)
            {
                fprintf(stderr, "gpioWaveTxSend failed\n");
                goto cleanup;
            }

            rc = gpioWaveTxBusy();
            if (rc != 0)
            {
                fprintf(stderr, "gpioWaveTxBusy failed\n");
                goto cleanup;
            }

            while (rc != 0)
            {
                rc = gpioWaveTxBusy();
                if (rc != 0)
                {
                    fprintf(stderr, "gpioWaveTxBusy failed\n");
                    goto cleanup;
                }
            }
        }

        rc = clock_gettime(CLOCK_MONOTONIC, &ts_led_off);
        if (rc != 0)
        {
            fprintf(stderr, "clock_gettime failed\n");
            goto cleanup;
        }

        ts_led_diff.tv_sec = ts_led_off.tv_sec - ts_led_on.tv_sec;
        ts_led_diff.tv_nsec = ts_led_off.tv_nsec - ts_led_on.tv_nsec;

        if (ts_led_diff.tv_nsec < 0)
        {
            ts_led_diff.tv_sec--;
            ts_led_diff.tv_nsec += 1000000000;
        }

        ts_diff.tv_sec = ts.tv_sec - ts_led_off.tv_sec;
        ts_diff.tv_nsec = ts.tv_nsec - ts_led_off.tv_nsec;

        if (ts_diff.tv_nsec < 0)
        {
            ts_diff.tv_sec--;
            ts_diff.tv_nsec += 1000000000;
        }

        if (ts_led_diff.tv_sec > 0 || ts_led_diff.tv_nsec > LED_ON_TIME_MS * 1000000)
        {
            rc = gpioWrite(LED_PIN, 0);
            if (rc != 0)
            {
                fprintf(stderr, "gpioWrite failed for LED_PIN\n");
                goto cleanup;
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

cleanup:
    gpioTerminate();
    return 0;
}
