// gcc -o touch_poll touch_poll.c -lrt
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

static struct gpiod_chip *chip;
static struct gpiod_line *lines[8];

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Exiting...\n");
        gpiod_line_release_many(lines, ARRAY_SIZE(lines));
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main(void)
{
    int i;
    int ret;
    struct timespec ts;
    struct gpiod_line_request_config lrc;
    struct gpiod_line_bulk_read bulk_read;
    struct gpiod_line_event event;
    uint8_t values[8];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        return -1;
    }

    lrc.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    lrc.consumer = "touch_poll";
    lrc.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;

    lines[0] = gpiod_chip_get_line(chip, 5);
    lines[1] = gpiod_chip_get_line(chip, 6);
    lines[2] = gpiod_chip_get_line(chip, 13);
    lines[3] = gpiod_chip_get_line(chip, 19);
    lines[4] = gpiod_chip_get_line(chip, 26);
    lines[5] = gpiod_chip_get_line(chip, 12);
    lines[6] = gpiod_chip_get_line(chip, 16);
    lines[7] = gpiod_chip_get_line(chip, 20);

    ret = gpiod_line_request_bulk_raw(lines, ARRAY_SIZE(lines), &lrc);
    if (ret < 0) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    bulk_read.lines = lines;
    bulk_read.num_lines = ARRAY_SIZE(lines);
    bulk_read.values = values;

    while (1) {
        ret = gpiod_line_bulk_read_events(&bulk_read, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read lines\n");
            gpiod_line_release_many(lines, ARRAY_SIZE(lines));
            gpiod_chip_close(chip);
            return -1;
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%lds.%03ldms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               ts.tv_sec, ts.tv_nsec / 1000000,
               values[0], values[1], values[2], values[3], values[4], values[5], values[6], values[7]);

        for (i = 0; i < ARRAY_SIZE(lines); i++) {
            if (values[i] != event.line->offset) {
                fprintf(stderr, "Failed to read line %d\n", i);
                gpiod_line_release_many(lines, ARRAY_SIZE(lines));
                gpiod_chip_close(chip);
                return -1;
            }
        }

        usleep(200000);
    }

    return 0;
}

