#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define LED_GPIO 17
#define BUTTON_GPIO 18

static struct gpiod_chip *chip;
static struct gpiod_line *led_line, *button_line;
static struct gpiod_line_request led_req, button_req;

static void cleanup(void)
{
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        exit(EXIT_FAILURE);
    }

    led_req.request_type = GPIOD_LINE_REQ_DIRECTION_OUTPUT;
    led_req.flags = GPIOD_LINE_REQ_FLAG_ACTIVE_LOW;
    led_req.consumer = "blink_button";
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(led_line, &led_req, 0);
    if (ret < 0) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    button_req.request_type = GPIOD_LINE_REQ_DIRECTION_INPUT;
    button_req.flags = GPIOD_LINE_REQ_FLAG_ACTIVE_HIGH | GPIOD_LINE_REQ_FLAG_OPEN_DRAIN;
    button_req.consumer = "blink_button";
    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        perror("gpiod_chip_get_line");
