#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define I2C_REG_CTRL1 0x20
#define I2C_REG_CTRL2 0x21
#define I2C_REG_CTRL3 0x22
#define I2C_REG_CTRL4 0x23
#define I2C_REG_CTRL5 0x24
#define I2C_REG_CTRL6 0x25
#define I2C_REG_CTRL7 0x26
#define I2C_REG_STATUS 0x27
#define I2C_REG_OUT_X_L 0x28
#define I2C_REG_OUT_X_H 0x29
#define I2C_REG_OUT_Y_L 0x2A
#define I2C_REG_OUT_Y_H 0x2B
#define I2C_REG_OUT_Z_L 0x2C
#define I2C_REG_OUT_Z_H 0x2D
#define I2C_REG_FIFO_CTRL 0x2E
#define I2C_REG_FIFO_SRC 0x2F
#define I2C_REG_INT1_CFG 0x30
#define I2C_REG_INT1_SRC 0x31
#define I2C_REG_INT1_THS 0x32
#define I2C_REG_INT1_DURATION 0x33
#define I2C_REG_INT2_CFG 0x34
#define I2C_REG_INT2_SRC 0x35
#define I2C_REG_INT2_THS 0x36
#define I2C_REG_INT2_DURATION 0x37
#define I2C_REG_CLICK_CFG 0x38
#define I2C_REG_CLICK_SRC 0x39
#define I2C_REG_CLICK_THS 0x3A
#define I2C_REG_TIME_LIMIT 0x3B
#define I2C_REG_TIME_LATENCY 0x3C
#define I2C_REG_TIME_WINDOW 0x3D
#define I2C_REG_ACT_THS 0x3E
#define I2C_REG_ACT_DUR 0x3F

#define GPIO_PIN 17
#define GPIO_PULSE_WIDTH 50

#define DEFAULT_THRESHOLD 2.0

#define LOG_FILE "impact_log.txt"

int i2c_handle;
int gpio_handle;

int init_i2c(void)
{
    char i2c_dev[16];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_handle = open(i2c_dev, O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

int init_gpio(void)
{
    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %s\n", strerror(gpio_handle));
        return -1;
    }
    if (gpioSetMode(gpio_handle, GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as output: %s\n", GPIO_PIN, strerror(gpio_handle));
        return -1;
    }
    return 0;
}

int init_sensor(void)
{
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_REG_CTRL1, 0x57) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", I2C_REG_CTRL1, strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_REG_CTRL2, 0x00) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", I2C_REG_CTRL2, strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_REG_CTRL3, 0x00) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", I2C_REG_CTRL3, strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_REG_CTRL4, 0x00) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", I2C_REG_CTRL4, strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_REG_CTRL5, 0x00) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", I2C_REG_CTRL5, strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_REG_CTRL6, 0x00) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", I2C_REG_CTRL6, strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_handle, I2C_REG_CTRL7, 0x00) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", I2C_REG_CTRL7, strerror(errno));
        return -1;
    }
    return 0;
}

int read_sensor(float *x, float *y, float *z)
{
    int16_t x_raw, y_raw, z_raw;
    if (i2c_smbus_read_word_data(i2c_handle, I2C_REG_OUT_X_L) < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X: %s\n", I2C_REG_OUT_X_L, strerror(errno));
        return -1;
    }
    x_raw = i2c_smbus_read_word_data(i2c_handle, I2C_REG_OUT_X_L);
    if (i2c_smbus_read_word_data(i2c_handle, I2C_REG_OUT_Y_L) < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X: %s\n", I2C_REG_OUT_Y_L, strerror(errno));
        return -1;
    }
    y_raw = i2c_smbus_read_word_data(i2c_handle, I2C_REG_OUT_Y_L);
    if (i2c_smbus_read_word_data(i2c_handle, I2C_REG_OUT_Z_L) < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X: %s\n", I2C_REG_OUT_Z_L, strerror(errno));
        return -1;
    }
    z_raw = i2c_smbus_read_word_data(i2c_handle, I2C_REG_OUT_Z_L);
    *x = (float)x_raw / 1000.0;
    *y = (float)y_raw / 1000.0;
    *z = (float)z_raw / 1000.0;
    return 0;
}

int trigger_impact(void)
{
    if (gpioWrite(gpio_handle, GPIO_PIN, PI_HIGH) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d to HIGH: %s\n", GPIO_PIN, strerror(gpio_handle));
        return -1;
    }
    sleep(GPIO_PULSE_WIDTH / 1000);
    if (gpioWrite(gpio_handle, GPIO_PIN, PI_LOW) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d to LOW: %s\n", GPIO_PIN, strerror(gpio_handle));
        return -1;
    }
    return 0;
}

int log_data(float x, float y, float z)
{
    FILE *log_file;
    time_t now;
    struct tm *now_tm;
    char timestamp[32];
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    now = time(NULL);
    now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
    fprintf(log_file, "%s: %f %f %f\n", timestamp, x, y, z);
    fclose(log_file);
    return 0;
}

void cleanup(void)
{
    if (gpio_handle >= 0) {
        gpioTerminate();
    }
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
}

int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;
    float x, y, z, g_force;
    int i;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }
    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }
    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }
    if (init_sensor() < 0) {
        return EXIT_FAILURE;
    }
    atexit(cleanup);
    while (1) {
        if (read_sensor(&x, &y, &z) < 0) {
            return EXIT_FAILURE;
        }
        g_force = sqrt(x * x + y * y + z * z);
        if (g_force > threshold) {
            for (i = 0; i < 10; i++) {
                if (trigger_impact() < 0) {
                    return EXIT_FAILURE;
                }
                if (log_data(x, y, z) < 0) {
                    return EXIT_FAILURE;
                }
                sleep(1);
            }
        }
        sleep(1);
    }
    return EXIT_SUCCESS;
}

