#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 3
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_DELAY 0

#define ADIS16448_REG_XGYRO_OUT 0x04
#define ADIS16448_REG_YGYRO_OUT 0x06
#define ADIS16448_REG_ZGYRO_OUT 0x08
#define ADIS16448_REG_XACCL_OUT 0x0A
#define ADIS16448_REG_YACCL_OUT 0x0C
#define ADIS16448_REG_ZACCL_OUT 0x0E

#define ADIS16448_GYRO_SCALE 0.02
#define ADIS16448_ACCL_SCALE 0.00025

#define ADIS16448_READ_CMD 0x80

static int spi_fd = -1;

static void cleanup(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

static int init_spi(void)
{
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;
    uint16_t delay = SPI_DELAY;

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI speed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &delay);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI delay: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_LSB_FIRST, &delay);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI delay: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_adis16448_reg(uint8_t reg, uint16_t *val)
{
    int ret;
    uint8_t tx[2] = { ADIS16448_READ_CMD | reg, 0 };
    uint8_t rx[2] = { 0 };

    ret = write(spi_fd, tx, sizeof(tx));
    if (ret < 0) {
        fprintf(stderr, "Failed to write SPI data: %s\n", strerror(errno));
        return -1;
    }

    ret = read(spi_fd, rx, sizeof(rx));
    if (ret < 0) {
        fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
        return -1;
    }

    *val = (rx[0] << 8) | rx[1];

    return 0;
}

int main(void)
{
    int ret;
    uint16_t xgyro, ygyro, zgyro, xaccl, yaccl, zaccl;
    float xgyro_f, ygyro_f, zgyro_f, xaccl_f, yaccl_f, zaccl_f;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    ret = init_spi();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    while (1) {
        ret = read_adis16448_reg(ADIS16448_REG_XGYRO_OUT, &xgyro);
        if (ret < 0) {
            fprintf(stderr, "Failed to read XGYRO_OUT\n");
            return EXIT_FAILURE;
        }

        ret = read_adis16448_reg(ADIS16448_REG_YGYRO_OUT, &ygyro);
        if (ret < 0) {
            fprintf(stderr, "Failed to read YGYRO_OUT\n");
            return EXIT_FAILURE;
        }

        ret = read_adis16448_reg(ADIS16448_REG_ZGYRO_OUT, &zgyro);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ZGYRO_OUT\n");
            return EXIT_FAILURE;
        }

        ret = read_adis16448_reg(ADIS16448_REG_XACCL_OUT, &xaccl);
        if (ret < 0) {
            fprintf(stderr, "Failed to read XACCL_OUT\n");
            return EXIT_FAILURE;
        }

        ret = read_adis16448_reg(ADIS16448_REG_YACCL_OUT, &yaccl);
        if (ret < 0) {
            fprintf(stderr, "Failed to read YACCL_OUT\n");
            return EXIT_FAILURE;
        }

        ret = read_adis16448_reg(ADIS16448_REG_ZACCL_OUT, &zaccl);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ZACCL_OUT\n");
            return EXIT_FAILURE;
        }

        xgyro_f = xgyro * ADIS16448_GYRO_SCALE;
        ygyro_f = ygyro * ADIS16448_GYRO_SCALE;
        zgyro_f = zgyro * ADIS16448_GYRO_SCALE;
        xaccl_f = xaccl * ADIS16448_ACCL_SCALE;
        yaccl_f = yaccl * ADIS16448_ACCL_SCALE;
        zaccl_f = zaccl * ADIS16448_ACCL_SCALE;

        printf("XGYRO: %f dps, YGYRO: %f dps, ZGYRO: %f dps, XACCL: %f g, YACCL: %f g, ZACCL: %f g\n",
               xgyro_f, ygyro_f, zgyro_f, xaccl_f, yaccl_f, zaccl_f);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

