#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define I2C_REG_DEVID 0x00
#define I2C_REG_DATAX0 0x32
#define I2C_REG_DATAX1 0x33
#define I2C_REG_DATAY0 0x34
#define I2C_REG_DATAY1 0x35
#define I2C_REG_DATAZ0 0x36
#define I2C_REG_DATAZ1 0x37
#define I2C_DEVID 0xE5
#define I2C_SCALE 256
#define I2C_THRESHOLD 2500
#define I2C_POLL_MS 10
#define I2C_LED_GPIO 17
#define I2C_LED_MS 500
#define I2C_LOG_FILE "impact_log.txt"

static int i2c_fd = -1;
static int i2c_led_gpio = -1;
static FILE *i2c_log_file = NULL;

static void i2c_cleanup(void)
{
    if (i2c_log_file != NULL) {
        fclose(i2c_log_file);
        i2c_log_file = NULL;
    }
    if (i2c_led_gpio >= 0) {
        gpioWrite(i2c_led_gpio, 0);
        gpioSetMode(i2c_led_gpio, PI_INPUT);
        i2c_led_gpio = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void i2c_exit(int status)
{
    i2c_cleanup();
    exit(status);
}

static void i2c_signal_handler(int signum)
{
    i2c_exit(EXIT_SUCCESS);
}

static void i2c_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        i2c_exit(EXIT_FAILURE);
    }
    i2c_led_gpio = I2C_LED_GPIO;
    gpioSetMode(i2c_led_gpio, PI_OUTPUT);
    gpioWrite(i2c_led_gpio, 0);
    i2c_fd = open(I2C_DEV_NAME, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open failed: %s\n", strerror(errno));
        i2c_exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl failed: %s\n", strerror(errno));
        i2c_exit(EXIT_FAILURE);
    }
    if (i2c_log_file == NULL) {
        i2c_log_file = fopen(I2C_LOG_FILE, "w");
        if (i2c_log_file == NULL) {
            fprintf(stderr, "fopen failed: %s\n", strerror(errno));
            i2c_exit(EXIT_FAILURE);
        }
    }
    signal(SIGINT, i2c_signal_handler);
    signal(SIGTERM, i2c_signal_handler);
}

static int i2c_read_reg(uint8_t reg)
{
    uint8_t buf[1];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "write failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "read failed: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

static int i2c_read_reg16(uint8_t reg)
{
    uint8_t buf[2];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "write failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "read failed: %s\n", strerror(errno));
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

static int i2c_read_devid(void)
{
    return i2c_read_reg(I2C_REG_DEVID);
}

static int i2c_read_datax(void)
{
    return i2c_read_reg16(I2C_REG_DATAX0);
}

static int i2c_read_datay(void)
{
    return i2c_read_reg16(I2C_REG_DATAY0);
}

static int i2c_read_dataz(void)
{
    return i2c_read_reg16(I2C_REG_DATAZ0);
}

static int i2c_read_data(int *x, int *y, int *z)
{
    *x = i2c_read_datax();
    if (*x < 0) {
        return -1;
    }
    *y = i2c_read_datay();
    if (*y < 0) {
        return -1;
    }
    *z = i2c_read_dataz();
    if (*z < 0) {
        return -1;
    }
    return 0;
}

