#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 3
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_DELAY 0

#define WHO_AM_I 0x5F
#define OUT_X_MSB 0x04
#define OUT_X_LSB 0x05
#define OUT_Y_MSB 0x06
#define OUT_Y_LSB 0x07
#define OUT_Z_MSB 0x08
#define OUT_Z_LSB 0x09

#define LOG_FILE "gyro_log.csv"

static int spi_fd = -1;
static FILE *log_fp = NULL;

static void cleanup(void)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static void sigint_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_spi(void)
{
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED;
    uint16_t delay = SPI_DELAY;

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI mode: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI bits per word: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI speed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &delay);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI delay: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_LSB_FIRST, &delay);
    if (ret < 0) {
        fprintf(stderr, "Failed to get SPI delay: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_register(uint8_t reg, uint16_t *value)
{
    int ret;
    uint8_t tx[2] = { reg | 0x80, 0x00 };
    uint8_t rx[2] = { 0x00, 0x00 };

    ret = write(spi_fd, tx, sizeof(tx));
    if (ret < 0) {
        fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = read(spi_fd, rx, sizeof(rx));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(errno));
        return -1;
    }

    *value = (rx[0] << 8) | rx[1];

    return 0;
}

static int write_register(uint8_t reg, uint16_t value)
{
    int ret;
    uint8_t tx[2] = { reg, value >> 8, value & 0xFF };

    ret = write(spi_fd, tx, sizeof(tx));
    if (ret < 0) {
        fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int init_gyro(void)
{
    uint16_t value;

    if (read_register(WHO_AM_I, &value) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (value != 0x42) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", value);
        return -1;
    }

    return 0;
}

static int sample_gyro(void)
{
    int ret;
    uint16_t value;
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
        return -1;
    }

    ret = read_register(OUT_X_MSB, &value);
    if (ret < 0) {
        fprintf(stderr, "Failed to read OUT_X_MSB register\n");
        return -1;
    }

    fprintf(log_fp, "%ld.%09ld,%d\n", ts.tv_sec, ts.tv_nsec, value);

    return 0;
}

int main(void)
{
    int ret;

    if (atexit(cleanup) < 0) {
        fprintf(stderr, "Failed to register cleanup function: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    if (init_gyro() < 0) {
        fprintf(stderr, "Failed to initialize gyro\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "w");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fprintf(log_fp, "timestamp,value\n");

    while (1) {
        if (sample_gyro() < 0) {
            fprintf(stderr, "Failed to sample gyro\n");
            return EXIT_FAILURE;
        }

        ret = fflush(log_fp);
        if (ret < 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        usleep(10000);
    }

    return EXIT_SUCCESS;
}

