#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define I2C_WHO_AM_I 0x0F
#define I2C_WHO_AM_I_VAL 0xD3
#define I2C_CTRL_REG1 0x20
#define I2C_CTRL_REG1_VAL 0x0F
#define I2C_CTRL_REG4 0x23
#define I2C_CTRL_REG4_VAL 0x80
#define I2C_OUT_X_L 0x28
#define I2C_OUT_X_H 0x29
#define I2C_OUT_Y_L 0x2A
#define I2C_OUT_Y_H 0x2B
#define I2C_OUT_Z_L 0x2C
#define I2C_OUT_Z_H 0x2D
#define I2C_TIMEOUT 1000
#define I2C_RETRIES 3
#define I2C_SENSITIVITY 114.285
#define CSV_FILE "gyro_log.csv"
#define CSV_HEADER "Timestamp,X,Y,Z"

static int i2c_fd = -1;
static FILE *csv_fp = NULL;
static bool running = true;

static void cleanup(void)
{
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (csv_fp) {
        fclose(csv_fp);
    }
}

static void sigint_handler(int signum)
{
    running = false;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    int ret;

    ret = i2cWriteByte(i2c_fd, reg);
    if (ret < 0) {
        return ret;
    }

    ret = i2cReadByte(i2c_fd);
    if (ret < 0) {
        return ret;
    }

    *val = ret;

    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    int ret;

    ret = i2cWriteByteData(i2c_fd, reg, val);
    if (ret < 0) {
        return ret;
    }

    return 0;
}

static int i2c_init(void)
{
    int ret;
    uint8_t val;

    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_read_reg(I2C_WHO_AM_I, &val);
    if (ret < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (val != I2C_WHO_AM_I_VAL) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", val);
        return -1;
    }

    ret = i2c_write_reg(I2C_CTRL_REG1, I2C_CTRL_REG1_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 register: %s\n", strerror(errno));
        return -1;
    }

    ret = i2c_write_reg(I2C_CTRL_REG4, I2C_CTRL_REG4_VAL);
    if (ret < 0) {
        fprintf(stderr, "Failed to write CTRL_REG4 register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int i2c_read_data(int16_t *x, int16_t *y, int16_t *z)
{
    int ret;
    uint8_t buf[6];

    ret = i2cReadI2CBlockData(i2c_fd, I2C_OUT_X_L | 0x80, 6, buf);
    if (ret < 0) {
        return ret;
    }

    *x = (buf[1] << 8) | buf[0];
    *y = (buf[3] << 8) | buf[2];
    *z = (buf[5] << 8) | buf[4];

    return 0;
}

static int csv_init(void)
{
    csv_fp = fopen(CSV_FILE, "w");
    if (!csv_fp) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(csv_fp, "%s\n", CSV_HEADER);

    return 0;
}

static int csv_write_record(struct timespec *ts, int16_t x, int16_t y, int16_t z)
{
    fprintf(csv_fp, "%ld.%09ld,%d,%d,%d\n", ts->tv_sec, ts->tv_nsec, x, y, z);

    return 0;
}

int main(void)
{
    int ret;
    int16_t x, y, z;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    atexit(cleanup);
    signal(SIGINT, sigint_handler);

    ret = i2c_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

