#define FLAME_SENSOR_PIN 17
#define FLAME_LOG_FILE "flame_events.log"

static volatile sig_atomic_t exit_flag = 0;

static void sigint_handler(int signum)
{
    exit_flag = 1;
}

int main(void)
{
    FILE *log_file = NULL;
    int sensor_value = 0;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    log_file = fopen(FLAME_LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!exit_flag)
    {
        sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0)
        {
            fprintf(stderr, "Failed to read sensor value\n");
            break;
