static void transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
	int ret;

	struct spi_ioc_transfer tr = {
		.tx_buf = (unsigned long)tx,
		.rx_buf = (unsigned long)rx,
		.len = len,
		.delay_usecs = delay,
		.speed_hz = speed,
		.bits_per_word = bits,
	};

	ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
	if (ret < 1)
		pabort("can't send spi message");
}

static void write_reg(uint8_t reg, uint8_t val)
{
	uint8_t tx[2];

	tx[0] = reg | 0x80;
	tx[1] = val;

	transfer(fd, tx, NULL, 2);
}

static uint8_t read_reg(uint8_t reg)
{
	uint8_t tx[2];
	uint8_t rx[2];

	tx[0] = reg | 0x80 | 0x40;
	tx[1] = 0;

	transfer(fd, tx, rx, 2);

	return rx[1];
}

static void read_regs(uint8_t reg, uint8_t *rx, size_t len)
{
	uint8_t tx[len + 1];

	tx[0] = reg | 0x80 | 0x40;
	memset(tx + 1, 0, len);

	transfer(fd, tx, rx, len + 1);
}

static void reset(void)
{
	write_reg(0x1f, 0x52);
	usleep(1000);
}

static void init(void)
{
	uint8_t val;

	write_reg(0x2d, 0x00);
	usleep(1000);

	do {
		val = read_reg(0x0b);
	} while (!(val & 0x01));

	write_reg(0x2d, 0x02);
}

