{
    int ret;
    uint8_t tx_buf[SPI_WRITE_LEN] = {cmd, 0x00};
    uint8_t rx_buf[SPI_READ_LEN] = {0};

    ret = write(spi_fd, tx_buf, SPI_WRITE_LEN);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(errno));
        return -1;
    }

    ret = read(spi_fd, rx_buf, SPI_READ_LEN);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(errno));
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

