    if (csv_file == NULL) {
        fprintf(stderr, "CSV file not initialized\n");
        return -1;
    }

    fprintf(csv_file, "%ld.%06ld,%d,%d,%d,%d,%d,%d\n", timestamp->tv_sec, timestamp->tv_usec, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);

