    if (ret < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    ret = csv_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize CSV file\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (true) {
        gettimeofday(&timestamp, NULL);

        ret = spi_read(SPI_READ_X_GYRO_CMD | SPI_READ_CMD, &x_gyro);
        if (ret < 0) {
            fprintf(stderr, "Failed to read X gyro\n");
            continue;
        }

        ret = spi_read(SPI_READ_Y_GYRO_CMD | SPI_READ_CMD, &y_gyro);
        if (ret < 0) {
            fprintf(stderr, "Failed to read Y gyro\n");
            continue;
        }

        ret = spi_read(SPI_READ_Z_GYRO_CMD | SPI_READ_CMD, &z_gyro);
        if (ret < 0) {
            fprintf(stderr, "Failed to read Z gyro\n");
            continue;
        }

        ret = spi_read(SPI_READ_X_ACCEL_CMD | SPI_READ_CMD, &x_accel);
        if (ret < 0) {
            fprintf(stderr, "Failed to read X accel\n");
            continue;
        }

        ret = spi_read(SPI_READ_Y_ACCEL_CMD | SPI_READ_CMD, &y_accel);
        if (ret < 0) {
            fprintf(stderr, "Failed to read Y accel\n");
            continue;
        }

        ret = spi_read(SPI_READ_Z_ACCEL_CMD | SPI_READ_CMD, &z_accel);
        if (ret < 0) {
            fprintf(stderr, "Failed to read Z accel\n");
            continue;
        }

        ret = csv_log(&timestamp, x_gyro * SPI_READ_X_GYRO_SCALE, y_gyro * SPI_READ_Y_GYRO_SCALE, z_gyro * SPI_READ_Z_GYRO_SCALE, x_accel * SPI_READ_X_ACCEL_SCALE, y_accel * SPI_READ_Y_ACCEL_SCALE, z_accel * SPI_READ_Z_ACCEL_SCALE);
        if (ret < 0) {
            fprintf(stderr, "Failed to log data to CSV file\n");
            continue;
        }

        usleep(SPI_DELAY);
    }

    cleanup();

    return EXIT_SUCCESS;
}

