Write a C program for a Raspberry Pi 3 Model B+ that continuously polls two Keyes KY‑032 IR obstacle‑avoidance sensors connected on the GPIO bus, with sensor 1 wired to GPIO17 (physical pin 11) and sensor 2 to GPIO27 (physical pin 13), using a single bulk‑read API call that reads both lines together at a 100 ms interval, interprets the active‑low output (0 = obstacle detected, 1 = path clear), logs the detection status together with a timestamp to the console on each poll, checks the return value of every driver call and handles the case where the API call or the GPIO lines are unavailable, runs in an infinite loop until interrupted, and on any exit path—including receipt of SIGINT (Ctrl+C)—performs clean release of all resources, while compiling cleanly with ‑Wall ‑Wextra against driver version 2.0 or newer.

### Response:
```
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1 17
#define SENSOR_2 27
#define POLL_INTERVAL 100

int main(void)
{
    int status;
    int sensor_1_value;
    int sensor_2_value;
    struct timespec timestamp;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1, PI_INPUT) < 0)
    {
        fprintf(stderr, "Failed to set GPIO mode for sensor 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2, PI_INPUT) < 0)
    {
        fprintf(stderr, "Failed to set GPIO mode for sensor 2\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1)
    {
        if (clock_gettime(CLOCK_REALTIME, &timestamp) < 0)
        {
            fprintf(stderr, "Failed to get timestamp\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        status = gpioRead_Bits_0_31_1(&sensor_1_value, &sensor_2_value);

        if (status < 0)
        {
            fprintf(stderr, "Failed to read GPIO lines\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Timestamp: %ld.%09ld, Sensor 1: %d, Sensor 2: %d\n", timestamp.tv_sec, timestamp.tv_nsec, sensor_1_value, sensor_2_value);

        usleep(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}
