#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SLEEP_TIME 1000
#define WINDOW_TIME 5000

int threshold = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpioTerminate();
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int count = 0;
        time_t start_time = time(NULL);

        while (time(NULL) - start_time < WINDOW_TIME) {
            if (gpioRead(GPIO_PIN) == 1) {
                count++;
            }
            gpioDelay(SLEEP_TIME);
        }

        if (count >= threshold) {
            printf("ALERT: %d high readings in the last 5 seconds\n", count);
        } else {
            printf("STATUS: %d high readings in the last 5 seconds\n", count);
        }

        gpioDelay(1000);
    }

    return 0;
}

