#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define PIR_POLL_INTERVAL 50000
#define RELAY_ON_TIME 1
#define FAILSAFE_TIME 10

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static int pir_value;
static int relay_value;
static int failsafe_active;

static void pir_event(struct gpiod_line *line, void *data)
{
    int value;

    value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value: %s", strerror(errno));
        return;
    }

    if (value == pir_value)
        return;

    pir_value = value;
    if (pir_value) {
        syslog(LOG_INFO, "PIR HIGH");
        if (failsafe_active) {
            syslog(LOG_WARNING, "PIR HIGH while failsafe active");
            return;
        }
        if (relay_value) {
            syslog(LOG_WARNING, "PIR HIGH while relay active");
            return;
        }
        relay_value = 1;
        if (gpiod_line_set_value(relay_line, relay_value) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value: %s", strerror(errno));
            return;
        }
        syslog(LOG_INFO, "Relay ON");
        usleep(RELAY_ON_TIME * 1000000);
        relay_value = 0;
        if (gpiod_line_set_value(relay_line, relay_value) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value: %s", strerror(errno));
            return;
        }
        syslog(LOG_INFO, "Relay OFF");
    } else {
        syslog(LOG_INFO, "PIR LOW");
    }
}

static void failsafe(void)
{
    syslog(LOG_WARNING, "Failsafe triggered");
    if (relay_value) {
        relay_value = 0;
        if (gpiod_line_set_value(relay_line, relay_value) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value: %s", strerror(errno));
            return;
        }
        syslog(LOG_INFO, "Relay OFF");
    }
    syslog(LOG_INFO, "Shutdown");
    closelog();
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    exit(0);
}

static void sig_handler(int signo)
{
    switch (signo) {
    case SIGINT:
    case SIGTERM:
        failsafe();
        break;
    }
}

int main(int argc, char *argv[])
{
    struct gpiod_line_request_config pir_config;
    struct gpiod_line_request_config relay_config;
    struct timespec ts;
    int ret;

    openlog("pir_monitor", LOG_CONS | LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Startup");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        return 1;
    }

    gpiod_line_request_config_init(&pir_config, chip, PIR_GPIO, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line: %s", strerror(errno));
        return 1;
    }
    ret = gpiod_line_request(pir_line, &pir_config, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "gpiod_line_request: %s", strerror(errno));
        return 1;
    }

    gpiod_line_request_config_init(&relay_config, chip, RELAY_GPIO, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line: %s", strerror(errno));
        return 1;
    }
    ret = gpiod_line_request(relay_line, &relay_config, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "gpiod_line_request: %s", strerror(errno));
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

