static void pir_event(struct gpiod_line *line, void *data)
{
    int value;

    value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value: %s", strerror(errno));
        return;
    }

    if (value == pir_value)
        return;

    pir_value = value;
    if (pir_value) {
        syslog(LOG_INFO, "PIR HIGH");
        if (failsafe_active) {
            syslog(LOG_WARNING, "PIR HIGH while failsafe active");
            return;
        }
        if (relay_value) {
            syslog(LOG_WARNING, "PIR HIGH while relay active");
            return;
        }
        relay_value = 1;
        if (gpiod_line_set_value(relay_line, relay_value) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value: %s", strerror(errno));
            return;
        }
        syslog(LOG_INFO, "Relay ON");
        usleep(RELAY_ON_TIME * 1000000);
        relay_value = 0;
        if (gpiod_line_set_value(relay_line, relay_value) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value: %s", strerror(errno));
            return;
        }
        syslog(LOG_INFO, "Relay OFF");
    } else {
        syslog(LOG_INFO, "PIR LOW");
    }
}

static void failsafe(void)
{
    syslog(LOG_WARNING, "Failsafe triggered");
    if (relay_value) {
        relay_value = 0;
        if (gpiod_line_set_value(relay_line, relay_value) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value: %s", strerror(errno));
            return;
