#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_SOUND_SENSOR 17
#define GPIO_RELAY 27
#define POLLING_INTERVAL 100000
#define ACTIVATION_TIME 3

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_line_request req;

FILE *fp;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM)
    {
        printf("Received signal %d, shutting down...\n", signo);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(fp);
        exit(0);
    }
}

int main(void)
{
    int ret;
    int sound_detected = 0;
    int relay_active = 0;
    struct timespec ts;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        printf("Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request the sound sensor line
    memset(&req, 0, sizeof(req));
    req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    req.consumer = "sound_sensor";
    req.line_offsets[0] = GPIO_SOUND_SENSOR;
    req.num_lines = 1;
    line = gpiod_chip_get_line(chip, GPIO_SOUND_SENSOR);
    ret = gpiod_line_request(line, &req, 0);
    if (ret < 0)
    {
        printf("Error requesting line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Set up the relay line
    ret = gpiod_line_request_output(line, "relay", GPIO_RELAY);
    if (ret < 0)
    {
        printf("Error requesting relay line: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Open the log file
    fp = fopen("alarm_log.txt", "a");
    if (!fp)
    {
        printf("Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1)
    {
        // Wait for a sound event
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0)
        {
            printf("Error waiting for event: %s\n", strerror(errno));
            break;
        }

        // Check if the sound sensor is still active
        ret = gpiod_line_get_value(line);
        if (ret < 0)
        {
            printf("Error getting line value: %s\n", strerror(errno));
            break;
        }
        if (ret == 0)
        {
            // Sound sensor is not active, continue
            continue;
        }

        // Sound event detected, check if the relay is already active
        if (relay_active)
        {
            // Relay is already active, ignore the event
            continue;
        }

        // Sound event detected, activate the relay
        ret = gpiod_line_set_value(line, GPIO_RELAY, 1);
        if (ret < 0)
        {
            printf("Error setting relay value: %s\n", strerror(errno));
            break;
        }
        relay_active = 1;

        // Get the current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log the activation time
        fprintf(fp, "%ld.%ld\n", ts.tv_sec, ts.tv_nsec);
        fflush(fp);

        // Wait for the activation time to elapse
        usleep(ACTIVATION_TIME * 1000000);

        // Deactivate the relay
        ret = gpiod_line_set_value(line, GPIO_RELAY, 0);
        if (ret < 0)
        {
            printf("Error setting relay value: %s\n", strerror(errno));
            break;
        }
        relay_active = 0;
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(fp);

    return 0;
}

