#define UNLOCK_MESSAGE "Door unlocked"
#define EXIT_MESSAGE "Program exited"

static volatile int keepRunning = 1;

void handle_signal(int signal)
{
    keepRunning = 0;
}

void step(int in1, int in2, int in3, int in4)
{
    gpioWrite(STEPPER_IN1, in1);
    gpioWrite(STEPPER_IN2, in2);
    gpioWrite(STEPPER_IN3, in3);
    gpioWrite(STEPPER_IN4, in4);
    time_sleep(STEP_DELAY / 1000.0);
}

void lock()
{
    printf("%s\n", LOCK_MESSAGE);
    for (int i = 0; i < LOCK_STEPS; i++)
    {
