    gpioSetMode(STEPPER_IN2, PI_OUTPUT);
    gpioSetMode(STEPPER_IN3, PI_OUTPUT);
    gpioSetMode(STEPPER_IN4, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keepRunning)
    {
        if (gpioRead(LOCK_BUTTON) == 0)
        {
            lock();
            while (gpioRead(LOCK_BUTTON) == 0)
            {
                time_sleep(0.1);
            }
        }
        else if (gpioRead(UNLOCK_BUTTON) == 0)
        {
            unlock();
            while (gpioRead(UNLOCK_BUTTON) == 0)
            {
                time_sleep(0.1);
