#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define FREQUENCY 1000
#define DUTY_CYCLE 1000000

void sigint_handler(int sig)
{
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[])
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, FREQUENCY);

    gpioSetPWMrange(RED_PIN, DUTY_CYCLE);
    gpioSetPWMrange(GREEN_PIN, DUTY_CYCLE);
    gpioSetPWMrange(BLUE_PIN, DUTY_CYCLE);

    signal(SIGINT, sigint_handler);

    while (1)
    {
        for (double i = 0.0; i < 1.0; i += 0.01)
        {
            double red = sin(i * 2 * M_PI);
            double green = sin(i * 2 * M_PI + 2 * M_PI / 3);
            double blue = sin(i * 2 * M_PI + 4 * M_PI / 3);

            gpioPWM(RED_PIN, (int)(red * DUTY_CYCLE));
            gpioPWM(GREEN_PIN, (int)(green * DUTY_CYCLE));
            gpioPWM(BLUE_PIN, (int)(blue * DUTY_CYCLE));

            usleep(10000);
        }
    }

    return 0;
}

