#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18
#define VALVE_PULSE_WIDTH 1500
#define NOZZLE_PULSE_WIDTH_0 500
#define NOZZLE_PULSE_WIDTH_45 1000
#define NOZZLE_PULSE_WIDTH_90 1500
#define NOZZLE_PULSE_WIDTH_135 2000
#define NOZZLE_PULSE_WIDTH_180 2500
#define SPRAY_DURATION 5
#define WATERING_CYCLE_DURATION 5
#define MOISTURE_THRESHOLD 50
#define MAX_RETRIES 3
#define RETRY_BACKOFF 100000

static volatile sig_atomic_t stop = 0;

static void sig_handler(int signum)
{
    stop = 1;
}

static int set_servo_pulse_width(struct gpiod_line *line, unsigned int pulse_width)
{
    int ret;

    ret = gpiod_line_request_output(line, "servo", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d for output: %s\n",
                gpiod_line_get_number(line), strerror(-ret));
        return ret;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line %d to 1: %s\n",
                gpiod_line_get_number(line), strerror(-ret));
        return ret;
    }

    usleep(pulse_width);

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line %d to 0: %s\n",
                gpiod_line_get_number(line), strerror(-ret));
        return ret;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *valve_line, *nozzle_line;
    int ret, moisture, retries;
    unsigned int pulse_width;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    valve_line = gpiod_chip_get_line(chip, VALVE_GPIO);
    if (!valve_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", VALVE_GPIO, strerror(errno));
        return EXIT_FAILURE;
    }

    nozzle_line = gpiod_chip_get_line(chip, NOZZLE_GPIO);
    if (!nozzle_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", NOZZLE_GPIO, strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        moisture = 20;
        while (moisture <= 100) {
            printf("Moisture: %d\n", moisture);

            if (moisture < MOISTURE_THRESHOLD) {
                printf("Watering...\n");

                retries = 0;
                do {
                    ret = set_servo_pulse_width(valve_line, VALVE_PULSE_WIDTH);
                    if (ret < 0) {
                        fprintf(stderr, "Failed to set valve pulse width: %s\n", strerror(-ret));
                        retries++;
                        usleep(RETRY_BACKOFF);
                    }
                } while (ret < 0 && retries < MAX_RETRIES);

                if (ret < 0) {
                    fprintf(stderr, "Failed to set valve pulse width after %d retries\n", MAX_RETRIES);
                    return EXIT_FAILURE;
                }

                pulse_width = NOZZLE_PULSE_WIDTH_0;
                while (pulse_width <= NOZZLE_PULSE_WIDTH_180) {
                    retries = 0;
                    do {
                        ret = set_servo_pulse_width(nozzle_line, pulse_width);
                        if (ret < 0) {
                            fprintf(stderr, "Failed to set nozzle pulse width: %s\n", strerror(-ret));
                            retries++;
                            usleep(RETRY_BACKOFF);
                        }
                    } while (ret < 0 && retries < MAX_RETRIES);

                    if (ret < 0) {
                        fprintf(stderr, "Failed to set nozzle pulse width after %d retries\n", MAX_RETRIES);
                        return EXIT_FAILURE;
                    }

                    sleep(2);

                    pulse_width += NOZZLE_PULSE_WIDTH_45;
                }

                sleep(SPRAY_DURATION);

                retries = 0;
                do {
                    ret = set_servo_pulse_width(valve_line, 0);
                    if (ret < 0) {
                        fprintf(stderr, "Failed to set valve pulse width: %s\n", strerror(-ret));
                        retries++;
                        usleep(RETRY_BACKOFF);
                    }
                } while (ret < 0 && retries < MAX_RETRIES);

                if (ret < 0) {
                    fprintf(stderr, "Failed to set valve pulse width after %d retries\n", MAX_RETRIES);
                    return EXIT_FAILURE;
                }
            }

            sleep(WATERING_CYCLE_DURATION);

            moisture += 20;
        }
    }

    gpiod_line_release(valve_line);
    gpiod_line_release(nozzle_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

