#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define TRIGGER_DELAY 10
#define SAMPLING_INTERVAL 1
#define TIMEOUT 50
#define LOG_FILE "distance_log.txt"

int main(void)
{
    int fd, ret;
    struct gpiohandle_request req;
    struct gpioevent_request event_req;
    struct timespec ts;
    struct timespec ts_start, ts_end;
    double distance;
    FILE *fp;

    // Open the GPIO character device file
    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up the trigger GPIO line
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = TRIGGER_GPIO;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.default_values[0] = 0;
    req.lines = 1;
    ret = ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", TRIGGER_GPIO, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up the echo GPIO line
    memset(&event_req, 0, sizeof(event_req));
    event_req.lineoffset = ECHO_GPIO;
    event_req.eventflags = GPIOEVENT_REQUEST_RISING_EDGE | GPIOEVENT_REQUEST_FALLING_EDGE;
    ret = ioctl(fd, GPIO_GET_LINEEVENT_IOCTL, &event_req);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO event for line %d: %s\n", ECHO_GPIO, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Generate a 10us trigger pulse
        req.values[0] = 1;
        ret = ioctl(fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &req);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            break;
        }
        usleep(TRIGGER_DELAY);
        req.values[0] = 0;
        ret = ioctl(fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &req);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            break;
        }

        // Wait for the rising edge of the echo signal
        ret = ioctl(fd, GPIO_WAIT_FOR_EVENT, &event_req);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for rising edge: %s\n", strerror(errno));
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &ts_start);

        // Wait for the falling edge of the echo signal
        ret = ioctl(fd, GPIO_WAIT_FOR_EVENT, &event_req);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for falling edge: %s\n", strerror(errno));
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &ts_end);

        // Calculate the distance
        ts = ts_end;
        ts.tv_sec -= ts_start.tv_sec;
        ts.tv_nsec -= ts_start.tv_nsec;
        if (ts.tv_nsec < 0) {
            ts.tv_sec--;
            ts.tv_nsec += 1000000000;
        }
        distance = ts.tv_sec * 1000000000.0 + ts.tv_nsec;
        distance = distance / 58000.0;

        // Write the distance to the log file
        fprintf(fp, "%.2f\n", distance);
        fflush(fp);

        // Sleep for the sampling interval
        usleep(SAMPLING_INTERVAL * 1000000);
    }

    // Clean up
    fclose(fp);
    close(fd);

    return EXIT_SUCCESS;
}

