void gpio_init() {
    int i;
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }
    for (i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINE_NUMBERS[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE_NUMBERS[i]);
            exit(EXIT_FAILURE);
        }
    }
    req.lines_count = GPIO_LINE_COUNT;
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req.default_values = GPIO_LINE_DEFAULT_VALUES;
    req.flags = GPIO_LINE_ACTIVE_LOW ? GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW : 0;
    req.consumer = "watering";
    req.lines = lines;
    if (gpiod_chip_request_lines(chip, &req) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        exit(EXIT_FAILURE);
    }
}

