#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_COUNT 4
#define GPIO_LINE_NAMES "17", "18", "27", "22"
#define GPIO_LINE_NUMBERS 17, 18, 27, 22
#define GPIO_LINE_ACTIVE_LOW 1
#define GPIO_LINE_DEFAULT_VALUES 1, 1, 1, 1
#define GPIO_LINE_DIRECTIONS 1, 1, 1, 1
#define GPIO_LINE_VALUES 0, 0, 0, 0
#define GPIO_LINE_DELAY 5
#define GPIO_LINE_CYCLE_DELAY 86400
#define GPIO_LINE_LOG_FILE "watering_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *lines[GPIO_LINE_COUNT];
struct gpiod_line_request req;

void gpio_init() {
    int i;
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }
    for (i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINE_NUMBERS[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE_NUMBERS[i]);
            exit(EXIT_FAILURE);
        }
    }
    req.lines_count = GPIO_LINE_COUNT;
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req.default_values = GPIO_LINE_DEFAULT_VALUES;
    req.flags = GPIO_LINE_ACTIVE_LOW ? GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW : 0;
    req.consumer = "watering";
    req.lines = lines;
    if (gpiod_chip_request_lines(chip, &req) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        exit(EXIT_FAILURE);
    }
}

void gpio_set_values(int values[]) {
    int i;
    for (i = 0; i < GPIO_LINE_COUNT; i++) {
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "Failed to set GPIO line %d value\n", GPIO_LINE_NUMBERS[i]);
            exit(EXIT_FAILURE);
        }
    }
}

void gpio_close() {
    gpiod_chip_close(chip);
}

void log_cycle(time_t t) {
    FILE *f = fopen(GPIO_LINE_LOG_FILE, "a");
    if (f == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(f, "%s", ctime(&t));
    fclose(f);
}

void signal_handler(int signum) {
    gpio_set_values(GPIO_LINE_DEFAULT_VALUES);
    gpio_close();
    exit(EXIT_SUCCESS);
}

