#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <wiringPi.h>

#define I2C_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define LED_PIN 1

int i2c_fd;
FILE *log_file;

void close_resources(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    digitalWrite(LED_PIN, LOW);
    wiringPiSetupGpio();
    pinMode(LED_PIN, OUTPUT);
    exit(0);
}

int main() {
    int ret;
    char buf[100];
    char log_line[100];
    time_t t;
    struct tm *tm;
    int ambient_light, proximity;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, close_resources);
    signal(SIGTERM, close_resources);

    // Set up LED pin
    wiringPiSetupGpio();
    pinMode(LED_PIN, OUTPUT);

    // Read and log data every 100 ms
    while (1) {
        // Read ambient light
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("Failed to read ambient light");
            continue;
        }
        ambient_light = (buf[0] << 8) | buf[1];

        // Read proximity
        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("Failed to read proximity");
            continue;
        }
        proximity = (buf[0] << 8) | buf[1];

        // Log data
        t = time(NULL);
        tm = localtime(&t);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S,AmbientLight:%d,Proximity:%d\n", tm, ambient_light, proximity);
        fputs(log_line, log_file);
        fflush(log_file);

        // Turn on LED if proximity exceeds 100
        if (proximity > 100) {
            digitalWrite(LED_PIN, HIGH);
        } else {
            digitalWrite(LED_PIN, LOW);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

