#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *relay_line;

static void cleanup(void)
{
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (relay_line)
        gpiod_line_release(relay_line);
    if (chip)
        gpiod_chip_close(chip);
}

static void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

int main(void)
{
    int ret;
    int sensor_value;
    struct timespec ts;

    /* Register signal handlers */
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the sensor line */
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Get the relay line */
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure the sensor line as an input with a pull-down resistor */
    ret = gpiod_line_request_input_flags(sensor_line, "sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure the relay line as an output */
    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request relay line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (1) {
        /* Read the sensor value */
        ret = gpiod_line_get_value(sensor_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        /* Check for a touch */
        if (ret == 1 && sensor_value == 0) {
            /* Toggle the relay */
            ret = gpiod_line_set_value(relay_line, !gpiod_line_get_value(relay_line));
            if (ret < 0) {
                fprintf(stderr, "Failed to toggle relay: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }

            /* Wait for the debounce delay */
            ts.tv_sec = 0;
            ts.tv_nsec = DEBOUNCE_DELAY_MS * 1000000;
            nanosleep(&ts, NULL);
        }

        sensor_value = ret;
    }

    cleanup();
    return EXIT_SUCCESS;
}

