#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22

#define RELAY_COUNT 4

#define LOG_FILE "irrigation_log.txt"

#define SENSOR_MIN 0
#define SENSOR_MAX 100

#define SENSOR_DRY 30

#define SLEEP_TIME 5

struct gpiod_chip *chip;
struct gpiod_line *lines[RELAY_COUNT];

FILE *log_file;

void signal_handler(int signum)
{
    int i;

    for (i = 0; i < RELAY_COUNT; i++)
    {
        gpiod_line_set_value(lines[i], 1);
    }

    fclose(log_file);

    gpiod_chip_close(chip);

    exit(signum);
}

int main(void)
{
    int i;
    int sensor_value;
    int relay_state[RELAY_COUNT];
    time_t timestamp;
    char *timestamp_str;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");

    if (chip == NULL)
    {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    for (i = 0; i < RELAY_COUNT; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, RELAY_1 + i);

        if (lines[i] == NULL)
        {
            fprintf(stderr, "Error getting GPIO line %d\n", RELAY_1 + i);
            return 1;
        }

        if (gpiod_line_request_output(lines[i], "irrigation", 0) < 0)
        {
            fprintf(stderr, "Error requesting GPIO line %d\n", RELAY_1 + i);
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "w");

    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    srand(time(NULL));

    while (1)
    {
        sensor_value = rand() % (SENSOR_MAX - SENSOR_MIN + 1) + SENSOR_MIN;

        for (i = 0; i < RELAY_COUNT; i++)
        {
            relay_state[i] = (sensor_value < SENSOR_DRY) ? 0 : 1;
            gpiod_line_set_value(lines[i], relay_state[i]);
        }

        timestamp = time(NULL);
        timestamp_str = ctime(&timestamp);
        timestamp_str[strlen(timestamp_str) - 1] = '\0';

        fprintf(log_file, "%d, %d, %d, %d, %s\n", sensor_value, relay_state[0], relay_state[1], relay_state[2], timestamp_str);

        sleep(SLEEP_TIME);
    }

    return 0;
}

