    {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    for (i = 0; i < RELAY_COUNT; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, RELAY_1 + i);

        if (lines[i] == NULL)
