    {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    srand(time(NULL));

    while (1)
    {
        sensor_value = rand() % (SENSOR_MAX - SENSOR_MIN + 1) + SENSOR_MIN;

        for (i = 0; i < RELAY_COUNT; i++)
        {
            relay_state[i] = (sensor_value < SENSOR_DRY) ? 0 : 1;
            gpiod_line_set_value(lines[i], relay_state[i]);
        }

        timestamp = time(NULL);
        timestamp_str = ctime(&timestamp);
        timestamp_str[strlen(timestamp_str) - 1] = '\0';

        fprintf(log_file, "%d, %d, %d, %d, %s\n", sensor_value, relay_state[0], relay_state[1], relay_state[2], timestamp_str);

        sleep(SLEEP_TIME);
    }

    return 0;
}
