#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS_1 1
#define I2C_ADDR_1 0x40
#define I2C_ADDR_2 0x41
#define I2C_START_MEASUREMENT_CMD_1 0x00
#define I2C_START_MEASUREMENT_CMD_2 0x10
#define I2C_READ_MEASUREMENT_CMD 0x00
#define I2C_CRC_POLYNOMIAL 0x31
#define I2C_CRC_INITIAL_VALUE 0xFF
#define I2C_CRC_FINAL_XOR 0x00
#define GPIO_18 18
#define GPIO_18_ACTIVE_HIGH 1
#define GPIO_18_ACTIVE_LOW 0
#define FLOW_RATE_THRESHOLD 5.0
#define POLLING_INTERVAL_MS 100
#define FLOW_LOG_FILE_PATH "flow_log.txt"

static int i2c_fd_1 = -1;
static int i2c_fd_2 = -1;
static int gpio_18_fd = -1;
static bool is_relay_energized = false;

static void cleanup(void)
{
    if (gpio_18_fd >= 0) {
        gpioWrite(GPIO_18, GPIO_18_ACTIVE_LOW);
        gpioTerminate();
    }
    if (i2c_fd_1 >= 0) {
        close(i2c_fd_1);
    }
    if (i2c_fd_2 >= 0) {
        close(i2c_fd_2);
    }
}

static void sig_handler(int signum)
{
    cleanup();
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

static void setup_signal_handlers(void)
{
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);
}

static int open_i2c_bus(int bus)
{
    char i2c_dev_path[32];
    snprintf(i2c_dev_path, sizeof(i2c_dev_path), "/dev/i2c-%d", bus);
    int fd = open(i2c_dev_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

static int open_i2c_device(int bus, int addr)
{
    int fd = open_i2c_bus(bus);
    if (fd < 0) {
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C device address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static bool start_measurement(int fd)
{
    uint8_t cmd[2] = {I2C_START_MEASUREMENT_CMD_1, I2C_START_MEASUREMENT_CMD_2};
    if (write(fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        fprintf(stderr, "Failed to start measurement: %s\n", strerror(errno));
        return false;
    }
    return true;
}

static bool read_measurement(int fd, uint8_t *data)
{
    if (read(fd, data, 3) != 3) {
        fprintf(stderr, "Failed to read measurement: %s\n", strerror(errno));
        return false;
    }
    return true;
}

static bool validate_crc(const uint8_t *data, size_t len)
{
    uint8_t crc = I2C_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ I2C_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == I2C_CRC_FINAL_XOR;
}

static bool read_and_validate_measurement(int fd, uint8_t *data)
{
    if (!start_measurement(fd)) {
        return false;
    }
    if (!read_measurement(fd, data)) {
        return false;
    }
    if (!validate_crc(data, 2)) {
        fprintf(stderr, "CRC check failed\n");
        return false;
    }
    return true;
}

static double calculate_flow_rate(const uint8_t *data)
{
    uint16_t raw_value = (data[0] << 8) | data[1];
    return (double)raw_value / 1000.0;
}

static bool log_flow_rate(double flow_rate)
{
    FILE *fp = fopen(FLOW_LOG_FILE_PATH, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open flow log file: %s\n", strerror(errno));
        return false;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s %.3f\n", timestamp, flow_rate);
    fflush(fp);
    fclose(fp);
    return true;
}

static bool energize_relay(void)
{
    if (gpioWrite(GPIO_18, GPIO_18_ACTIVE_HIGH) != 0) {
        fprintf(stderr, "Failed to energize relay: %s\n", strerror(errno));
        return false;
    }
    is_relay_energized = true;
    return true;
}

static bool deenergize_relay(void)
{
    if (gpioWrite(GPIO_18, GPIO_18_ACTIVE_LOW) != 0) {
        fprintf(stderr, "Failed to de-energize relay: %s\n", strerror(errno));
        return false;
    }
    is_relay_energized = false;
    return true;
}

static bool check_flow_rate(double flow_rate)
{
    if (flow_rate < FLOW_RATE_THRESHOLD) {
        if (is_relay_energized) {
            return deenergize_relay();
        }
    } else {
        if (!is_relay_energized) {
            return energize_relay();
        }
    }
    return true;
}

static bool monitor_sensors(void)
{
    uint8_t data_1[3];
    uint8_t data_2[3];
    if (!read_and_validate_measurement(i2c_fd_1, data_1)) {
        return false;
    }
    if (!read_and_validate_measurement(i2c_fd_2, data_2)) {
        return false;
    }
    double flow_rate_1 = calculate_flow_rate(data_1);
    double flow_rate_2 = calculate_flow_rate(data_2);
    if (!log_flow_rate(flow_rate_1)) {
        return false;
    }
    if (!log_flow_rate(flow_rate_2)) {
        return false;
    }
    if (!check_flow_rate(flow_rate_1)) {
        return false;
    }
    if (!check_flow_rate(flow_rate_2)) {
        return false;
    }
    return true;
}

int main(void)
{
    setup_signal_handlers();
    atexit(cleanup);

    i2c_fd_1 = open_i2c_device(I2C_BUS_1, I2C_ADDR_1);
    if (i2c_fd_1 < 0) {
        return EXIT_FAILURE;
    }
    i2c_fd_2 = open_i2c_device(I2C_BUS_1, I2C_ADDR_2);
    if (i2c_fd_2 < 0) {
        return EXIT_FAILURE;
    }

