        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    gpio_18_fd = gpioSetMode(GPIO_18, PI_OUTPUT);
    if (gpio_18_fd < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (!deenergize_relay()) {
        return EXIT_FAILURE;
    }

    while (true) {
        if (!monitor_sensors()) {
            continue;
        }
        usleep(POLLING_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

