#include <linux/gpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>

#define GPIO_PIN_SENSOR 17
#define GPIO_PIN_MOTOR_EN 22
#define GPIO_PIN_MOTOR_IN1 23
#define GPIO_PIN_MOTOR_IN2 24

#define GPIO_DIRECTION_IN 0
#define GPIO_DIRECTION_OUT 1

#define GPIO_VALUE_LOW 0
#define GPIO_VALUE_HIGH 1

#define GPIO_EDGE_NONE 0
#define GPIO_EDGE_RISING 1
#define GPIO_EDGE_FALLING 2
#define GPIO_EDGE_BOTH 3

#define LOG_TAG "rain_window"

int gpio_export(unsigned int gpio)
{
    int fd, len;
    char buf[11];

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "%s: cannot open export", LOG_TAG);
        return -1;
    }

    len = snprintf(buf, sizeof(buf), "%d", gpio);
    write(fd, buf, len);
    close(fd);

    return 0;
}

int gpio_unexport(unsigned int gpio)
{
    int fd, len;
    char buf[11];

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "%s: cannot open unexport", LOG_TAG);
        return -1;
    }

    len = snprintf(buf, sizeof(buf), "%d", gpio);
    write(fd, buf, len);
    close(fd);

    return 0;
}

int gpio_set_direction(unsigned int gpio, unsigned int direction)
{
    int fd, len;
    char buf[60];

    len = snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/direction", gpio);

    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "%s: cannot open direction", LOG_TAG);
        return -1;
    }

    if (direction == GPIO_DIRECTION_IN)
        write(fd, "in", 2);
    else
        write(fd, "out", 3);

    close(fd);

    return 0;
}

int gpio_set_edge(unsigned int gpio, unsigned int edge)
{
    int fd, len;
    char buf[60];

    len = snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/edge", gpio);

    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "%s: cannot open edge", LOG_TAG);
        return -1;
    }

    if (edge == GPIO_EDGE_NONE)
        write(fd, "none", 4);
    else if (edge == GPIO_EDGE_RISING)
        write(fd, "rising", 6);
    else if (edge == GPIO_EDGE_FALLING)
        write(fd, "falling", 7);
    else
        write(fd, "both", 4);

    close(fd);

    return 0;
}

int gpio_set_value(unsigned int gpio, unsigned int value)
{
    int fd, len;
    char buf[60];

    len = snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/value", gpio);

    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "%s: cannot open value", LOG_TAG);
        return -1;
    }

    if (value == GPIO_VALUE_LOW)
        write(fd, "0", 1);
    else
        write(fd, "1", 1);

    close(fd);

    return 0;
}

int gpio_get_value(unsigned int gpio, unsigned int *value)
{
    int fd, len;
    char buf[60];
    char ch;

    len = snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/value", gpio);

    fd = open(buf, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "%s: cannot open value", LOG_TAG);
        return -1;
    }

    read(fd, &ch, 1);

    if (ch != '0')
        *value = 1;
    else
        *value = 0;

    close(fd);

    return 0;
}

int gpio_fd_open(unsigned int gpio)
{
    int fd, len;
    char buf[60];

    len = snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/value", gpio);

    fd = open(buf, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "%s: cannot open value", LOG_TAG);
        return -1;
    }

    return fd;
}

int gpio_fd_close(int fd)
{
    return close(fd);
}

int gpio_fd_get_value(int fd, unsigned int *value)
{
    char ch;

    read(fd, &ch, 1);

    if (ch != '0')
        *value = 1;
    else
        *value = 0;

    return 0;
}

int gpio_fd_poll(int fd, unsigned int timeout)
{
    struct pollfd fds[1];
    int ret;

    fds[0].fd = fd;
    fds[0].events = POLLPRI;

    ret = poll(fds, 1, timeout);
    if (ret < 0) {
        syslog(LOG_ERR, "%s: cannot poll", LOG_TAG);
        return -1;
    }

    if (ret == 0)
        return 0;

    lseek(fd, 0, SEEK_SET);

    return 1;
}

