#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SERVO_GPIO 18
#define LOCK_GPIO 21
#define UNLOCK_GPIO 22
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000
#define DEBOUNCE_DELAY 100000

struct gpiod_chip *chip;
struct gpiod_line *servo_line, *lock_line, *unlock_line;

void lock_door(void)
{
    printf("Locking door\n");
    gpiod_line_request_output(servo_line, "servo", 0);
    gpiod_line_set_value(servo_line, 1);
    usleep(LOCK_PULSE_WIDTH);
    gpiod_line_set_value(servo_line, 0);
    gpiod_line_release(servo_line);
}

void unlock_door(void)
{
    printf("Unlocking door\n");
    gpiod_line_request_output(servo_line, "servo", 0);
    gpiod_line_set_value(servo_line, 1);
    usleep(UNLOCK_PULSE_WIDTH);
    gpiod_line_set_value(servo_line, 0);
    gpiod_line_release(servo_line);
}

void shutdown_handler(int signum)
{
    printf("Shutting down\n");
    gpiod_line_request_output(servo_line, "servo", 0);
    gpiod_line_set_value(servo_line, 1);
    usleep(0);
    gpiod_line_set_value(servo_line, 0);
    gpiod_line_release(servo_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main(void)
{
    int lock_value, unlock_value;

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        printf("Error opening GPIO chip\n");
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        printf("Error getting servo GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_GPIO);
    if (!lock_line) {
        printf("Error getting lock GPIO line\n");
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    unlock_line = gpiod_chip_get_line(chip, UNLOCK_GPIO);
    if (!unlock_line) {
        printf("Error getting unlock GPIO line\n");
        gpiod_line_release(servo_line);
        gpiod_line_release(lock_line);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_input(lock_line, "lock");
    gpiod_line_request_input(unlock_line, "unlock");
    gpiod_line_set_value(lock_line, 1);
    gpiod_line_set_value(unlock_line, 1);

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (1) {
        lock_value = gpiod_line_get_value(lock_line);
        unlock_value = gpiod_line_get_value(unlock_line);

        if (lock_value == 0) {
            lock_door();
            usleep(DEBOUNCE_DELAY);
        } else if (unlock_value == 0) {
            unlock_door();
            usleep(DEBOUNCE_DELAY);
        }

        usleep(1000);
    }

    gpiod_line_release(servo_line);
    gpiod_line_release(lock_line);
    gpiod_line_release(unlock_line);
    gpiod_chip_close(chip);

    return 0;
}

