#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

#define PIR_PIN 4

#define LOG_ERROR(fmt, ...) log_message(LOG_ERR, fmt, ##__VA_ARGS__)
#define LOG_INFO(fmt, ...) log_message(LOG_INFO, fmt, ##__VA_ARGS__)

static int log_fd = -1;

static void log_message(int priority, const char *format, ...)
{
    va_list args;
    char buf[1024];
    int n;

    va_start(args, format);
    n = vsnprintf(buf, sizeof(buf), format, args);
    va_end(args);

    if (n < 0) {
        syslog(LOG_ERR, "vsnprintf failed: %m");
        return;
    }

    if (n >= sizeof(buf)) {
        syslog(LOG_ERR, "log message too long");
        return;
    }

    if (log_fd >= 0) {
        write(log_fd, buf, n);
        write(log_fd, "\n", 1);
    }

    syslog(priority, "%s", buf);
}

static void log_init(void)
{
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "open %s failed: %m", LOG_FILE);
        return;
    }

    if (fcntl(log_fd, F_SETFD, FD_CLOEXEC) < 0) {
        syslog(LOG_ERR, "fcntl %s failed: %m", LOG_FILE);
        return;
    }
}

static void log_deinit(void)
{
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

static void gpio_init(void)
{
    if (gpioInitialise() < 0) {
        LOG_ERROR("gpioInitialise failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        LOG_ERROR("gpioSetMode failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        LOG_ERROR("gpioSetMode failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void gpio_deinit(void)
{
    gpioTerminate();
}

static void servo_set_angle(int angle)
{
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        LOG_ERROR("invalid angle %d", angle);
        return;
    }

    int pulse = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / SERVO_MAX_ANGLE);

    if (gpioServo(SERVO_PIN, pulse) < 0) {
        LOG_ERROR("gpioServo failed: %s", strerror(errno));
        return;
    }

    LOG_INFO("servo set to %d degrees", angle);
}

static void pir_read(void)
{
    int level = gpioRead(PIR_PIN);
    if (level < 0) {
        LOG_ERROR("gpioRead failed: %s", strerror(errno));
        return;
    }

    LOG_INFO("PIR: %d", level);
}

static void handle_command(const char *command)
{
    if (strncmp(command, "the library's API call ", 23) == 0) {
        int angle = atoi(command + 23);
        servo_set_angle(angle);
    } else if (strcmp(command, "PIR") == 0) {
        pir_read();
    } else {
        LOG_ERROR("invalid command: %s", command);
    }
}

static void handle_client(int client_fd)
{
    char buf[1024];
    int n;

    while ((n = read(client_fd, buf, sizeof(buf))) > 0) {
        buf[n] = '\0';
        handle_command(buf);
    }

    if (n < 0) {
        LOG_ERROR("read failed: %m");
    }

    close(client_fd);
}

static void handle_connection(int server_fd)
{
    int client_fd;
    struct sockaddr_in client_addr;
    socklen_t client_addr_len;

    client_addr_len = sizeof(client_addr);
    client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_addr_len);
    if (client_fd < 0) {
        LOG_ERROR("accept failed: %m");
        return;
    }

    if (fcntl(client_fd, F_SETFD, FD_CLOEXEC) < 0) {
        LOG_ERROR("fcntl failed: %m");
        close(client_fd);
        return;
    }

    handle_client(client_fd);
}

static void handle_signal(int signum)
{
    LOG_INFO("received signal %d", signum);
    exit(EXIT_SUCCESS);
}

static void server_init(void)
{
    int server_fd;
    struct sockaddr_in server_addr;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        LOG_ERROR("socket failed: %m");
        exit(EXIT_FAILURE);
    }

    if (fcntl(server_fd, F_SETFD, FD_CLOEXEC) < 0) {
        LOG_ERROR("fcntl failed: %m");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        LOG_ERROR("bind failed: %m");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 5) < 0) {
        LOG_ERROR("listen failed: %m");
        exit(EXIT_FAILURE);
    }

    while (1) {
        handle_connection(server_fd);
    }
}

int main(void)
{
    openlog("servo", LOG_PID, LOG_FACILITY);
    log_init();

    gpio_init();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    server_init();

    gpio_deinit();
    log_deinit();
    closelog();

    return EXIT_SUCCESS;
}

