#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define I2C_CMD_CONT_H_RES_MODE 0x10
#define I2C_CMD_POWER_DOWN 0x00
#define I2C_CMD_POWER_ON 0x01
#define I2C_CMD_RESET 0x07
#define RELAY_PIN 23
#define SAMPLING_INTERVAL 2
#define LOG_FILE "grow_log.txt"

int i2c_fd = -1;
int relay_gpio = -1;
FILE *log_file = NULL;

void cleanup(void)
{
    if (i2c_fd >= 0)
    {
        i2cClose(i2c_fd);
    }
    if (relay_gpio >= 0)
    {
        gpioWrite(relay_gpio, 0);
        gpioSetMode(relay_gpio, PI_INPUT);
        gpioSetPullUpDown(relay_gpio, PI_PUD_OFF);
        gpioTerminate();
    }
    if (log_file != NULL)
    {
        fclose(log_file);
    }
}

void sig_handler(int signum)
{
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;
    uint8_t buf[2];
    uint16_t lux;
    time_t timestamp;
    struct tm *timeinfo;
    char time_str[32];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if ((i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0)
    {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        goto error;
    }

    if ((ret = i2cWriteByte(i2c_fd, I2C_CMD_POWER_ON)) < 0)
    {
        fprintf(stderr, "Failed to power on sensor: %s\n", strerror(errno));
        goto error;
    }

    if ((ret = i2cWriteByte(i2c_fd, I2C_CMD_CONT_H_RES_MODE)) < 0)
    {
        fprintf(stderr, "Failed to set sensor mode: %s\n", strerror(errno));
        goto error;
    }

    if ((ret = gpioInitialise()) < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        goto error;
    }

    if ((relay_gpio = gpioSetMode(RELAY_PIN, PI_OUTPUT)) < 0)
    {
        fprintf(stderr, "Failed to set relay GPIO mode: %s\n", strerror(errno));
        goto error;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL)
    {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto error;
    }

    while (1)
    {
        if ((ret = i2cReadDevice(i2c_fd, buf, 2)) < 0)
        {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            goto error;
        }

        lux = (buf[0] << 8) | buf[1];

        timestamp = time(NULL);
        timeinfo = localtime(&timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (fprintf(log_file, "%s, %u\n", time_str, lux) < 0)
        {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            goto error;
        }

        fflush(log_file);

        if (lux < 150)
        {
            gpioWrite(relay_gpio, 1);
        }
        else
        {
            gpioWrite(relay_gpio, 0);
        }

        sleep(SAMPLING_INTERVAL);
    }

error:
    cleanup();
    return EXIT_FAILURE;
}

