    gpio_line_hx711_sck = open(GPIO_DEV, O_RDWR);
    if (gpio_line_hx711_sck < 0) {
        syslog(LOG_ERR, "Failed to open GPIO line %d: %s", GPIO_LINE_HX711_SCK, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, GPIO_LINE_SOLENOID) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line handle for %d: %s", GPIO_LINE_SOLENOID, strerror(errno));
        exit(EXIT_FAILURE);
