static void setup_spi(void)
{
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint8_t bits_per_word = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
