    if (ioctl(gpio_line_solenoid, GPIOHANDLE_SET_DIRECTION_IOCTL, GPIOHANDLE_DIRECTION_OUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %d direction: %s", GPIO_LINE_SOLENOID, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_line_hx711_dout, GPIOHANDLE_SET_DIRECTION_IOCTL, GPIOHANDLE_DIRECTION_IN) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %d direction: %s", GPIO_LINE_HX711_DOUT, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_line_hx711_sck, GPIOHANDLE_SET_DIRECTION_IOCTL, GPIOHANDLE_DIRECTION_OUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %d direction: %s", GPIO_LINE_HX711_SCK, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void setup_spi(void)
{
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint8_t bits_per_word = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void setup_gpio_and_spi(void)
{
    setup_gpio();
    setup_spi();
}

static void lock_solenoid(void)
{
    if (ioctl(gpio_line_solenoid, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %d value: %s", GPIO_LINE_SOLENOID, strerror(errno));
        exit(EXIT_FAILURE);
    }

    usleep(solenoid_lock_duration_ms * 1000);

    if (ioctl(gpio_line_solenoid, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %d value: %s", GPIO_LINE_SOLENOID, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static uint32_t hx711_read(void)
{
    uint32_t data = 0;
    uint8_t buf[3];

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (ioctl(gpio_line_hx711_dout, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data) < 0) {
            syslog(LOG_ERR, "Failed to get GPIO line %d value: %s", GPIO_LINE_HX711_DOUT, strerror(errno));
            exit(EXIT_FAILURE);
        }

        if (data == 0) {
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - start.tv_sec > HX711_READ_TIMEOUT_MS / 1000) {
            syslog(LOG_ERR, "Timeout waiting for HX711 DOUT to go LOW");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < ARRAY_SIZE(buf); i++) {
        for (int j = 0; j < 8; j++) {
            if (ioctl(gpio_line_hx711_sck, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO line %d value: %s", GPIO_LINE_HX711_SCK, strerror(errno));
                exit(EXIT_FAILURE);
            }

            if (ioctl(gpio_line_hx711_dout, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data) < 0) {
                syslog(LOG_ERR, "Failed to get GPIO line %d value: %s", GPIO_LINE_HX711_DOUT, strerror(errno));
                exit(EXIT_FAILURE);
            }

            buf[i] |= (data << j);

            if (ioctl(gpio_line_hx711_sck, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 0) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO line %d value: %s", GPIO_LINE_HX711_SCK, strerror(errno));
                exit(EXIT_FAILURE);
            }
        }
    }

    if (ioctl(gpio_line_hx711_sck, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %d value: %s", GPIO_LINE_HX711_SCK, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_line_hx711_sck, GPIOHANDLE_SET_LINE_VALUES_IOCTL, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %d value: %s", GPIO_LINE_HX711_SCK, strerror(errno));
        exit(EXIT_FAILURE);
    }

    data = (buf[2] << 16) | (buf[1] << 8) | buf[0];
    return data;
}

static uint32_t hx711_tare(void)
{
    uint32_t data = 0;
    uint32_t sum = 0;

    for (int i = 0; i < 10; i++) {
        data = hx711_read();
        sum += data;
    }

    return sum / 10;
}

static int hx711_get_weight(uint32_t tare)
{
    uint32_t data = 0;
    uint32_t sum = 0;

    for (int i = 0; i < MEASUREMENT_AVERAGE_COUNT; i++) {
        data = hx711_read();
        sum += data;
    }

    data = sum / MEASUREMENT_AVERAGE_COUNT;
    data -= tare;
    data /= HX711_GAIN;

    return data * scale_factor;
}

static void parse_args(int argc, char *argv[])
{
    int c;
    while ((c = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (c) {
        case 't':
            threshold_grams = atoi(optarg);
            break;
        case 's':
            scale_factor = atoi(optarg);
            break;
        case 'd':
            solenoid_lock_duration_ms = atoi(optarg);
            break;
        default:
            exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[])
{
    parse_args(argc, argv);

    setup_syslog();
    setup_signals();
    setup_gpio_and_spi();

    uint32_t tare = hx711_tare();
    syslog(LOG_INFO, "Tare: %d", tare);

    while (1) {
        int weight = hx711_get_weight(tare);
        syslog(LOG_INFO, "Weight: %d", weight);

        if (weight > threshold_grams) {
            lock_solenoid();
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    close_all();
    close_syslog();

    return EXIT_SUCCESS;
}
```

