#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define RELAY_PIN 17

#define SENSOR_DEBOUNCE_DELAY 50
#define MAIN_LOOP_SLEEP_DELAY 10

#define RELAY_ON 1
#define RELAY_OFF 0

#define RELAY_STATE_ON "ON"
#define RELAY_STATE_OFF "OFF"

#define ISO_8601_TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%S%z"

static int relayState = RELAY_OFF;

static void logRelayState(int state) {
    time_t now = time(NULL);
    struct tm *nowLocal = localtime(&now);
    char timestamp[256];
    strftime(timestamp, sizeof(timestamp), ISO_8601_TIMESTAMP_FORMAT, nowLocal);
    printf("%s %s\n", timestamp, state == RELAY_ON ? RELAY_STATE_ON : RELAY_STATE_OFF);
}

static void toggleRelay() {
    if (relayState == RELAY_ON) {
        gpioWrite(RELAY_PIN, RELAY_OFF);
        relayState = RELAY_OFF;
        logRelayState(RELAY_OFF);
    } else {
        gpioWrite(RELAY_PIN, RELAY_ON);
        relayState = RELAY_ON;
        logRelayState(RELAY_ON);
    }
}

static void handleSensorChange(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Sensor is HIGH, debounce and toggle relay
        usleep(SENSOR_DEBOUNCE_DELAY * 1000);
        if (gpioRead(SENSOR_PIN) == 1) {
            toggleRelay();
        }
    } else {
        // Sensor is LOW, wait for next touch
        while (gpioRead(SENSOR_PIN) == 0) {
            usleep(MAIN_LOOP_SLEEP_DELAY * 1000);
        }
    }
}

static void handleSignal(int signal) {
    gpioWrite(RELAY_PIN, RELAY_OFF);
    gpioTerminate();
    printf("Exiting...\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    gpioSetAlertFunc(SENSOR_PIN, handleSensorChange);

    signal(SIGINT, handleSignal);

    while (1) {
        usleep(MAIN_LOOP_SLEEP_DELAY * 1000);
    }

    return 0;
}

