#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define LOG_FILE "door_events.log"
#define RATE_LIMIT 2000

FILE *log_file;
int pir_state = 0;
int relay_state = 0;
time_t last_event_time = 0;

void handle_pir_event(int pin, int level, uint32_t tick) {
    if (level == 1 && pir_state == 0) {
        // Motion detected
        pir_state = 1;
        time_t current_time = time(NULL);
        if (current_time - last_event_time >= RATE_LIMIT / 1000) {
            // Rate limit not exceeded
            last_event_time = current_time;
            fprintf(log_file, "%ld Motion detected\n", current_time);
            fflush(log_file);
            gpioWrite(RELAY_PIN, 1);
            relay_state = 1;
            gpioSetTimerFunc(500, 1, NULL);
        }
    }
}

void handle_relay_event(void) {
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;
    fprintf(log_file, "%ld Door unlocked\n", time(NULL));
    fflush(log_file);
}

void handle_signal(int signum) {
    if (signum == SIGINT) {
        // Handle SIGINT signal
        gpioTerminate();
        fclose(log_file);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);
    gpioSetAlertFunc(PIR_PIN, handle_pir_event);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    signal(SIGINT, handle_signal);

    while (1) {
        gpioDelay(50);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_1 17
#define MOTOR_2 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION 50
#define MAX_STEP_DURATION 200
#define MIN_STEPS 5
#define MAX_STEPS 15

volatile sig_atomic_t shutdown_flag = 0;

void handle_shutdown(int signal) {
    shutdown_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    srand(time(NULL));

    gpioSetMode(MOTOR_1, PI_OUTPUT);
    gpioSetMode(MOTOR_2, PI_OUTPUT);

    while (!shutdown_flag) {
        int num_steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;

        for (int i = 0; i < num_steps; i++) {
            int motor_1_duty_cycle = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
            int motor_2_duty_cycle = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
            int step_duration = rand() % (MAX_STEP_DURATION - MIN_STEP_DURATION + 1) + MIN_STEP_DURATION;

            gpioPWM(MOTOR_1, motor_1_duty_cycle);
            gpioPWM(MOTOR_2, motor_2_duty_cycle);

            usleep(step_duration * 1000);
        }
    }

    gpioPWM(MOTOR_1, 0);
    gpioPWM(MOTOR_2, 0);

    gpioTerminate();

    return 0;
}

