#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_THRESHOLD 10.0
#define READ_TIMEOUT 500

static int running = 1;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;

void sigint_handler(int signum)
{
    running = 0;
}

int main(int argc, char *argv[])
{
    FILE *calibration_file, *weight_log_file;
    double weight, total_weight = 0.0;
    int i;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    signal(SIGINT, sigint_handler);

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file)
    {
        if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2)
        {
            fprintf(stderr, "Failed to read calibration data from %s\n", CALIBRATION_FILE);
            scale_factor = DEFAULT_SCALE_FACTOR;
            offset = DEFAULT_OFFSET;
        }
        fclose(calibration_file);
    }

    weight_log_file = fopen(WEIGHT_LOG_FILE, "a");
    if (!weight_log_file)
    {
        fprintf(stderr, "Failed to open %s for writing: %s\n", WEIGHT_LOG_FILE, strerror(errno));
        return 1;
    }

    for (i = 0; i < CALIBRATION_SAMPLES; i++)
    {
        gpioWrite(HX711_CLOCK_PIN, 0);
        usleep(100);
        gpioWrite(HX711_CLOCK_PIN, 1);
        usleep(100);
        total_weight += gpioRead(HX711_DATA_PIN);
    }
    offset = total_weight / CALIBRATION_SAMPLES;

    while (running)
    {
        gpioWrite(HX711_CLOCK_PIN, 0);
        usleep(100);
        gpioWrite(HX711_CLOCK_PIN, 1);
        usleep(100);
        weight = (gpioRead(HX711_DATA_PIN) - offset) / scale_factor;

        if (weight > CALIBRATION_THRESHOLD)
        {
            gpioWrite(SOLENOID_PIN, 1);
        }
        else
        {
            gpioWrite(SOLENOID_PIN, 0);
        }

        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);
        fprintf(weight_log_file, "%s, %.2f\n", time_string, weight);
        fflush(weight_log_file);

        usleep(READ_TIMEOUT * 1000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    fclose(weight_log_file);

    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file)
    {
        fprintf(calibration_file, "%.2f %.2f\n", scale_factor, offset);
        fclose(calibration_file);
    }

    return 0;
}

