#define BCM2708_PERI_BASE        0x3F000000
#define GPIO_BASE                (BCM2708_PERI_BASE + 0x200000)
#define BLOCK_SIZE               (4*1024)

#define GPIO_SET                 *(gpio+7)
#define GPIO_CLR                 *(gpio+10)
#define GPIO_READ                *(gpio+13)
#define GPIO_PULL                *(gpio+37)
#define GPIO_PULLCLK0            *(gpio+38)

#define HX711_DATA_PIN           4
#define HX711_CLOCK_PIN          17
#define SOLENOID_PIN             27

#define HX711_DATA_MASK          (1 << HX711_DATA_PIN)
#define HX711_CLOCK_MASK         (1 << HX711_CLOCK_PIN)
#define SOLENOID_MASK            (1 << SOLENOID_PIN)

#define HX711_DATA_HIGH()        (GPIO_SET = HX711_DATA_MASK)
#define HX711_DATA_LOW()         (GPIO_CLR = HX711_DATA_MASK)
#define HX711_CLOCK_HIGH()       (GPIO_SET = HX711_CLOCK_MASK)
#define HX711_CLOCK_LOW()        (GPIO_CLR = HX711_CLOCK_MASK)
#define SOLENOID_HIGH()          (GPIO_SET = SOLENOID_MASK)
#define SOLENOID_LOW()           (GPIO_CLR = SOLENOID_MASK)

#define HX711_DATA_READ()        (GPIO_READ & HX711_DATA_MASK)

#define HX711_CLOCK_DELAY_US     1
#define HX711_DATA_TIMEOUT_US    100000

#define SOLENOID_DELAY_S         5

#define CALIBRATION_FILE         "calibration.txt"
#define LOG_FILE                 "security.log"

#define CALIBRATION_WEIGHT       10000
#define THRESHOLD_WEIGHT         5000

#define ARRAY_SIZE(a)            (sizeof(a) / sizeof((a)[0]))

static volatile uint8_t *gpio;

static int fd;

static void
hx711_clock_delay(void)
{
    struct timespec ts = {
        .tv_sec = 0,
        .tv_nsec = HX711_CLOCK_DELAY_US * 1000,
    };

    nanosleep(&ts, NULL);
}

static void
hx711_data_timeout(void)
{
    struct timespec ts = {
        .tv_sec = 0,
        .tv_nsec = HX711_DATA_TIMEOUT_US * 1000,
    };

    nanosleep(&ts, NULL);
}

static int
hx711_read(void)
{
    int i;
    int value = 0;

    HX711_DATA_HIGH();
    hx711_clock_delay();

    for (i = 0; i < 24; i++) {
        HX711_CLOCK_HIGH();
        hx711_clock_delay();

        value <<= 1;

        if (HX711_DATA_READ()) {
            value |= 1;
        }

        HX711_CLOCK_LOW();
        hx711_clock_delay();
    }

    HX711_CLOCK_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_LOW();
    hx711_clock_delay();

    return value;
}

static int
hx711_read_timeout(void)
{
    int value;

    HX711_DATA_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_LOW();
    hx711_clock_delay();

    value = hx711_read();

    if (HX711_DATA_READ()) {
        hx711_data_timeout();
    }

    return value;
}

static int
hx711_read_average(int samples)
{
    int i;
    int value = 0;

    for (i = 0; i < samples; i++) {
        value += hx711_read_timeout();
    }

    return value / samples;
}

static int
hx711_read_calibration(void)
{
    int value;

    value = hx711_read_average(10);

    return value;
}

static int
hx711_read_weight(int calibration)
{
    int value;

    value = hx711_read_average(10);

    value -= calibration;

    return value;
}

static void
hx711_init(void)
{
    HX711_DATA_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_LOW();
    hx711_clock_delay();
}

static void
gpio_init(void)
{
    int fd;
    int i;

    fd = open("/dev/gpiomem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    gpio = mmap(NULL, BLOCK_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (gpio == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < 32; i++) {
        GPIO_PULLCLK0 = 0;
    }
}

static void
gpio_cleanup(void)
{
    munmap(gpio, BLOCK_SIZE);
    close(fd);
}

static void
solenoid_init(void)
{
    SOLENOID_LOW();
}

static void
solenoid_lock(void)
{
    SOLENOID_HIGH();
    sleep(SOLENOID_DELAY_S);
    SOLENOID_LOW();
}

static void
log_weight(int weight)
{
    FILE *fp;
    time_t t;
    struct tm *tm;
    char buf[64];

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    t = time(NULL);
    tm = localtime(&t);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %d\n", buf, weight);

    fclose(fp);
}

static void
sigint_handler(int sig)
{
    solenoid_lock();
    gpio_cleanup();
    exit(EXIT_SUCCESS);
}

int
main(int argc, char *argv[])
{
    int calibration;
    int weight;

    signal(SIGINT, sigint_handler);

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    gpio_init();
    hx711_init();
    solenoid_init();

    printf("Place a known weight on the sensor and press enter: ");
    getchar();

    calibration = hx711_read_calibration();

    printf("Calibration value: %d\n", calibration);

    FILE *fp;

    fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%d\n", calibration);

    fclose(fp);

    while (1) {
        weight = hx711_read_weight(calibration);

        if (weight > THRESHOLD_WEIGHT) {
            solenoid_lock();
            log_weight(weight);
        }
    }

    return 0;
}

