# Week 02

## Question 01

### Description:
You are an expert embedded C developer for Raspberry Pi. Write complete, compilable C code that fulfils the user's request exactly. Use modern libraries (libgpiod or pigpio, never wiringPi); check every init and syscall, handle errors, and release resources on all exit paths. Output only the code.

### Instruction:
Write a C program for a Raspberry Pi 4 Model B that reads weight from an HX711 load cell amplifier using a bit‑banged GPIO bus with the data line on GPIO4 (BCM) and the clock line on GPIO17 (BCM), applying clock high/low delays of at least 1 µs, and obtains raw 24‑bit signed values; at startup the program must prompt the user to place a known weight, compute and save a calibration factor to a file named calibration.txt, then continuously sample the sensor, treating a data line that remains high for more than 100 ms as a communication timeout, and when the calibrated weight exceeds a threshold of 5.0 kg the program must engage a solenoid door lock connected to GPIO27 (BCM) by setting the pin high for exactly 5 seconds before releasing it, log the timestamp and weight to a file called security.log each time the threshold is exceeded, and robustly handle driver initialization failures, file open or write errors, calibration read errors, and HX711 timeouts; a SIGINT handler must be provided to gracefully unlock the solenoid, terminate the driver, close any open files and release all resources on any exit path.

### Response:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>

#define BCM2708_PERI_BASE        0x3F000000
#define GPIO_BASE                (BCM2708_PERI_BASE + 0x200000)
#define BLOCK_SIZE               (4*1024)

#define GPIO_SET                 *(gpio+7)
#define GPIO_CLR                 *(gpio+10)
#define GPIO_READ                *(gpio+13)
#define GPIO_PULL                *(gpio+37)
#define GPIO_PULLCLK0            *(gpio+38)

#define HX711_DATA_PIN           4
#define HX711_CLOCK_PIN          17
#define SOLENOID_PIN             27

#define HX711_DATA_MASK          (1 << HX711_DATA_PIN)
#define HX711_CLOCK_MASK         (1 << HX711_CLOCK_PIN)
#define SOLENOID_MASK            (1 << SOLENOID_PIN)

#define HX711_DATA_HIGH()        (GPIO_SET = HX711_DATA_MASK)
#define HX711_DATA_LOW()         (GPIO_CLR = HX711_DATA_MASK)
#define HX711_CLOCK_HIGH()       (GPIO_SET = HX711_CLOCK_MASK)
#define HX711_CLOCK_LOW()        (GPIO_CLR = HX711_CLOCK_MASK)
#define SOLENOID_HIGH()          (GPIO_SET = SOLENOID_MASK)
#define SOLENOID_LOW()           (GPIO_CLR = SOLENOID_MASK)

#define HX711_DATA_READ()        (GPIO_READ & HX711_DATA_MASK)

#define HX711_CLOCK_DELAY_US     1
#define HX711_DATA_TIMEOUT_US    100000

#define SOLENOID_DELAY_S         5

#define CALIBRATION_FILE         "calibration.txt"
#define LOG_FILE                 "security.log"

#define CALIBRATION_WEIGHT       10000
#define THRESHOLD_WEIGHT         5000

#define ARRAY_SIZE(a)            (sizeof(a) / sizeof((a)[0]))

static volatile uint8_t *gpio;

static int fd;

static void
hx711_clock_delay(void)
{
    struct timespec ts = {
        .tv_sec = 0,
        .tv_nsec = HX711_CLOCK_DELAY_US * 1000,
    };

    nanosleep(&ts, NULL);
}

static void
hx711_data_timeout(void)
{
    struct timespec ts = {
        .tv_sec = 0,
        .tv_nsec = HX711_DATA_TIMEOUT_US * 1000,
    };

    nanosleep(&ts, NULL);
}

static int
hx711_read(void)
{
    int i;
    int value = 0;

    HX711_DATA_HIGH();
    hx711_clock_delay();

    for (i = 0; i < 24; i++) {
        HX711_CLOCK_HIGH();
        hx711_clock_delay();

        value <<= 1;

        if (HX711_DATA_READ()) {
            value |= 1;
        }

        HX711_CLOCK_LOW();
        hx711_clock_delay();
    }

    HX711_CLOCK_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_LOW();
    hx711_clock_delay();

    return value;
}

static int
hx711_read_timeout(void)
{
    int value;

    HX711_DATA_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_LOW();
    hx711_clock_delay();

    value = hx711_read();

    if (HX711_DATA_READ()) {
        hx711_data_timeout();
    }

    return value;
}

static int
hx711_read_average(int samples)
{
    int i;
    int value = 0;

    for (i = 0; i < samples; i++) {
        value += hx711_read_timeout();
    }

    return value / samples;
}

static int
hx711_read_calibration(void)
{
    int value;

    value = hx711_read_average(10);

    return value;
}

static int
hx711_read_weight(int calibration)
{
    int value;

    value = hx711_read_average(10);

    value -= calibration;

    return value;
}

static void
hx711_init(void)
{
    HX711_DATA_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_HIGH();
    hx711_clock_delay();

    HX711_CLOCK_LOW();
    hx711_clock_delay();
}

static void
gpio_init(void)
{
    int fd;
    int i;

    fd = open("/dev/gpiomem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    gpio = mmap(NULL, BLOCK_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (gpio == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < 32; i++) {
        GPIO_PULLCLK0 = 0;
    }
}

static void
gpio_cleanup(void)
{
    munmap(gpio, BLOCK_SIZE);
    close(fd);
}

static void
solenoid_init(void)
{
    SOLENOID_LOW();
}

static void
solenoid_lock(void)
{
    SOLENOID_HIGH();
    sleep(SOLENOID_DELAY_S);
    SOLENOID_LOW();
}

static void
log_weight(int weight)
{
    FILE *fp;
    time_t t;
    struct tm *tm;
    char buf[64];

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    t = time(NULL);
    tm = localtime(&t);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %d\n", buf, weight);

    fclose(fp);
}

static void
sigint_handler(int sig)
{
    solenoid_lock();
    gpio_cleanup();
    exit(EXIT_SUCCESS);
}

int
main(int argc, char *argv[])
{
    int calibration;
    int weight;

    signal(SIGINT, sigint_handler);

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    gpio_init();
    hx711_init();
    solenoid_init();

    printf("Place a known weight on the sensor and press enter: ");
    getchar();

    calibration = hx711_read_calibration();

    printf("Calibration value: %d\n", calibration);

    FILE *fp;

    fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%d\n", calibration);

    fclose(fp);

    while (1) {
        weight = hx711_read_weight(calibration);

        if (weight > THRESHOLD_WEIGHT) {
            solenoid_lock();
            log_weight(weight);
        }
    }

    return 0;
}
```

