#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    int lastState = -1;
    while (keepRunning) {
        int sensorState = gpioRead(SENSOR_PIN);
        if (sensorState < 0) {
            fprintf(stderr, "Failed to read sensor state: %s\n", strerror(errno));
            break;
        }

        if (sensorState != lastState) {
            time_t currentTime = time(NULL);
            struct tm *localTime = localtime(&currentTime);
            char timeString[32];
            strftime(timeString, sizeof(timeString), "%FT%TZ", localTime);

            int relayState = sensorState == 0 ? 1 : 0;
            gpioWrite(RELAY_PIN, relayState);

            fprintf(logFile, "%s: %s\n", timeString, relayState == 1 ? "ON" : "OFF");
            fflush(logFile);

            lastState = sensorState;
        }

        gpioDelay(100000);
    }

    fclose(logFile);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "motion_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *pir_line, *buzzer_line;

void sig_handler(int signo)
{
    if (signo == SIGINT || signo == SIGTERM) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main(void)
{
    int ret;
    FILE *log_file;
    struct timespec ts;
    char timestamp[20];

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        fprintf(stderr, "Error getting PIR GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(pir_line, "motion_detector");
    if (ret < 0) {
        fprintf(stderr, "Error requesting PIR GPIO line: %s\n", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer GPIO line: %s\n", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(buzzer_line, "motion_detector", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer GPIO line: %s\n", strerror(errno));
        gpiod_line_release(buzzer_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(buzzer_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        ret = gpiod_line_event_wait(pir_line, -1);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for PIR GPIO line event: %s\n", strerror(errno));
            break;
        }

        if (gpiod_line_event_read(pir_line) == 1) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%F %T", gmtime(&ts.tv_sec));
