#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define I2C_REG 0x00
#define I2C_LEN 2
#define I2C_RETRIES 3
#define I2C_DELAY 100000
#define I2C_TIMEOUT 1000
#define I2C_BUF_LEN 1024
#define LOG_FILE "airflow_log.txt"
#define LOG_BUF_LEN 1024

static int i2c_fd = -1;
static int log_fd = -1;
static int running = 1;

static void sigint_handler(int signum)
{
    running = 0;
}

static int i2c_open(void)
{
    int fd;
    int ret;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    ret = ioctl(fd, I2C_TIMEOUT, I2C_TIMEOUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C timeout: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    ret = ioctl(fd, I2C_RETRIES, I2C_RETRIES);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C retries: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    int ret;
    int retries = 0;

    while (retries < I2C_RETRIES) {
        ret = read(fd, buf, len);
        if (ret == len) {
            return 0;
        } else if (ret < 0) {
            if (errno == EAGAIN) {
                usleep(I2C_DELAY);
                retries++;
            } else {
                fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
                return -1;
            }
        } else {
            fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
    return -1;
}

static int log_open(void)
{
    int fd;

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return fd;
}

static int log_write(int fd, const char *buf, size_t len)
{
    int ret;

    ret = write(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_close(int fd)
{
    int ret;

    ret = close(fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_entry(int fd, uint16_t flow)
{
    char buf[LOG_BUF_LEN];
    time_t t;
    struct tm *tm;

    t = time(NULL);
    tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Failed to get local time: %s\n", strerror(errno));
        return -1;
    }

    snprintf(buf, LOG_BUF_LEN, "%04d-%02d-%02d %02d:%02d:%02d %d\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, flow);

    return log_write(fd, buf, strlen(buf));
}

int main(void)
{
    uint8_t i2c_buf[I2C_BUF_LEN];
    uint16_t flow;
    int ret;

    signal(SIGINT, sigint_handler);

    i2c_fd = i2c_open();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    log_fd = log_open();
    if (log_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        ret = i2c_read(i2c_fd, i2c_buf, I2C_LEN);
        if (ret < 0) {
            break;
        }

        flow = (i2c_buf[0] << 8) | i2c_buf[1];
        flow &= 0x3FFF;
        flow *= 100;

        ret = log_entry(log_fd, flow);
        if (ret < 0) {
            break;
        }

        sleep(1);
    }

    log_close(log_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

