    while (retries < I2C_RETRIES) {
        ret = read(fd, buf, len);
        if (ret == len) {
            return 0;
        } else if (ret < 0) {
            if (errno == EAGAIN) {
                usleep(I2C_DELAY);
                retries++;
            } else {
                fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
                return -1;
            }
        } else {
            fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
            return -1;
