    req_middle.lineoffsets[0] = GPIO_MIDDLE;
    req_middle.flags = GPIOHANDLE_REQUEST_INPUT;
    req_middle.default_values[0] = 0;
    req_middle.lines = 1;
    req_middle.fd = -1;

