    if (gpio_fd_middle < 0) {
        perror("Failed to open /dev/gpiochip0");
        return 1;
    }

    gpio_fd_right = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd_right < 0) {
        perror("Failed to open /dev/gpiochip0");
        return 1;
    }

    if (ioctl(gpio_fd_left, GPIO_GET_LINEHANDLE_IOCTL, &req_left) < 0) {
        perror("Failed to get line handle for GPIO_LEFT");
        return 1;
    }

    if (ioctl(gpio_fd_middle, GPIO_GET_LINEHANDLE_IOCTL, &req_middle) < 0) {
        perror("Failed to get line handle for GPIO_MIDDLE");
        return 1;
    }

    if (ioctl(gpio_fd_right, GPIO_GET_LINEHANDLE_IOCTL, &req_right) < 0) {
        perror("Failed to get line handle for GPIO_RIGHT");
        return 1;
    }

    // Set up UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("Failed to open UART device");
        return 1;
    }

    tcgetattr(uart_fd, &uart_config);
    cfsetispeed(&uart_config, BAUDRATE);
    cfsetospeed(&uart_config, BAUDRATE);
    uart_config.c_cflag |= (CLOCAL | CREAD);
    uart_config.c_cflag &= ~PARENB;
    uart_config.c_cflag &= ~CSTOPB;
    uart_config.c_cflag &= ~CSIZE;
    uart_config.c_cflag |= CS8;
    uart_config.c_cflag &= ~CRTSCTS;
    uart_config.c_iflag &= ~(IXON | IXOFF | IXANY);
    uart_config.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    uart_config.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &uart_config);

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read GPIO values
        if (read(req_left.fd, &gpio_value_left, sizeof(gpio_value_left)) < 0) {
            perror("Failed to read GPIO_LEFT");
            return 1;
        }

        if (read(req_middle.fd, &gpio_value_middle, sizeof(gpio_value_middle)) < 0) {
            perror("Failed to read GPIO_MIDDLE");
            return 1;
        }

        if (read(req_right.fd, &gpio_value_right, sizeof(gpio_value_right)) < 0) {
            perror("Failed to read GPIO_RIGHT");
            return 1;
        }

        // Log sensor states
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: %d %d %d\n", ts.tv_sec, ts.tv_nsec, gpio_value_left, gpio_value_middle, gpio_value_right);

        // Check for emergency stop
        if (gpio_value_left == 0 && gpio_value_middle == 0 && gpio_value_right == 0) {
            uart_buffer_len = sprintf(uart_buffer, "%s", EMERGENCY_STOP);
            if (write(uart_fd, uart_buffer, uart_buffer_len) < 0) {
                perror("Failed to write to UART device");
            }
        }

        // Sleep for 100ms
        usleep(100000);
    }

    return 0;
}
